INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23deeeb0-58ff-4e9d-8464-ad71bd230433', '巴西聞收宮闕送班司馬入京', '巴西闻收宮闕送班司马入京', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["聞道收宗廟，鳴鑾自陝歸。","傾都看黃屋，正殿引朱衣。","劒外春天遠，巴西敕使稀。","念君輕世亂，匹馬向王畿。"]', '["闻道收宗廟，鳴鑾自陝归。","傾都看黄屋，正殿引朱衣。","劒外春天远，巴西敕使稀。","念君轻世亂，匹马向王畿。"]', '诗', 'shi', '', NULL, '巴西聞收宮闕送班司馬入京 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe45650e-1ae7-4cbd-8106-ba3c09edefeb', '花底', '花底', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["紫蕚扶千蘂，黃鬚照萬花。","忽疑行暮雨，何事入朝霞。","恐是潘安縣，堪留衛玠車。","深知好顏色，莫作委泥沙。"]', '["紫蕚扶千蘂，黄鬚照万花。","忽疑行暮雨，何事入朝霞。","恐是潘安縣，堪留衛玠车。","深知好顏色，莫作委泥沙。"]', '诗', 'shi', '', NULL, '花底 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c06c6f1d-b88f-4169-8df1-6aea35110ec1', '柳邊', '柳邊', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["只道梅花發，那知柳亦新。","枝枝總到地，葉葉自開春。","紫燕時飜翼，黃鸝不露身。","漢南應老盡，霸上遠愁人。"]', '["只道梅花發，那知柳亦新。","枝枝總到地，葉葉自开春。","紫燕时飜翼，黄鸝不露身。","漢南應老尽，霸上远愁人。"]', '诗', 'shi', '', NULL, '柳邊 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f76dcec1-ab9d-432e-a10c-da58ae8ad0b1', '送竇九歸成都', '送竇九归成都', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["文章亦不盡，竇子才縱橫。","非爾更苦節，何人符大名。","讀書雲閣觀，問絹錦官城。","我有浣花竹，題詩須一行。"]', '["文章亦不尽，竇子才縱橫。","非爾更苦節，何人符大名。","读书云閣观，问絹錦官城。","我有浣花竹，題诗須一行。"]', '诗', 'shi', '', NULL, '送竇九歸成都 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5312939e-9860-410f-b72b-da8477a2f370', '贈裴南部聞袁判官自來欲有按問', '贈裴南部闻袁判官自来欲有按问', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["塵滿萊蕪甑，堂橫單父琴。","人皆知飲水，公輩不偷金。","梁獄書因上，秦臺鏡欲臨。","獨醒時所嫉，羣小謗能深。","即出黃沙在，何須白髮侵。","使君傳舊德，已見直繩心。"]', '["塵满萊蕪甑，堂橫單父琴。","人皆知饮水，公輩不偷金。","梁獄书因上，秦台镜欲臨。","独醒时所嫉，羣小謗能深。","即出黄沙在，何須白髮侵。","使君傳旧德，已见直繩心。"]', '诗', 'shi', '', NULL, '贈裴南部聞袁判官自來欲有按問 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91177514-d91b-4944-b496-b0f269c71a11', '奉使崔都水翁下峽', '奉使崔都水翁下峽', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["無數涪江筏，鳴橈總發時。","別離終不久，宗族忍相遺。","白狗黃牛峽，朝雲暮雨祠。","所過頻問訊，到日自題詩。"]', '["無數涪江筏，鳴橈總發时。","別離終不久，宗族忍相遺。","白狗黄牛峽，朝云暮雨祠。","所過頻问訊，到日自題诗。"]', '诗', 'shi', '', NULL, '奉使崔都水翁下峽 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4010d4c-2722-4642-b637-2cf560582ceb', '題郪縣郭三十二明府茅屋壁', '題郪縣郭三十二明府茅屋壁', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江頭且繫船，爲爾獨相憐。","雲散灌壇雨，春青彭澤田。","頻驚適小國，一擬問高天。","別後巴東路，逢人問幾賢。"]', '["江头且繫船，爲爾独相怜。","云散灌壇雨，春青彭澤田。","頻驚適小国，一擬问高天。","別後巴东路，逢人问幾賢。"]', '诗', 'shi', '', NULL, '題郪縣郭三十二明府茅屋壁 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7eef5518-c3df-4603-90f6-c27d3beb8e4e', '遣悶戲呈路十九曹長', '遣悶戲呈路十九曹长', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江浦雷聲喧昨夜，春城雨色動微寒。","黃鸝竝坐交愁濕，白鷺羣飛大劇乾。","晚節漸於詩律細，誰家數去酒杯寬。","惟吾最愛清狂客，百徧向看意未闌。"]', '["江浦雷声喧昨夜，春城雨色动微寒。","黄鸝竝坐交愁濕，白鷺羣飞大劇乾。","晚節漸於诗律細，誰家數去酒杯寬。","惟吾最愛清狂客，百徧向看意未闌。"]', '诗', 'shi', '', NULL, '遣悶戲呈路十九曹長 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fddb5609-2370-40d9-bac7-cc918bd325da', '隨章留後新亭會送諸君', '隨章留後新亭會送諸君', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["新亭有高會，行子得良時。","日動映江幕，風鳴排檻旗。","絕葷終不改，勸酒欲無詞。","已墮峴山淚，因題零雨詩。"]', '["新亭有高會，行子得良时。","日动映江幕，风鳴排檻旗。","絕葷終不改，勸酒欲無词。","已墮峴山泪，因題零雨诗。"]', '诗', 'shi', '', NULL, '隨章留後新亭會送諸君 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2922969a-0b64-4b76-8b6c-6439d02abde9', '東津送韋諷攝閬州錄事', '东津送韋諷攝閬州錄事', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["聞說江山好，憐君吏隱兼。","寵行舟遠泛，怯別酒頻添。","推薦非承乏，操持必去嫌。","他時如按縣，不得慢陶潛。"]', '["闻说江山好，怜君吏隐兼。","寵行舟远泛，怯別酒頻添。","推薦非承乏，操持必去嫌。","他时如按縣，不得慢陶潛。"]', '诗', 'shi', '', NULL, '東津送韋諷攝閬州錄事 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3e95b39-e022-478a-ab92-a7f7a5fd12e4', '客舊館', '客旧館', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["陳迹隨人事，初秋別此亭。","重來棃葉赤，依舊竹林青。","風幔何時卷，寒砧昨夜聲。","無由出江漢，愁緒月冥冥。"]', '["陳迹隨人事，初秋別此亭。","重来棃葉赤，依旧竹林青。","风幔何时卷，寒砧昨夜声。","無由出江漢，愁緒月冥冥。"]', '诗', 'shi', '', NULL, '客舊館 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc83eaf8-ab69-4f5c-9c06-69c67cd72651', '閬州奉送二十四舅使自京赴任青城', '閬州奉送二十四舅使自京赴任青城', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["聞道王喬舄，名因太史傳。","如何碧雞使，把詔紫微天。","秦嶺愁回馬，涪江醉泛船。","青城漫污雜，吾舅意淒然。"]', '["闻道王喬舄，名因太史傳。","如何碧雞使，把詔紫微天。","秦嶺愁回马，涪江醉泛船。","青城漫污杂，吾舅意淒然。"]', '诗', 'shi', '', NULL, '閬州奉送二十四舅使自京赴任青城 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d5ba079-7c3a-4b81-a2f0-4610ecf38b2b', '愁坐', '愁坐', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["高齋常見野，愁坐更臨門。","十月山寒重，孤城月水昏。","葭萌氐種迥，左擔犬戎存。","終日憂奔走，歸期未敢論。"]', '["高斋常见野，愁坐更臨门。","十月山寒重，孤城月水昏。","葭萌氐種迥，左擔犬戎存。","終日憂奔走，归期未敢論。"]', '诗', 'shi', '', NULL, '愁坐 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('179a54b5-59cf-40f3-8fae-63d317331dce', '陪鄭公秋晚北池臨眺', '陪鄭公秋晚北池臨眺', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["北池雲水闊，華館闢秋風。","獨鶴元依渚，衰荷且映空。","采菱寒刺上，蹋藕野泥中。","素檝分曹往，金盤小徑通。","萋萋露草碧，片片晚旗紅。","杯酒霑津吏，衣裳與釣翁。","異方初豔菊，故里亦高桐。","搖落關山思，淹留戰伐功。","嚴城殊未掩，清宴已知終。","何補參卿事，歡娛到薄躬。"]', '["北池云水闊，华館闢秋风。","独鹤元依渚，衰荷且映空。","采菱寒刺上，蹋藕野泥中。","素檝分曹往，金盤小徑通。","萋萋露草碧，片片晚旗紅。","杯酒霑津吏，衣裳與釣翁。","異方初豔菊，故里亦高桐。","搖落关山思，淹留戰伐功。","嚴城殊未掩，清宴已知終。","何補參卿事，歡娛到薄躬。"]', '诗', 'shi', '', NULL, '陪鄭公秋晚北池臨眺 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b961a873-0d3a-4be4-afbe-14b127e48d06', '去蜀', '去蜀', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["五載客蜀郡，一年居梓州。","如何關塞阻，轉作瀟湘游。","世事已黃髮，殘生隨白鷗。","安危大臣在，不必淚長流。"]', '["五載客蜀郡，一年居梓州。","如何关塞阻，轉作瀟湘游。","世事已黄髮，殘生隨白鷗。","安危大臣在，不必泪长流。"]', '诗', 'shi', '', NULL, '去蜀 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('014b2ad0-4cb1-43fb-9901-35e3650f105f', '放船', '放船', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["收帆下急水，卷幔逐回灘。","江市戎戎暗，山雲淰淰寒。","村荒無徑入，獨鳥怪人看。","已泊城樓底，何曾夜色闌。"]', '["收帆下急水，卷幔逐回灘。","江市戎戎暗，山云淰淰寒。","村荒無徑入，独鸟怪人看。","已泊城楼底，何曾夜色闌。"]', '诗', 'shi', '', NULL, '放船 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65c98846-6b8b-4319-a10e-d3c5c0fde249', '哭台州鄭司戶蘇少監', '哭台州鄭司戶蘇少監', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["故舊誰憐我，平生鄭與蘇。","存亡不重見，喪亂獨前途。","豪俊何人在，文章埽地無。","羇遊萬里闊，凶問一年俱。","白首中原上，清秋大海隅。","夜臺當北斗，泉路著東吳。","得罪台州去，時危棄碩儒。","移官蓬閣後，穀貴沒潛夫。","流慟嗟何及，銜冤有是夫。","道消詩興廢，心息酒爲徒。","許與才雖薄，追誰跡未拘。","班揚名甚盛，嵇阮逸相須。","會取君臣合，寧銓品命殊。","賢良不必展，廊廟偶然趨。","勝決風塵際，功安造化鑪。","從容拘舊學，慘澹閟陰符。","擺落嫌疑久，哀傷志力輸。","俗依緜谷異，客對雪山孤。","童稚思諸子，交朋列友于。","情乖清酒送，望絕撫墳呼。","瘧病餐巴水，瘡痍老蜀都。","飄零迷哭處，天地日榛蕪。"]', '["故旧誰怜我，平生鄭與蘇。","存亡不重见，喪亂独前途。","豪俊何人在，文章埽地無。","羇游万里闊，凶问一年俱。","白首中原上，清秋大海隅。","夜台當北斗，泉路著东吳。","得罪台州去，时危棄碩儒。","移官蓬閣後，穀貴沒潛夫。","流慟嗟何及，銜冤有是夫。","道消诗兴廢，心息酒爲徒。","許與才雖薄，追誰跡未拘。","班揚名甚盛，嵇阮逸相須。","會取君臣合，寧銓品命殊。","賢良不必展，廊廟偶然趨。","勝決风塵際，功安造化鑪。","從容拘旧学，慘澹閟陰符。","擺落嫌疑久，哀傷志力輸。","俗依緜谷異，客对雪山孤。","童稚思諸子，交朋列友于。","情乖清酒送，望絕撫墳呼。","瘧病餐巴水，瘡痍老蜀都。","飄零迷哭处，天地日榛蕪。"]', '诗', 'shi', '', NULL, '哭台州鄭司戶蘇少監 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f41f729c-f562-4abf-9706-57067fcc0135', '送王侍御往東川放生池祖席', '送王侍御往东川放生池祖席', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["東川詩友合，此贈怯輕爲。","況復傳宗近，空然惜別離。","梅花交近野，草色向平池。","儻憶江邊臥，歸期願早知。"]', '["东川诗友合，此贈怯轻爲。","況复傳宗近，空然惜別離。","梅花交近野，草色向平池。","儻憶江邊臥，归期願早知。"]', '诗', 'shi', '', NULL, '送王侍御往東川放生池祖席 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66c98290-0989-44c8-9f45-1342193ff3b8', '惠義寺送王少尹赴成都', '惠義寺送王少尹赴成都', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["苒苒谷中寺，娟娟林表峰。","闌干上處遠，結構坐來重。","騎馬行春徑，衣冠起晚鐘。","雲門青寂寂，此別惜相從。"]', '["苒苒谷中寺，娟娟林表峰。","闌干上处远，結構坐来重。","騎马行春徑，衣冠起晚鐘。","云门青寂寂，此別惜相從。"]', '诗', 'shi', '', NULL, '惠義寺送王少尹赴成都 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6532c143-b684-4399-abfa-4edc7e8de03c', '避地', '避地', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["避地歲時晚，竄身筋骨勞。","詩書遂牆壁，奴僕且旌旄。","行在僅聞信，此生隨所遭。","神堯舊天下，會見出腥臊。"]', '["避地歲时晚，竄身筋骨勞。","诗书遂牆壁，奴僕且旌旄。","行在僅闻信，此生隨所遭。","神堯旧天下，會见出腥臊。"]', '诗', 'shi', '', NULL, '避地 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e5493f5-221b-4d85-b367-a36cf73f5645', '惠義寺園送辛員外', '惠義寺园送辛員外', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["朱櫻此日垂朱實，郭外誰家負郭田。","萬里相逢貪握手，高才却望足離筵。"]', '["朱櫻此日垂朱實，郭外誰家負郭田。","万里相逢貪握手，高才却望足離筵。"]', '诗', 'shi', '', NULL, '惠義寺園送辛員外 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('086d35f6-842f-46fc-a942-87669c4278ff', '又送', '又送', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["雙峰寂寂對春臺，萬竹青青照客杯。","細草留連侵坐輭，殘花悵望近人開。","同舟昨日何由得，竝馬今朝未擬迴。","直到緜州始分首，江邊樹裏共誰來。"]', '["雙峰寂寂对春台，万竹青青照客杯。","細草留連侵坐輭，殘花悵望近人开。","同舟昨日何由得，竝马今朝未擬迴。","直到緜州始分首，江邊樹裏共誰来。"]', '诗', 'shi', '', NULL, '又送 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49ba8a46-b588-44fe-8415-e86c3bd6e61e', '九日登梓州城', '九日登梓州城', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["客心驚暮序，賓雁下襄州。","共賞重陽節，言尋戲馬遊。","湖風秋戍柳，江雨暗山樓。","且酌東籬菊，聊祛南國愁。"]', '["客心驚暮序，賓雁下襄州。","共賞重陽節，言尋戲马游。","湖风秋戍柳，江雨暗山楼。","且酌东籬菊，聊祛南国愁。"]', '诗', 'shi', '', NULL, '九日登梓州城 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5044be6-11b0-44c7-8480-17a31e0b4637', '闕題', '闕題', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["三月雪連夜，未應傷物華。","只緣春欲盡，留著伴棃花。"]', '["三月雪連夜，未應傷物华。","只緣春欲尽，留著伴棃花。"]', '诗', 'shi', '', NULL, '闕題 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0588679-461e-449d-9758-01d6bc1f6e9d', '句', '句', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["寒食少天氣，東風多柳花。","小桃知客意，春盡始開花。"]', '["寒食少天氣，东风多柳花。","小桃知客意，春尽始开花。"]', '诗', 'shi', '', NULL, '句 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a64899a4-3471-40d4-a63a-336d1b9145c0', '自蜀奉冊命往朔方途中呈韋左相文部房尚書門下崔侍郎', '自蜀奉冊命往朔方途中呈韋左相文部房尚书门下崔侍郎', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["胡羯亂中夏，鑾輿忽南巡。","衣冠陷戎寇，狼狽隨風塵。","豳公秉大節，臨難不顧身。","激昂白刃前，濺血下沾巾。","尚書抱忠義，歷險披荆榛。","扈從出劍門，登翼岷江濱。","時望挹侍郎，公才標縉紳。","亭亭崑山玉，皎皎無緇磷。","顧惟乏經濟，扞牧陪從臣。","永願雪會稽，仗劍清咸秦。","太皇時內禪，神器付嗣君。","新命集舊邦，至德被遠人。","捧冊自南服，奉詔趨北軍。","覲謁心載馳，違離難重陳。","策馬出蜀山，畏途上緣雲。","飲啄叢箐間，棲息虎豹羣。","崎嶇凌危棧，惴慄驚心神。","峭壁上嶔岑，大江下沄沄。","皇風扇八極，異類懷深仁。","元兇誘黠虜，肘腋生妖氛。","明主信英武，威聲赫四鄰。","誓師自朔方，旗幟何繽紛。","鐵騎照白日，旄頭拂秋旻。","將來蕩滄溟，寧止蹴崑崙。","古來有屯難，否泰長相因。","夏康纘禹績，代祖復漢勳。","于役各勤王，驅馳拱紫宸。","豈惟太公望，往昔逢周文。","誰謂三傑才，功業獨殊倫。","感此慰行邁，無爲歌苦辛。"]', '["胡羯亂中夏，鑾輿忽南巡。","衣冠陷戎寇，狼狽隨风塵。","豳公秉大節，臨难不顧身。","激昂白刃前，濺血下沾巾。","尚书抱忠義，歷險披荆榛。","扈從出劍门，登翼岷江濱。","时望挹侍郎，公才標縉紳。","亭亭崑山玉，皎皎無緇磷。","顧惟乏經濟，扞牧陪從臣。","永願雪會稽，仗劍清咸秦。","太皇时內禪，神器付嗣君。","新命集旧邦，至德被远人。","捧冊自南服，奉詔趨北軍。","覲謁心載驰，違離难重陳。","策马出蜀山，畏途上緣云。","饮啄叢箐间，棲息虎豹羣。","崎嶇凌危棧，惴慄驚心神。","峭壁上嶔岑，大江下沄沄。","皇风扇八極，異類懷深仁。","元兇誘黠虜，肘腋生妖氛。","明主信英武，威声赫四鄰。","誓師自朔方，旗幟何繽紛。","鐵騎照白日，旄头拂秋旻。","將来蕩滄溟，寧止蹴崑崙。","古来有屯难，否泰长相因。","夏康纘禹績，代祖复漢勳。","于役各勤王，驱驰拱紫宸。","豈惟太公望，往昔逢周文。","誰謂三傑才，功業独殊倫。","感此慰行邁，無爲歌苦辛。"]', '诗', 'shi', '', NULL, '自蜀奉冊命往朔方途中呈韋左相文部房尚書門下崔侍郎 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97c98650-151d-4c52-8504-1e6c66820058', '贈裴九侍御昌江草堂彈琴', '贈裴九侍御昌江草堂彈琴', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["朔風吹疎林，積雪在崖巘。","鳴琴草堂響，小澗清且淺。","沈吟東山意，欲去芳歲晚。","悵望黃綺心，白雲若在眼。"]', '["朔风吹疎林，積雪在崖巘。","鳴琴草堂响，小澗清且淺。","沈吟东山意，欲去芳歲晚。","悵望黄綺心，白云若在眼。"]', '诗', 'shi', '', NULL, '贈裴九侍御昌江草堂彈琴 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7edf3f0-b1d7-4f79-9b9d-4776b0444b3b', '巴陵早秋寄荆州崔司馬吏部閻功曹舍人', '巴陵早秋寄荆州崔司马吏部閻功曹舍人', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["謫居瀟湘渚，再見洞庭秋。","極目連江漢，西南浸斗牛。","滔滔盪雲夢，澹澹搖巴丘。","曠如臨渤澥，窅疑造瀛洲。","君山麗中波，蒼翠長夜浮。","帝子去永久，楚詞尚悲秋。","我同長沙行，時事加百憂。","登高望舊國，胡馬滿東周。","宛葉徧蓬蒿，樊鄧無良疇。","獨攀青楓樹，淚灑滄江流。","故人西掖寮，同扈岐陽蒐。","差池盡三黜，蹭蹬各南州。","相去雖地接，不得從之遊。","耿耿雲陽臺，迢迢王粲樓。","跂予暮霞裏，誰謂無輕舟。"]', '["謫居瀟湘渚，再见洞庭秋。","極目連江漢，西南浸斗牛。","滔滔盪云梦，澹澹搖巴丘。","曠如臨渤澥，窅疑造瀛洲。","君山丽中波，蒼翠长夜浮。","帝子去永久，楚词尚悲秋。","我同长沙行，时事加百憂。","登高望旧国，胡马满东周。","宛葉徧蓬蒿，樊鄧無良疇。","独攀青楓樹，泪灑滄江流。","故人西掖寮，同扈岐陽蒐。","差池尽三黜，蹭蹬各南州。","相去雖地接，不得從之游。","耿耿云陽台，迢迢王粲楼。","跂予暮霞裏，誰謂無轻舟。"]', '诗', 'shi', '', NULL, '巴陵早秋寄荆州崔司馬吏部閻功曹舍人 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bdc6196-a895-47f1-9ea1-23acfef229b4', '閑居秋懷寄陽翟陸贊府封丘高少府', '闲居秋懷寄陽翟陸贊府封丘高少府', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["今日霖雨霽，颯然高館涼。","秋風吹二毛，烈士加慨慷。","憶昔皇運初，衆賓俱龍驤。","解巾佐幕府，脫劍升明堂。","郁郁被慶雲，昭昭翼太陽。","鯨魚縱大壑，鸑鷟鳴高岡。","信矣草創時，泰階速賢良。","一言頓遭逢，片善蒙恩光。","我生屬聖明，感激竊自彊。","崎嶇郡邑權，連騫翰墨場。","天朝富英髦，多士如珪璋。","盛才溢下位，蹇步徒猖狂。","閉門對羣書，几案在我旁。","枕席相遠遊，聊欲浮滄浪。","八月白露降，玄蟬號枯桑。","艤舟臨清川，迢遞愁思長。","我有同懷友，各在天一方。","離披不相見，浩蕩隔兩鄉。","平生霞外期，宿昔共行藏。","豈無蓬萊樹，歲晏空蒼蒼。"]', '["今日霖雨霽，颯然高館涼。","秋风吹二毛，烈士加慨慷。","憶昔皇運初，衆賓俱龙驤。","解巾佐幕府，脫劍升明堂。","郁郁被慶云，昭昭翼太陽。","鯨鱼縱大壑，鸑鷟鳴高岡。","信矣草創时，泰階速賢良。","一言頓遭逢，片善蒙恩光。","我生屬聖明，感激竊自彊。","崎嶇郡邑權，連騫翰墨場。","天朝富英髦，多士如珪璋。","盛才溢下位，蹇步徒猖狂。","閉门对羣书，几案在我旁。","枕席相远游，聊欲浮滄浪。","八月白露降，玄蟬號枯桑。","艤舟臨清川，迢遞愁思长。","我有同懷友，各在天一方。","離披不相见，浩蕩隔兩乡。","平生霞外期，宿昔共行藏。","豈無蓬萊樹，歲晏空蒼蒼。"]', '诗', 'shi', '', NULL, '閑居秋懷寄陽翟陸贊府封丘高少府 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27e67ed7-f172-48d2-90d3-5f3b85ab8cfb', '送友人使河源', '送友人使河源', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["送君魯郊外，下車上高丘。","蕭條千里暮，日落黃雲秋。","舉酒有餘恨，論邊無遠謀。","河源望不見，旌斾去悠悠。"]', '["送君魯郊外，下车上高丘。","蕭條千里暮，日落黄云秋。","舉酒有餘恨，論邊無远謀。","河源望不见，旌斾去悠悠。"]', '诗', 'shi', '', NULL, '送友人使河源 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddda8310-964c-48c4-8ffc-2e0b0ae64ee7', '送李侍御', '送李侍御', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["我年四十餘，已歎前路短。","羈離洞庭上，安得不引滿。","李侯忘情者，與我同疎懶。","孤帆泣瀟湘，望遠心欲斷。"]', '["我年四十餘，已歎前路短。","羈離洞庭上，安得不引满。","李侯忘情者，與我同疎懶。","孤帆泣瀟湘，望远心欲斷。"]', '诗', 'shi', '', NULL, '送李侍御 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('449b2a0e-97b1-4f34-a38e-6d5b54bb9f59', '送耿副使歸長沙', '送耿副使归长沙', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["畫舸欲南歸，江亭且留宴。","日暮湖上雲，蕭蕭若流霰。","昨夜相知者，明發不可見。","惆悵西北風，高帆爲誰扇。"]', '["畫舸欲南归，江亭且留宴。","日暮湖上云，蕭蕭若流霰。","昨夜相知者，明發不可见。","惆悵西北风，高帆爲誰扇。"]', '诗', 'shi', '', NULL, '送耿副使歸長沙 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea16a414-7a81-4e29-bada-88b5ce0e7a56', '送夏侯子之江夏', '送夏侯子之江夏', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["扣楫洞庭上，清風千里來。","留歡一杯酒，欲別復裴回。","相見楚山下，漁舟憶釣臺。","羨君還舊里，歸念獨悠哉。"]', '["扣楫洞庭上，清风千里来。","留歡一杯酒，欲別复裴回。","相见楚山下，漁舟憶釣台。","羨君還旧里，归念独悠哉。"]', '诗', 'shi', '', NULL, '送夏侯子之江夏 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58d09ca0-11c1-411f-96b4-2b5cb21dda95', '寓言二首 一', '寓言二首 一', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["春草紛碧色，佳人曠無期。","悠哉千里心，欲采商山芝。","歎息良會晚，如何桃李時。","懷君晴川上，佇立夏雲滋。"]', '["春草紛碧色，佳人曠無期。","悠哉千里心，欲采商山芝。","歎息良會晚，如何桃李时。","懷君晴川上，佇立夏云滋。"]', '诗', 'shi', '', NULL, '寓言二首 一 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('206e3471-2e7d-49dd-baf6-26c40052a82a', '寓言二首 二', '寓言二首 二', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["凜凜秋閨夕，綺羅早知寒。","玉砧調鳴杵，始擣機中紈。","憶昨別離日，桐花覆井欄。","今來思君時，白露盈堦漙。","聞有關河信，欲寄雙玉盤。","玉以委貞心，盤以薦嘉餐。","嗟君在萬里，使妾衣帶寬。"]', '["凜凜秋閨夕，綺羅早知寒。","玉砧調鳴杵，始擣機中紈。","憶昨別離日，桐花覆井欄。","今来思君时，白露盈堦漙。","闻有关河信，欲寄雙玉盤。","玉以委貞心，盤以薦嘉餐。","嗟君在万里，使妾衣带寬。"]', '诗', 'shi', '', NULL, '寓言二首 二 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2170f7c7-787a-4463-9061-c4f959c15670', '燕歌行', '燕歌行', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["國之重鎮惟幽都，東威九夷北制胡。","五軍精卒三十萬，百戰百勝擒單于。","前臨滹沱後易水，崇山沃野亙千里。","昔時燕山重賢士，黃金築臺從隗始。","倏忽興王定薊丘，漢家又以封王侯。","蕭條魏晉爲橫流，鮮卑竊據朝五州。","我唐區夏餘十紀，軍容武備赫萬祀。","彤弓黃鉞授元帥，墾耕大漠爲內地。","季秋膠折邊草腓，治兵羽獵因出師。","千營萬隊連旌旗，望之如火忽電馳。","匈奴懾竄窮髮北，大荒萬里無塵飛。","君不見隋家昔爲天下宰，窮兵黷武征遼海。","南風不競多死聲，鼓臥旗折黃雲橫。","六軍將士皆死盡，戰馬空鞍歸故營。","時移道革天下平，白環入貢滄海清。","自有農夫已高枕，無勞校尉重橫行。"]', '["国之重鎮惟幽都，东威九夷北制胡。","五軍精卒三十万，百戰百勝擒單于。","前臨滹沱後易水，崇山沃野亙千里。","昔时燕山重賢士，黄金築台從隗始。","倏忽兴王定薊丘，漢家又以封王侯。","蕭條魏晉爲橫流，鲜卑竊據朝五州。","我唐區夏餘十紀，軍容武備赫万祀。","彤弓黄鉞授元帥，墾耕大漠爲內地。","季秋膠折邊草腓，治兵羽獵因出師。","千營万隊連旌旗，望之如火忽電驰。","匈奴懾竄窮髮北，大荒万里無塵飞。","君不见隋家昔爲天下宰，窮兵黷武征遼海。","南风不競多死声，鼓臥旗折黄云橫。","六軍將士皆死尽，戰马空鞍归故營。","时移道革天下平，白环入貢滄海清。","自有農夫已高枕，無勞校尉重橫行。"]', '诗', 'shi', '', NULL, '燕歌行 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e190844-b5af-4f96-8560-1fab6dded1cf', '巴陵寄李二戶部張十四禮部', '巴陵寄李二戶部張十四禮部', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["江南春草初冪冪，愁殺江南獨愁客。","秦中楊柳也應新，轉憶秦中相憶人。","萬里鶯花不相見，登高一望淚沾巾。"]', '["江南春草初冪冪，愁殺江南独愁客。","秦中楊柳也應新，轉憶秦中相憶人。","万里鶯花不相见，登高一望泪沾巾。"]', '诗', 'shi', '', NULL, '巴陵寄李二戶部張十四禮部 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d97849fe-a0a9-4e70-8c5f-903a767d55dd', '長門怨', '长门怨', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["獨坐思千里，春庭曉景長。","鶯喧翡翠幕，柳覆鬱金堂。","舞蝶縈愁緒，繁花對靚妝。","深情托瑤瑟，弦斷不成章。"]', '["独坐思千里，春庭晓景长。","鶯喧翡翠幕，柳覆鬱金堂。","舞蝶縈愁緒，繁花对靚妝。","深情托瑤瑟，弦斷不成章。"]', '诗', 'shi', '', NULL, '長門怨 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5f5758f-6d54-4cf5-80f7-aee564991dbb', '銅雀臺', '銅雀台', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["日暮銅臺靜，西陵鳥雀歸。","撫弦心斷絕，聽管淚霏微。","靈几臨朝奠，空牀卷夜衣。","蒼蒼川上月，應照妾魂飛。"]', '["日暮銅台静，西陵鸟雀归。","撫弦心斷絕，听管泪霏微。","靈几臨朝奠，空牀卷夜衣。","蒼蒼川上月，應照妾魂飞。"]', '诗', 'shi', '', NULL, '銅雀臺 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ed42f3d-1d23-4809-8338-19f6ea4bcf33', '侍宴曲', '侍宴曲', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["雲陛褰珠扆，天墀覆綠楊。","隔簾妝隱映，向席舞低昂。","鳴佩長廊靜，開冰廣殿涼。","歡餘劍履散，同輦入昭陽。"]', '["云陛褰珠扆，天墀覆綠楊。","隔簾妝隐映，向席舞低昂。","鳴佩长廊静，开冰廣殿涼。","歡餘劍履散，同輦入昭陽。"]', '诗', 'shi', '', NULL, '侍宴曲 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d405c662-a7cd-4367-b55d-9d022408c27a', '對酒曲二首 一', '对酒曲二首 一', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["梅發柳依依，黃鸝歷亂飛。","當歌憐景色，對酒惜芳菲。","曲水浮花氣，流風散舞衣。","通宵留暮雨，上客莫言歸。"]', '["梅發柳依依，黄鸝歷亂飞。","當歌怜景色，对酒惜芳菲。","曲水浮花氣，流风散舞衣。","通宵留暮雨，上客莫言归。"]', '诗', 'shi', '', NULL, '對酒曲二首 一 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe18dc54-e281-4c8f-a75f-ad03acff753d', '對酒曲二首 二', '对酒曲二首 二', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["春來酒味濃，舉酒對春叢。","一酌千憂散，三杯萬事空。","放歌乘美景，醉舞向東風。","寄語尊前客，生涯任轉蓬。"]', '["春来酒味濃，舉酒对春叢。","一酌千憂散，三杯万事空。","放歌乘美景，醉舞向东风。","寄語尊前客，生涯任轉蓬。"]', '诗', 'shi', '', NULL, '對酒曲二首 二 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87c25012-7161-4495-97a9-0ce825a8201e', '送陸協律赴端州', '送陸協律赴端州', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["越井人南去，湘川水北流。","江邊數杯酒，海內一孤舟。","嶺嶠同仙客，京華即舊游。","春心將別恨，萬里共悠悠。"]', '["越井人南去，湘川水北流。","江邊數杯酒，海內一孤舟。","嶺嶠同仙客，京华即旧游。","春心將別恨，万里共悠悠。"]', '诗', 'shi', '', NULL, '送陸協律赴端州 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d708028-3c83-4bfc-baff-69ee730c16c7', '送王員外赴長沙', '送王員外赴长沙', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["攜手登臨處，巴陵天一隅。","春生雲夢澤，水溢洞庭湖。","共歎虞飜枉，同悲阮籍途。","長沙舊卑濕，今古不應殊。"]', '["携手登臨处，巴陵天一隅。","春生云梦澤，水溢洞庭湖。","共歎虞飜枉，同悲阮籍途。","长沙旧卑濕，今古不應殊。"]', '诗', 'shi', '', NULL, '送王員外赴長沙 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0d9ba88-14bc-49b3-b6c9-95ae471e261d', '送夏侯參軍赴廣州', '送夏侯參軍赴廣州', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["聞道衡陽外，由來鴈不飛。","送君從此去，書信定應稀。","雲海南溟遠，煙波北渚微。","勉哉孫楚吏，綵服正光輝。"]', '["闻道衡陽外，由来鴈不飞。","送君從此去，书信定應稀。","云海南溟远，煙波北渚微。","勉哉孫楚吏，綵服正光輝。"]', '诗', 'shi', '', NULL, '送夏侯參軍赴廣州 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59f2d984-3c55-48b9-b502-ea30639fb6ad', '長沙別李六侍御', '长沙別李六侍御', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["月明湘水白，霜落洞庭乾。","放逐長沙外，相逢路正難。","雲歸帝鄉遠，鴈報朔方寒。","此別盈襟淚，雍門不假彈。"]', '["月明湘水白，霜落洞庭乾。","放逐长沙外，相逢路正难。","云归帝乡远，鴈報朔方寒。","此別盈襟泪，雍门不假彈。"]', '诗', 'shi', '', NULL, '長沙別李六侍御 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28698238-d4e3-4424-95db-1e5b02216e96', '岳陽樓宴王員外貶長沙', '岳陽楼宴王員外貶长沙', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["極浦三春草，高樓萬里心。","楚山晴靄碧，湘水暮流深。","忽與朝中舊，同爲澤畔吟。","停杯試北望，還欲淚沾[襟]。"]', '["極浦三春草，高楼万里心。","楚山晴靄碧，湘水暮流深。","忽與朝中旧，同爲澤畔吟。","停杯試北望，還欲泪沾[襟]。"]', '诗', 'shi', '', NULL, '岳陽樓宴王員外貶長沙 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d456e2d3-45e4-4fb4-8416-fc8180222042', '詠馮昭儀當熊', '詠馮昭儀當熊', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["白羽插雕弓，蜺旌動朔風。","平明出金屋，扈輦上林中。","逐獸長廊靜，呼鷹御苑空。","王孫莫諫獵，賤妾解當熊。"]', '["白羽插雕弓，蜺旌动朔风。","平明出金屋，扈輦上林中。","逐獸长廊静，呼鷹御苑空。","王孫莫諫獵，賤妾解當熊。"]', '诗', 'shi', '', NULL, '詠馮昭儀當熊 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9abc0f0-8f45-486d-a75d-7aa217f33ddd', '早朝大明宮呈兩省僚友', '早朝大明宮呈兩省僚友', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["銀燭熏天紫陌長，禁城春色曉蒼蒼。","千條弱柳垂青瑣，百囀流鶯繞建章。","劍佩聲隨玉墀步，衣冠身惹御爐香。","共沐恩波鳳池上，朝朝染翰侍君王。"]', '["銀燭熏天紫陌长，禁城春色晓蒼蒼。","千條弱柳垂青瑣，百囀流鶯繞建章。","劍佩声隨玉墀步，衣冠身惹御爐香。","共沐恩波鳳池上，朝朝染翰侍君王。"]', '诗', 'shi', '', NULL, '早朝大明宮呈兩省僚友 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb760bf0-8d06-4209-84fa-b6cb91689f6e', '白馬', '白马', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["白馬紫連錢，嘶鳴丹闕前。","聞珂自蝶躞，不要下金鞭。"]', '["白马紫連錢，嘶鳴丹闕前。","闻珂自蝶躞，不要下金鞭。"]', '诗', 'shi', '', NULL, '白馬 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eff32e55-9fd8-4c5d-88e0-f9f32559f037', '贈薛瑤英', '贈薛瑤英', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["舞怯銖衣重，笑疑桃臉開。","方知漢成帝，虛築避風臺。"]', '["舞怯銖衣重，笑疑桃臉开。","方知漢成帝，虛築避风台。"]', '诗', 'shi', '', NULL, '贈薛瑤英 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fe1ad4c-f301-4de3-acdf-e951d718378b', '出塞曲', '出塞曲', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["萬里平沙一聚塵，南飛羽檄北來人。","傳道五原烽火急，單于昨夜寇新秦。"]', '["万里平沙一聚塵，南飞羽檄北来人。","傳道五原烽火急，單于昨夜寇新秦。"]', '诗', 'shi', '', NULL, '出塞曲 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f9457ea-2e67-459b-ae59-10fa80ed5e25', '春思二首 一', '春思二首 一', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["草色青青柳色黃，桃花歷亂李花香。","東風不爲吹愁去，春日偏能惹恨長。"]', '["草色青青柳色黄，桃花歷亂李花香。","东风不爲吹愁去，春日偏能惹恨长。"]', '诗', 'shi', '', NULL, '春思二首 一 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b425026f-95bf-40f7-addf-a1d3e4bf7c60', '春思二首 二', '春思二首 二', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["紅粉當壚弱柳垂，金花臘酒解酴醿。","笙歌日暮能留客，醉殺長安輕薄兒。"]', '["紅粉當壚弱柳垂，金花臘酒解酴醿。","笙歌日暮能留客，醉殺长安轻薄兒。"]', '诗', 'shi', '', NULL, '春思二首 二 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5dc715a-741a-46ef-bd21-d5d00c89fd92', '勤政樓觀樂', '勤政楼观乐', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["銀河帝女下三清，紫禁笙歌出九城。","爲報延州來聽樂，須知天下欲昇平。"]', '["銀河帝女下三清，紫禁笙歌出九城。","爲報延州来听乐，須知天下欲昇平。"]', '诗', 'shi', '', NULL, '勤政樓觀樂 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2872403-a910-4f7d-80c2-908d1311c0b8', '贈陝掾梁宏', '贈陝掾梁宏', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["梁子工文四十年，詩顛名過草書顛。","白頭仍作功曹掾，祿薄難供沽酒錢。"]', '["梁子工文四十年，诗顛名過草书顛。","白头仍作功曹掾，祿薄难供沽酒錢。"]', '诗', 'shi', '', NULL, '贈陝掾梁宏 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44adc443-78f1-4b99-948b-e651a88d7b71', '荅嚴大夫', '荅嚴大夫', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["今夕秦天一鴈來，梧桐墜葉搗衣催。","思君獨步華亭月，舊館秋陰生綠苔。"]', '["今夕秦天一鴈来，梧桐墜葉捣衣催。","思君独步华亭月，旧館秋陰生綠苔。"]', '诗', 'shi', '', NULL, '荅嚴大夫 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c8f9765-45ee-4577-9931-5027f49878b5', '送李侍郎赴常州', '送李侍郎赴常州', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["雪晴雲散北風寒，楚水吳山道路難。","今日送君須盡醉，明朝相憶路漫漫。"]', '["雪晴云散北风寒，楚水吳山道路难。","今日送君須尽醉，明朝相憶路漫漫。"]', '诗', 'shi', '', NULL, '送李侍郎赴常州 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('375d0ef5-9068-4c2b-9763-18742aeed7c4', '初至巴陵與李十二白裴九同泛洞庭湖三首 一', '初至巴陵與李十二白裴九同泛洞庭湖三首 一', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["江上相逢皆舊遊，湘山永望不堪愁。","明月秋風洞庭水，孤鴻落葉一扁舟。"]', '["江上相逢皆旧游，湘山永望不堪愁。","明月秋风洞庭水，孤鴻落葉一扁舟。"]', '诗', 'shi', '', NULL, '初至巴陵與李十二白裴九同泛洞庭湖三首 一 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9777f975-441e-4ece-9631-05b32704e042', '初至巴陵與李十二白裴九同泛洞庭湖三首 二', '初至巴陵與李十二白裴九同泛洞庭湖三首 二', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["楓岸紛紛落葉多，洞庭秋水晚來波。","乘興輕舟無近遠，白雲明月弔湘娥。"]', '["楓岸紛紛落葉多，洞庭秋水晚来波。","乘兴轻舟無近远，白云明月弔湘娥。"]', '诗', 'shi', '', NULL, '初至巴陵與李十二白裴九同泛洞庭湖三首 二 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2272304-9b07-4c4d-89ea-fd6e7c0b1a91', '初至巴陵與李十二白裴九同泛洞庭湖三首 三', '初至巴陵與李十二白裴九同泛洞庭湖三首 三', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["江畔楓葉初帶霜，渚邊菊花亦已黃。","輕舟落日興不盡，三湘五湖意何長。"]', '["江畔楓葉初带霜，渚邊菊花亦已黄。","轻舟落日兴不尽，三湘五湖意何长。"]', '诗', 'shi', '', NULL, '初至巴陵與李十二白裴九同泛洞庭湖三首 三 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca190099-24f8-4d2d-9482-3fa6cc62a887', '西亭春望', '西亭春望', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["日長風煖柳青青，北鴈歸飛入窅冥。","岳陽城上聞吹笛，能使春心滿洞庭。"]', '["日长风煖柳青青，北鴈归飞入窅冥。","岳陽城上闻吹笛，能使春心满洞庭。"]', '诗', 'shi', '', NULL, '西亭春望 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42e7b91f-cc65-4128-8679-2752170df76f', '君山', '君山', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["湘中老人讀黃老，手援紫藟坐碧草。","春至不知湖水深，日暮忘却巴陵道。"]', '["湘中老人读黄老，手援紫藟坐碧草。","春至不知湖水深，日暮忘却巴陵道。"]', '诗', 'shi', '', NULL, '君山 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76d92edf-ab72-43e4-b359-00383eb8740d', '洞庭送李十二赴零陵', '洞庭送李十二赴零陵', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["今日相逢落葉前，洞庭秋水遠連天。","共說金華舊遊處，回看北斗欲潸然。"]', '["今日相逢落葉前，洞庭秋水远連天。","共说金华旧游处，回看北斗欲潸然。"]', '诗', 'shi', '', NULL, '洞庭送李十二赴零陵 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecc50b50-8998-4041-aa2a-a3fe8c88b325', '江南送李卿', '江南送李卿', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["雙鶴南飛度楚山，楚南相見憶秦關。","願值迴風吹羽翼，早隨陽鴈及春還。"]', '["雙鹤南飞度楚山，楚南相见憶秦关。","願值迴风吹羽翼，早隨陽鴈及春還。"]', '诗', 'shi', '', NULL, '江南送李卿 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b123426e-64d6-471a-85f1-2b824e1548bd', '送王道士還京', '送王道士還京', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["一片仙雲入帝鄉，數聲秋鴈至衡陽。","借問清都舊花月，豈知遷客泣瀟湘。"]', '["一片仙云入帝乡，數声秋鴈至衡陽。","借问清都旧花月，豈知遷客泣瀟湘。"]', '诗', 'shi', '', NULL, '送王道士還京 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf74ae03-cc7d-4f15-98d0-8ad8a0eba914', '巴陵夜別王八員外', '巴陵夜別王八員外', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["柳絮飛時別洛陽，梅花發後到三湘。","世情已逐浮雲散，離恨空隨江水長。"]', '["柳絮飞时別洛陽，梅花發後到三湘。","世情已逐浮云散，離恨空隨江水长。"]', '诗', 'shi', '', NULL, '巴陵夜別王八員外 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ed2b527-8482-4bf0-8728-d0c5f828653d', '別裴九弟', '別裴九弟', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["西江萬里向東流，今夜江邊駐客舟。","月色更添春色好，蘆風似勝竹風幽。"]', '["西江万里向东流，今夜江邊駐客舟。","月色更添春色好，蘆风似勝竹风幽。"]', '诗', 'shi', '', NULL, '別裴九弟 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd87a4b6-d301-47fa-b138-692a1b7ef226', '送南給事貶崖州', '送南給事貶崖州', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["疇昔丹墀與鳳池，即今相見兩相悲。","朱崖雲夢三千里，欲別俱爲慟哭時。"]', '["疇昔丹墀與鳳池，即今相见兩相悲。","朱崖云梦三千里，欲別俱爲慟哭时。"]', '诗', 'shi', '', NULL, '送南給事貶崖州 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd3e613e-ad79-4584-a306-cb7e1b99ff7c', '重別南給事', '重別南給事', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["謫宦三年尚未回，故人今日又重來。","聞道崖州一千里，今朝須盡數千杯。"]', '["謫宦三年尚未回，故人今日又重来。","闻道崖州一千里，今朝須尽數千杯。"]', '诗', 'shi', '', NULL, '重別南給事 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b204828-26d1-4051-af94-66b309b83901', '岳陽樓重宴別王八員外貶長沙', '岳陽楼重宴別王八員外貶长沙', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["江路東連千里潮，青雲北望紫微遙。","莫道巴陵湖水闊，長沙南畔更蕭條。"]', '["江路东連千里潮，青云北望紫微遙。","莫道巴陵湖水闊，长沙南畔更蕭條。"]', '诗', 'shi', '', NULL, '岳陽樓重宴別王八員外貶長沙 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2516cd79-8ae0-47b0-9bad-0a807c57dbb1', '紫參歌', '紫參歌', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["遠公林下滿青苔，春藥偏宜間石開。","往往幽人尋水見，時時仙蝶隔雲來。","陰陽雕刻花如鳥，對鳳連雞一何小。","春風宛轉虎溪傍，紫翼紅翹翻霽光。","貝葉經前無住色，蓮花會裏暫留香。","蓬山才子憐幽性，白雲陽春動新詠。","應知仙卉老雲霞，莫賞夭桃滿蹊逕。"]', '["远公林下满青苔，春藥偏宜间石开。","往往幽人尋水见，时时仙蝶隔云来。","陰陽雕刻花如鸟，对鳳連雞一何小。","春风宛轉虎溪傍，紫翼紅翹翻霽光。","貝葉經前無住色，蓮花會裏暫留香。","蓬山才子怜幽性，白云陽春动新詠。","應知仙卉老云霞，莫賞夭桃满蹊逕。"]', '诗', 'shi', '', NULL, '紫參歌 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eebe6e3-bd22-46bd-ab32-7bad224e1eae', '瑪瑙杯歌', '瑪瑙杯歌', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["瑤溪碧岸生奇寶，剖質披心出文藻。","良工雕飾明且鮮，得成珍器入芳筵。","含華炳麗金尊側，翠斝瓊觴忽無色。","繁弦急管催獻酬，倏若飛空生羽翼。","𤩌𤩌蘭英照豹斑，滿堂詞客盡朱顏。","花光來去傳香袖，霞影高低傍玉山。","王孫彩筆題新詠，碎錦連珠復輝映。","世情貴耳不貴奇，謾說海底珊瑚枝。","寧及琢磨當妙用，燕歌楚舞長相隨。"]', '["瑤溪碧岸生奇寶，剖質披心出文藻。","良工雕飾明且鲜，得成珍器入芳筵。","含华炳丽金尊側，翠斝瓊觴忽無色。","繁弦急管催獻酬，倏若飞空生羽翼。","𤩌𤩌蘭英照豹斑，满堂词客尽朱顏。","花光来去傳香袖，霞影高低傍玉山。","王孫彩笔題新詠，碎錦連珠复輝映。","世情貴耳不貴奇，謾说海底珊瑚枝。","寧及琢磨當妙用，燕歌楚舞长相隨。"]', '诗', 'shi', '', NULL, '瑪瑙杯歌 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7fd325f-acb2-479e-9c0d-e104a1c519df', '鋤藥詠', '鋤藥詠', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["蒔藥穿林復在巘，濃香秀色深能淺。","雲氣垂來裛露偏，松陰占處知春晚。","拂曙殘鶯百囀催，縈泉帶石幾花開。","不隨飛鳥緣枝去，如笑幽人出谷來。","對之不覺忘疎嬾，廢卷荷鋤嫌日短。","豈無萱草樹堦墀，惜爾幽芳世所遺。","但使芝蘭出蕭艾，不辭手足皆胼胝。","寧學陶潛空嗜酒，頹齡捨此事東菑。"]', '["蒔藥穿林复在巘，濃香秀色深能淺。","云氣垂来裛露偏，松陰占处知春晚。","拂曙殘鶯百囀催，縈泉带石幾花开。","不隨飞鸟緣枝去，如笑幽人出谷来。","对之不覺忘疎嬾，廢卷荷鋤嫌日短。","豈無萱草樹堦墀，惜爾幽芳世所遺。","但使芝蘭出蕭艾，不辞手足皆胼胝。","寧学陶潛空嗜酒，頹齡捨此事东菑。"]', '诗', 'shi', '', NULL, '鋤藥詠 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5e0331b-c6c8-458d-b7f6-fd636604ae45', '病鶴篇', '病鹤篇', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["獨鶴聲哀羽摧折，沙頭一點留殘雪。","三山侶伴能遠翔，五里裴回忍爲別。","驚羣各畏野人機，誰肯相將霞水飛。","不及川鳧長比翼，隨波雙泛復雙歸。","碧海滄江深且廣，目盡天倪安得往。","雲山隔路不隔心，宛頸和鳴長在想。","何時白霧捲青天，接影追飛太液前。"]', '["独鹤声哀羽摧折，沙头一点留殘雪。","三山侶伴能远翔，五里裴回忍爲別。","驚羣各畏野人機，誰肯相將霞水飞。","不及川鳧长比翼，隨波雙泛复雙归。","碧海滄江深且廣，目尽天倪安得往。","云山隔路不隔心，宛頸和鳴长在想。","何时白霧捲青天，接影追飞太液前。"]', '诗', 'shi', '', NULL, '病鶴篇 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e961ac8e-2de7-4ba1-a5a4-e1b810809edf', '片玉篇', '片玉篇', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["至寶未爲代所奇，韞靈示[璞]荆山陲。","獨使虹光天子識，不將清韻世人知。","世人所貴惟燕石，美玉對之成瓦礫。","空山埋照凡幾年，古色蒼痕宛自然。","重溪冪冪暗雲樹，一片熒熒光石泉。","美人之鑒明且徹，玉指提攜嘆奇絕。","試勞香袖拂莓苔，不覺清心皎冰雪。","連城美價幸逢時，命代良工豈見遺。","試作珪璋禮天地，何如瓀𤨟在堦墀。"]', '["至寶未爲代所奇，韞靈示[璞]荆山陲。","独使虹光天子識，不將清韻世人知。","世人所貴惟燕石，美玉对之成瓦礫。","空山埋照凡幾年，古色蒼痕宛自然。","重溪冪冪暗云樹，一片熒熒光石泉。","美人之鑒明且徹，玉指提携嘆奇絕。","試勞香袖拂莓苔，不覺清心皎冰雪。","連城美價幸逢时，命代良工豈见遺。","試作珪璋禮天地，何如瓀𤨟在堦墀。"]', '诗', 'shi', '', NULL, '片玉篇 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23ccbb4e-eccb-4475-9d7f-ad949218c71b', '畫鶴篇', '畫鹤篇', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["點素凝姿任畫工，霜毛玉羽照簾櫳。","借問飛鳴華表上，何如粉繢彩屏中。","文昌宮近芙蓉闕，蘭室絪緼香且結。","鑪氣朝成緱嶺雲，銀燈夜作華亭月。","日暖花明梁燕歸，應驚片雪在仙闈。","主人顧盼千金重，誰肯裴回五里飛。"]', '["点素凝姿任畫工，霜毛玉羽照簾櫳。","借问飞鳴华表上，何如粉繢彩屏中。","文昌宮近芙蓉闕，蘭室絪緼香且結。","鑪氣朝成緱嶺云，銀灯夜作华亭月。","日暖花明梁燕归，應驚片雪在仙闈。","主人顧盼千金重，誰肯裴回五里飞。"]', '诗', 'shi', '', NULL, '畫鶴篇 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31379608-e12f-4ec6-a9f8-42d22388df40', '秋霖曲', '秋霖曲', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["君不見聖主旰食憂元元，秋風苦雨暗九門。","鳳凰池裏沸泉騰，蒼龍闕下生雲根。","陰精離畢太淹度，倦鳥將歸不知樹。","愁陰慘淡時殷雷，生靈墊溺若寒灰。","公卿紅粒爨丹桂，黔首白骨封青苔。","貂裘玉食張公子，炰炙熏天戟門裏。","且如歌笑日揮金，應笑禹湯能罪己。","鶴鳴蛙躍正及時，豹隱蘭凋亦可悲。","焉得太阿決屏翳，還令率土見朝曦。"]', '["君不见聖主旰食憂元元，秋风苦雨暗九门。","鳳凰池裏沸泉腾，蒼龙闕下生云根。","陰精離畢太淹度，倦鸟將归不知樹。","愁陰慘淡时殷雷，生靈墊溺若寒灰。","公卿紅粒爨丹桂，黔首白骨封青苔。","貂裘玉食張公子，炰炙熏天戟门裏。","且如歌笑日揮金，應笑禹湯能罪己。","鹤鳴蛙躍正及时，豹隐蘭凋亦可悲。","焉得太阿決屏翳，還令率土见朝曦。"]', '诗', 'shi', '', NULL, '秋霖曲 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a111e08b-ab19-46bf-a23e-9a96cf686321', '白石枕', '白石枕', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["琢珉勝水碧，所貴素且貞。","曾無白圭玷，不作浮磬鳴。","捧來太陽前，一片新冰清。","沈沈風憲地，待爾秋已至。","璞堅難爲功，誰怨晚成器。","比德無磷緇，論交亦如此。"]', '["琢珉勝水碧，所貴素且貞。","曾無白圭玷，不作浮磬鳴。","捧来太陽前，一片新冰清。","沈沈风憲地，待爾秋已至。","璞堅难爲功，誰怨晚成器。","比德無磷緇，論交亦如此。"]', '诗', 'shi', '', NULL, '白石枕 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f23bcaa-99bb-4d34-9d68-abd3b9f4d163', '賦得青城山歌送楊杜二郎中赴蜀軍', '賦得青城山歌送楊杜二郎中赴蜀軍', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["蜀山西南千萬重，仙經最說青城峰。","青城嶔岑倚空碧，遠壓峨嵋吞劍壁。","錦屏雲起易成霞，玉洞花明不知夕。","星臺二妙逐王師，阮瑀軍書王粲詩。","日落猨聲連玉笛，晴來山翠傍旌旗。","綠蘿春月營門近，知君對酒遙相思。"]', '["蜀山西南千万重，仙經最说青城峰。","青城嶔岑倚空碧，远壓峨嵋吞劍壁。","錦屏云起易成霞，玉洞花明不知夕。","星台二妙逐王師，阮瑀軍书王粲诗。","日落猨声連玉笛，晴来山翠傍旌旗。","綠蘿春月營门近，知君对酒遙相思。"]', '诗', 'shi', '', NULL, '賦得青城山歌送楊杜二郎中赴蜀軍 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96f59cf0-a6ff-49f3-b3f4-a56e4f60b6e8', '送李大夫赴廣州', '送李大夫赴廣州', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["一賢間氣生，麟趾鳳凰羽。","何意人之望，未爲王者輔。","出鎮忽推才，盛哉文且武。","南越寄維城，雄雄擁甲兵。","鼓門通幕府，天井入軍營。","厥俗多豪侈，古來難致禮。","唯君飲冰心，可酌貪泉水。","忠臣感聖君，徇義不邀勳。","龍鏡逃山魅，霜風破嶂雪。","征途凡幾轉，魏闕如在眼。","向郡海潮迎，指鄉關樹遠。","按節化甌閩，下車佳政新。","應令尉陀俗，還作上皇人。","支離交俊哲，弱冠至華髮。","昔許霄漢期，今嗟鵬鷃別。","圖南不可御，惆悵守薄暮。"]', '["一賢间氣生，麟趾鳳凰羽。","何意人之望，未爲王者輔。","出鎮忽推才，盛哉文且武。","南越寄維城，雄雄擁甲兵。","鼓门通幕府，天井入軍營。","厥俗多豪侈，古来难致禮。","唯君饮冰心，可酌貪泉水。","忠臣感聖君，徇義不邀勳。","龙镜逃山魅，霜风破嶂雪。","征途凡幾轉，魏闕如在眼。","向郡海潮迎，指乡关樹远。","按節化甌閩，下车佳政新。","應令尉陀俗，還作上皇人。","支離交俊哲，弱冠至华髮。","昔許霄漢期，今嗟鵬鷃別。","圖南不可御，惆悵守薄暮。"]', '诗', 'shi', '', NULL, '送李大夫赴廣州 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7350cb9b-0a7e-4927-9cf8-e07c0bd67135', '送崔校書從軍', '送崔校书從軍', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["雁門太守能愛賢，麟閣書生亦投筆。","寧唯玉劒報知己，更有龍韜佐師律。","別馬連嘶出御溝，家人幾夜望刀頭。","燕南春草傷心色，薊北黃雲滿眼愁。","聞道輕生能擊虜，何嗟少壯不封侯。"]', '["雁门太守能愛賢，麟閣书生亦投笔。","寧唯玉劒報知己，更有龙韜佐師律。","別马連嘶出御溝，家人幾夜望刀头。","燕南春草傷心色，薊北黄云满眼愁。","闻道轻生能擊虜，何嗟少壯不封侯。"]', '诗', 'shi', '', NULL, '送崔校書從軍 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8937ea32-aa5d-4003-b363-2cb987360707', '送張將軍征西', '送張將軍征西', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["長安少年唯好武，金殿承恩爭破虜。","沙場烽火隔天山，鐵騎征西幾歲還。","戰處黑雲霾翰海，愁中明月度陽關。","玉笛聲悲離酌晚，金方路極行人遠。","計日霜戈盡敵歸，回首戎城空落暉。","始笑子卿心計失，徒看海上節旄稀。"]', '["长安少年唯好武，金殿承恩爭破虜。","沙場烽火隔天山，鐵騎征西幾歲還。","戰处黑云霾翰海，愁中明月度陽关。","玉笛声悲離酌晚，金方路極行人远。","計日霜戈尽敵归，回首戎城空落暉。","始笑子卿心計失，徒看海上節旄稀。"]', '诗', 'shi', '', NULL, '送張將軍征西 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfd2646e-303f-45fa-ad9e-84b1df2fa4fc', '送修武元少府', '送修武元少府', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["寸祿榮色養，此行寧歎惜。","自今黃綬采蘭時，不厭丹墀芳草色。","百戰荒城復井田，幾家春樹帶人煙。","黎甿久厭蓬飄苦，遲爾西南惠月傳。"]', '["寸祿榮色養，此行寧歎惜。","自今黄綬采蘭时，不厭丹墀芳草色。","百戰荒城复井田，幾家春樹带人煙。","黎甿久厭蓬飄苦，遲爾西南惠月傳。"]', '诗', 'shi', '', NULL, '送修武元少府 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d43835bb-f425-4eaf-b6a3-d20f9c5eec27', '送崔十三東遊', '送崔十三东游', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["千里有同心，十年一會面。","當杯緩箏柱，倏忽催離宴。","丹鳳城頭噪晚鴉，行人馬首夕陽斜。","灞上春風留別袂，關東新月宿誰家。","官柳依依兩鄉色，誰能此別不相憶。"]', '["千里有同心，十年一會面。","當杯緩箏柱，倏忽催離宴。","丹鳳城头噪晚鴉，行人马首夕陽斜。","灞上春风留別袂，关东新月宿誰家。","官柳依依兩乡色，誰能此別不相憶。"]', '诗', 'shi', '', NULL, '送崔十三東遊 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c735e439-9965-4c38-8a1f-cb7432e9c969', '送鄔三落第還鄉', '送鄔三落第還乡', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["郢客文章絕世稀，常嗟時命與心違。","十年失路誰知己，千里思親獨遠歸。","雲帆春水將何適，日愛東南暮山碧。","關中新月對離尊，江上殘花待歸客。","名宦無媒自古遲，窮途此別不堪悲。","荷衣垂釣且安命，金馬招賢會有時。"]', '["郢客文章絕世稀，常嗟时命與心違。","十年失路誰知己，千里思親独远归。","云帆春水將何適，日愛东南暮山碧。","关中新月对離尊，江上殘花待归客。","名宦無媒自古遲，窮途此別不堪悲。","荷衣垂釣且安命，金马招賢會有时。"]', '诗', 'shi', '', NULL, '送鄔三落第還鄉 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d38990b6-6ef4-4843-b112-3f7c4ad33e9b', '送馬明府赴江陵', '送马明府赴江陵', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["陶令南行心自永，江天極目澄秋景。","萬室遙方犬不鳴，雙鳧下處人皆靜。","清風高興得湖山，門柳蕭條雙翟閑。","黃花滿把應相憶，落日登樓北望還。"]', '["陶令南行心自永，江天極目澄秋景。","万室遙方犬不鳴，雙鳧下处人皆静。","清风高兴得湖山，门柳蕭條雙翟闲。","黄花满把應相憶，落日登楼北望還。"]', '诗', 'shi', '', NULL, '送馬明府赴江陵 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5acf3a90-df9f-4a67-b60b-429e2e532e0f', '送畢侍御謫居', '送畢侍御謫居', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["崇蘭香死玉簪折，志士吞聲甘徇節。","忠藎不爲明主知，悲來莫向時人說。","滄浪之水見心清，楚客辭天淚滿纓。","百鳥喧喧噪一鶚，上林高枝亦難託。","寧嗟人世棄虞飜，且喜江山得康樂。","自憐黃綬老嬰身，妻子朝來勸隱淪。","桃花洞裏舉家去，此別相思復幾春。"]', '["崇蘭香死玉簪折，志士吞声甘徇節。","忠藎不爲明主知，悲来莫向时人说。","滄浪之水见心清，楚客辞天泪满纓。","百鸟喧喧噪一鶚，上林高枝亦难託。","寧嗟人世棄虞飜，且喜江山得康乐。","自怜黄綬老嬰身，妻子朝来勸隐淪。","桃花洞裏舉家去，此別相思复幾春。"]', '诗', 'shi', '', NULL, '送畢侍御謫居 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3c6b2bf-35cf-40dc-bbcf-cfb5efa9f82e', '送褚大落第東歸', '送褚大落第东归', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["離琴彈苦調，美人慘向隅。","頃來荷策干明主，還復扁舟歸五湖。","漢家側席明揚久，豈意遺賢在林藪。","玉堂金馬隔青雲，墨客儒生皆白首。","昨夢芳洲采白蘋，歸期且喜故園春。","稚子只思陶令至，文君不厭馬卿貧。","剡中風月久相憶，池上舊遊應再得。","酒熟寧孤芳杜春，詩成不枉青山色。","念此那能不羨歸，長楊諫獵事皆違。","他日東流一乘興，知君爲我掃荆扉。"]', '["離琴彈苦調，美人慘向隅。","頃来荷策干明主，還复扁舟归五湖。","漢家側席明揚久，豈意遺賢在林藪。","玉堂金马隔青云，墨客儒生皆白首。","昨梦芳洲采白蘋，归期且喜故园春。","稚子只思陶令至，文君不厭马卿貧。","剡中风月久相憶，池上旧游應再得。","酒熟寧孤芳杜春，诗成不枉青山色。","念此那能不羨归，长楊諫獵事皆違。","他日东流一乘兴，知君爲我掃荆扉。"]', '诗', 'shi', '', NULL, '送褚大落第東歸 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4aa9659-d7cc-4a2c-b5e3-84120124f2ee', '送傅管記赴蜀軍', '送傅管記赴蜀軍', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["終童之死誰繼出，燕頷儒生今俊逸。","主將早知鸚鵡賦，飛書許載蛟龍筆。","峨嵋玉壘指霞標，鳥沒天低幕府遙。","巴山雨色藏征斾，漢水猨聲咽短簫。","賜璧腰金應可料，才畧縱橫年且妙。","無人不重樂毅賢，何敵能當魯連嘯。","日暮黃雲千里昏，壯心輕別不銷魂。","勤君用却龍泉劒，莫負平生國士恩。"]', '["終童之死誰繼出，燕頷儒生今俊逸。","主將早知鸚鵡賦，飞书許載蛟龙笔。","峨嵋玉壘指霞標，鸟沒天低幕府遙。","巴山雨色藏征斾，漢水猨声咽短簫。","賜璧腰金應可料，才畧縱橫年且妙。","無人不重乐毅賢，何敵能當魯連嘯。","日暮黄云千里昏，壯心轻別不銷魂。","勤君用却龙泉劒，莫負平生国士恩。"]', '诗', 'shi', '', NULL, '送傅管記赴蜀軍 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d06ef399-b8fa-4427-b32e-4ad1132ff3d7', '送張少府', '送張少府', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["愁雲破斜照，別酌勸行子。","蓬驚馬首風，雁拂天邊水。","寸晷如三歲，離心在萬里。"]', '["愁云破斜照，別酌勸行子。","蓬驚马首风，雁拂天邊水。","寸晷如三歲，離心在万里。"]', '诗', 'shi', '', NULL, '送張少府 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8da0b71-c9fb-42cd-b434-6f5a961e845d', '行路難', '行路难', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["君不見明星映空月，太陽朝升光盡歇。","君不見凋零委路蓬，長風飄舉入雲中。","由來人事何嘗定，且莫驕奢笑踐窮。"]', '["君不见明星映空月，太陽朝升光尽歇。","君不见凋零委路蓬，长风飄舉入云中。","由来人事何嘗定，且莫驕奢笑踐窮。"]', '诗', 'shi', '', NULL, '行路難 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a312b9b6-ca48-4272-bfcf-d85bee9f537e', '盧龍塞行送韋掌記', '盧龙塞行送韋掌記', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["雨雪紛紛黑山外，行人共指盧龍塞。","萬里飛沙咽鼓鼙，三軍殺氣凝旌斾。","陳琳書記本翩翩，料敵張兵奪酒泉。","聖主好文兼好武，封侯莫比漢皇年。"]', '["雨雪紛紛黑山外，行人共指盧龙塞。","万里飞沙咽鼓鼙，三軍殺氣凝旌斾。","陳琳书記本翩翩，料敵張兵奪酒泉。","聖主好文兼好武，封侯莫比漢皇年。"]', '诗', 'shi', '', NULL, '盧龍塞行送韋掌記 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fa910be-23c0-4d4f-a83d-5aa74a36597c', '效古秋夜長', '效古秋夜长', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["秋漢飛玉霜，北風掃荷香。","含情紡織孤燈盡，拭淚相思寒漏長。","簷前碧雲靜如水，月弔棲烏啼鳥起。","誰家少婦事鴛機，錦幕雲屏深掩扉。","白玉窗中聞落葉，應憐寒女獨無衣。"]', '["秋漢飞玉霜，北风掃荷香。","含情紡织孤灯尽，拭泪相思寒漏长。","簷前碧云静如水，月弔棲烏啼鸟起。","誰家少婦事鴛機，錦幕云屏深掩扉。","白玉窗中闻落葉，應怜寒女独無衣。"]', '诗', 'shi', '', NULL, '效古秋夜長 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55b8fb1b-fe9d-443a-a3de-6f016fc79fe9', '臥病李員外題扉而去', '臥病李員外題扉而去', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["僻陋病者居，蒿萊行逕失。","誰知簪紱貴，能問幽憂疾。","珂聲未駐門，蘭氣先入室。","沉痾不冠帶，安得候蓬蓽。","清揚去莫尋，離念頃來侵。","雀栖高窗靜，日出修桐陰。","枕上憶君子，悄悄唯苦心。"]', '["僻陋病者居，蒿萊行逕失。","誰知簪紱貴，能问幽憂疾。","珂声未駐门，蘭氣先入室。","沉痾不冠带，安得候蓬蓽。","清揚去莫尋，離念頃来侵。","雀栖高窗静，日出修桐陰。","枕上憶君子，悄悄唯苦心。"]', '诗', 'shi', '', NULL, '臥病李員外題扉而去 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c373cc0-d72c-4bc8-b39e-c48d0564c86e', '酬王維春夜竹亭贈別', '酬王維春夜竹亭贈別', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["山月隨客來，主人興不淺。","今宵竹林下，誰覺花源遠。","惆悵曙鶯啼，孤雲還絕巘。"]', '["山月隨客来，主人兴不淺。","今宵竹林下，誰覺花源远。","惆悵曙鶯啼，孤云還絕巘。"]', '诗', 'shi', '', NULL, '酬王維春夜竹亭贈別 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('246b3dad-004b-4b2b-b6ce-a0016cb05e57', '山中寄時校書', '山中寄时校书', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["蓬萊紫氣溫如玉，唯予知爾陽春曲。","別來幾日芳蓀綠，百花酒滿不見君，青山一望心斷續。"]', '["蓬萊紫氣溫如玉，唯予知爾陽春曲。","別来幾日芳蓀綠，百花酒满不见君，青山一望心斷續。"]', '诗', 'shi', '', NULL, '山中寄時校書 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('013121bc-ca81-42c0-a918-0f541b8a65fb', '送李四擢第歸覲省', '送李四擢第归覲省', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["當年貴得意，文字各爭名。","齊唱陽春曲，唯君金玉聲。","懸黎寶中出，高價世難掩。","鴻羽不低飛，龍津徒自險。","直矜鸚鵡賦，不貴芳桂枝。","少俊蔡邕許，長鳴唐舉知。","梁城下熊軾，朱戟何暐耀。","才子欲歸寧，棠花已含笑。","高門知慶大，子孝覺親榮。","獨攬還珠美，寧唯問絹情。","離筵不盡醉，摻袂一何早。","馬蹄西別輕，樹色東看好。","行塵忽不見，惆悵青門道。"]', '["當年貴得意，文字各爭名。","齊唱陽春曲，唯君金玉声。","懸黎寶中出，高價世难掩。","鴻羽不低飞，龙津徒自險。","直矜鸚鵡賦，不貴芳桂枝。","少俊蔡邕許，长鳴唐舉知。","梁城下熊軾，朱戟何暐耀。","才子欲归寧，棠花已含笑。","高门知慶大，子孝覺親榮。","独攬還珠美，寧唯问絹情。","離筵不尽醉，摻袂一何早。","马蹄西別轻，樹色东看好。","行塵忽不见，惆悵青门道。"]', '诗', 'shi', '', NULL, '送李四擢第歸覲省 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2b44284-b679-43ca-8c72-8c79a6e5cdc1', '過曹鈞隱居', '過曹鈞隐居', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["荃蕙有奇性，馨香道爲人。","不居衆芳下，寧老空林春。","之子秉高節，攻文還守真。","素書寸陰盡，流水怨情新。","濟濟振纓客，煙霄各致身。","誰當舉玄晏，不使作良臣。"]', '["荃蕙有奇性，馨香道爲人。","不居衆芳下，寧老空林春。","之子秉高節，攻文還守真。","素书寸陰尽，流水怨情新。","濟濟振纓客，煙霄各致身。","誰當舉玄晏，不使作良臣。"]', '诗', 'shi', '', NULL, '過曹鈞隱居 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d6b5c2b-0e77-497c-9ba9-a394fde9e35b', '哭曹鈞', '哭曹鈞', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["苦節推白首，憐君負此生。","忠藎名空在，家貧道不行。","朝來相憶訪蓬蓽，只謂淵明猶臥疾。","忽見江南弔鶴來，始知天上文星失。","嘗恨知音千古稀，那堪夫子九泉歸。","一聲鄰笛殘陽裏，酹酒空堂淚滿衣。"]', '["苦節推白首，怜君負此生。","忠藎名空在，家貧道不行。","朝来相憶訪蓬蓽，只謂淵明猶臥疾。","忽见江南弔鹤来，始知天上文星失。","嘗恨知音千古稀，那堪夫子九泉归。","一声鄰笛殘陽裏，酹酒空堂泪满衣。"]', '诗', 'shi', '', NULL, '哭曹鈞 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54ea9954-751e-412e-bb1f-5fdf18cb2f5a', '東陽郡齋中詣南山招韋十', '东陽郡斋中詣南山招韋十', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["霽來海半山，隱映城上起。","中峰落照時，殘雪翠微裏。","同心久爲別，孤興那對此。","良會何遲遲，清揚瞻則邇。"]', '["霽来海半山，隐映城上起。","中峰落照时，殘雪翠微裏。","同心久爲別，孤兴那对此。","良會何遲遲，清揚瞻則邇。"]', '诗', 'shi', '', NULL, '東陽郡齋中詣南山招韋十 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b3c37e1-b0e5-4135-8e19-ebc779029622', '清泥驛迎獻王侍御', '清泥驛迎獻王侍御', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["候館掃清晝，使車出明光。","森森入郭樹，一道引飛霜。","仰視驄花白，多慚綬色黃。","鷦鷯無羽翼，願假憲烏翔。"]', '["候館掃清晝，使车出明光。","森森入郭樹，一道引飞霜。","仰視驄花白，多慚綬色黄。","鷦鷯無羽翼，願假憲烏翔。"]', '诗', 'shi', '', NULL, '清泥驛迎獻王侍御 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ee646bb-07d2-4847-9527-8f90351bbe22', '沭陽古渡作', '沭陽古渡作', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["日落問津處，雲霞殘碧空。","牧牛避田燒，退鷁隨潮風。","迴首故鄉遠，臨流此路窮。","翩翩青冥去，羨彼高飛鴻。"]', '["日落问津处，云霞殘碧空。","牧牛避田燒，退鷁隨潮风。","迴首故乡远，臨流此路窮。","翩翩青冥去，羨彼高飞鴻。"]', '诗', 'shi', '', NULL, '沭陽古渡作 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8c9fb53-1723-4b66-a79f-87bfb7ec5eba', '臥疾荅劉道士', '臥疾荅劉道士', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["白露蠶已絲，空林日淒清。","寥寥晝扉掩，獨臥秋窗明。","寶字比仙藥，羽人寄柴荆。","長吟想風馭，怳若升蓬瀛。"]', '["白露蠶已絲，空林日淒清。","寥寥晝扉掩，独臥秋窗明。","寶字比仙藥，羽人寄柴荆。","长吟想风馭，怳若升蓬瀛。"]', '诗', 'shi', '', NULL, '臥疾荅劉道士 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c53ae26b-4d36-4eaa-9ff4-004c922bee79', '夢尋西山準上人', '梦尋西山準上人', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["別處秋泉聲，至今猶在耳。","何嘗夢魂去，不見雪山子。","新月隔林時，千峰翠微裏。","言忘心更寂，跡滅雲自起。","覺來纓上塵，如洗功德水。"]', '["別处秋泉声，至今猶在耳。","何嘗梦魂去，不见雪山子。","新月隔林时，千峰翠微裏。","言忘心更寂，跡滅云自起。","覺来纓上塵，如洗功德水。"]', '诗', 'shi', '', NULL, '夢尋西山準上人 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3cffd93-4f6e-48c7-9dc2-83dd6fa21ca2', '長安旅宿', '长安旅宿', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["九秋旅夜長，萬感何時歇。","蕙花漸寒暮，心事猶楚越。","直躬邅世道，咫步隔天闕。","每聞長樂鐘，載泣靈臺月。","明旦北門外，歸途堪白髮。"]', '["九秋旅夜长，万感何时歇。","蕙花漸寒暮，心事猶楚越。","直躬邅世道，咫步隔天闕。","每闻长乐鐘，載泣靈台月。","明旦北门外，归途堪白髮。"]', '诗', 'shi', '', NULL, '長安旅宿 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f911e1be-474d-4147-9500-750d2cae4977', '過桐柏山', '過桐柏山', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["秋風過楚山，山靜秋聲晚。","賞心無定極，仙步亦清遠。","返照雲竇空，寒流石苔淺。","羽人昔已去，靈跡欣方踐。","投策謝歸途，世緣從此遣。"]', '["秋风過楚山，山静秋声晚。","賞心無定極，仙步亦清远。","返照云竇空，寒流石苔淺。","羽人昔已去，靈跡欣方踐。","投策謝归途，世緣從此遣。"]', '诗', 'shi', '', NULL, '過桐柏山 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f718ec8-d4cf-4257-90a6-f0ec432912a0', '李士曹廳對雨', '李士曹廳对雨', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["春雨暗重城，訟庭深更寂。","終朝人吏少，滿院煙雲集。","溼鳥壓花枝，新苔宜砌石。","掾曹富文史，清興對詞客。","愛爾蕙蘭叢，芳香飽時澤。"]', '["春雨暗重城，訟庭深更寂。","終朝人吏少，满院煙云集。","溼鸟壓花枝，新苔宜砌石。","掾曹富文史，清兴对词客。","愛爾蕙蘭叢，芳香飽时澤。"]', '诗', 'shi', '', NULL, '李士曹廳對雨 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd785cf3-0c68-46a9-982d-db3e9f2b2ef8', '登勝果寺南樓雨中望嚴協律', '登勝果寺南楼雨中望嚴協律', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["微雨侵晚陽，連山半藏碧。","林端陟香榭，雲外遲來客。","孤村凝片煙，去水生遠白。","但隹川原趣，不覺城池夕。","更喜眼中人，清光漸咫尺。"]', '["微雨侵晚陽，連山半藏碧。","林端陟香榭，云外遲来客。","孤村凝片煙，去水生远白。","但隹川原趣，不覺城池夕。","更喜眼中人，清光漸咫尺。"]', '诗', 'shi', '', NULL, '登勝果寺南樓雨中望嚴協律 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('110ea489-e0f3-40c3-8bd1-39936729a6cf', '冬夜題旅館', '冬夜題旅館', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["退飛憶林藪，樂業羨黎庶。","四海盡窮途，一枝無宿處。","嚴冬北風急，中夜哀鴻去。","孤燭思何深，寒窗坐難曙。","勞歌待明發，惆悵盈百慮。"]', '["退飞憶林藪，乐業羨黎庶。","四海尽窮途，一枝無宿处。","嚴冬北风急，中夜哀鴻去。","孤燭思何深，寒窗坐难曙。","勞歌待明發，惆悵盈百慮。"]', '诗', 'shi', '', NULL, '冬夜題旅館 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f579259-77b8-4ba0-b038-c60b889d9dd2', '自終南山晚歸', '自終南山晚归', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["采苓日往還。","得性非樵隱，白水到初闊。","青山辭尚近，絕境勝無倪。","歸途興不盡，沮溺時返顧。","牛羊自相引，逍遙不外求。","塵慮從茲泯。"]', '["采苓日往還。","得性非樵隐，白水到初闊。","青山辞尚近，絕境勝無倪。","归途兴不尽，沮溺时返顧。","牛羊自相引，逍遙不外求。","塵慮從茲泯。"]', '诗', 'shi', '', NULL, '自終南山晚歸 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2833e66b-f317-4aee-af70-8a930b72142e', '早渡伊川見舊鄰作', '早渡伊川见旧鄰作', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["鵾雞鳴早霜，秋水寒旅涉。","漁人昔鄰舍，相見具舟楫。","出浦興未盡，向山心更愜。","村落通白雲，茅茨隱紅葉。","東臯滿時稼，歸客欣復業。"]', '["鵾雞鳴早霜，秋水寒旅涉。","漁人昔鄰舍，相见具舟楫。","出浦兴未尽，向山心更愜。","村落通白云，茅茨隐紅葉。","东臯满时稼，归客欣复業。"]', '诗', 'shi', '', NULL, '早渡伊川見舊鄰作 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84ec4a9f-4157-4f7c-a8f5-4e53e6a9fbf7', '夕發箭場巖下作', '夕發箭場巖下作', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["行役不遑安，在幽機轉發。","山谷無明晦，溪霞自興沒。","朝櫛杉下風，夕飲石上月。","懿爾青雲士，垂纓朝鳳闕。","寧知採竹人，每食慙薇蕨。"]', '["行役不遑安，在幽機轉發。","山谷無明晦，溪霞自兴沒。","朝櫛杉下风，夕饮石上月。","懿爾青云士，垂纓朝鳳闕。","寧知採竹人，每食慙薇蕨。"]', '诗', 'shi', '', NULL, '夕發箭場巖下作 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55657e38-4ff1-4748-82dc-a106734b8521', '同李五夕次香山精舍訪憲上人', '同李五夕次香山精舍訪憲上人', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["彼岸聞山鐘，仙舟過苕水。","松門入幽映，石徑趨迤邐。","初月開草堂，遠公方覯止。","忘言在閑夜，凝念得微理。","泠泠功德池，相與滌心耳。"]', '["彼岸闻山鐘，仙舟過苕水。","松门入幽映，石徑趨迤邐。","初月开草堂，远公方覯止。","忘言在闲夜，凝念得微理。","泠泠功德池，相與滌心耳。"]', '诗', 'shi', '', NULL, '同李五夕次香山精舍訪憲上人 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad241b3f-bcd8-4109-8ac5-851c49649215', '雨中望海上懷鬱林觀中道侶', '雨中望海上懷鬱林观中道侶', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["山觀海頭雨，懸沫動煙樹。","只疑蒼茫裏，鬱島欲飛去。","大塊怒天吳，驚潮蕩雲路。","羣真儼盈想，一葦不可渡。","惆悵赤城期，願假輕鴻馭。"]', '["山观海头雨，懸沫动煙樹。","只疑蒼茫裏，鬱島欲飞去。","大塊怒天吳，驚潮蕩云路。","羣真儼盈想，一葦不可渡。","惆悵赤城期，願假轻鴻馭。"]', '诗', 'shi', '', NULL, '雨中望海上懷鬱林觀中道侶 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad777e0a-f3da-4a4b-a139-de6842496d6c', '廣德初鑾駕出關後登高愁望二首 一', '廣德初鑾駕出关後登高愁望二首 一', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["長安不可望，遠處邊愁起。","輦轂混戎夷，山河空表裏。","黃雲壓城闕，斜照移烽壘。","漢幟遠成霞，胡馬來如蟻。","不知涿鹿戰，早晚蚩尤死。","渴日候河清，沈憂催暮齒。"]', '["长安不可望，远处邊愁起。","輦轂混戎夷，山河空表裏。","黄云壓城闕，斜照移烽壘。","漢幟远成霞，胡马来如蟻。","不知涿鹿戰，早晚蚩尤死。","渴日候河清，沈憂催暮齒。"]', '诗', 'shi', '', NULL, '廣德初鑾駕出關後登高愁望二首 一 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d9b4f82-3950-4467-b739-73c9feccb36e', '廣德初鑾駕出關後登高愁望二首 二', '廣德初鑾駕出关後登高愁望二首 二', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["愁看秦川色，慘慘雲景晦。","乾坤暫運行，品物遺覆載。","黃塵漲戎馬，紫氣隨龍斾。","掩泣指關東，日月妖氛外。","臣心寄遠水，朝海去如帶。","周德更休明，天衢佇開泰。"]', '["愁看秦川色，慘慘云景晦。","乾坤暫運行，品物遺覆載。","黄塵漲戎马，紫氣隨龙斾。","掩泣指关东，日月妖氛外。","臣心寄远水，朝海去如带。","周德更休明，天衢佇开泰。"]', '诗', 'shi', '', NULL, '廣德初鑾駕出關後登高愁望二首 二 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d477b0e-74c8-4d79-83dc-678b0f95769a', '獨往覆釜山寄郎士元', '独往覆釜山寄郎士元', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["賞心無遠近，芳月好登望。","勝事引幽人，山下復山上。","將尋洞中藥，復愛湖外嶂。","古壁苔入雲，陰溪樹穿浪。","誰言世緣絕，更惜知音曠。","鶯啼綠蘿春，迴首還惆悵。"]', '["賞心無远近，芳月好登望。","勝事引幽人，山下复山上。","將尋洞中藥，复愛湖外嶂。","古壁苔入云，陰溪樹穿浪。","誰言世緣絕，更惜知音曠。","鶯啼綠蘿春，迴首還惆悵。"]', '诗', 'shi', '', NULL, '獨往覆釜山寄郎士元 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('106ecd31-b4b2-4419-a7ed-6153e8edb5e8', '送王季友赴洪州幕下', '送王季友赴洪州幕下', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["列郡皆用武，南征所從誰。","諸侯重才畧，見子如瓊枝。","撫劍感知己，出門方遠辭。","煙波帶幕府，海日生紅旗。","問我何功德，負恩留玉墀。","銷魂把別袂，媿爾酬明時。"]', '["列郡皆用武，南征所從誰。","諸侯重才畧，见子如瓊枝。","撫劍感知己，出门方远辞。","煙波带幕府，海日生紅旗。","问我何功德，負恩留玉墀。","銷魂把別袂，媿爾酬明时。"]', '诗', 'shi', '', NULL, '送王季友赴洪州幕下 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('939ffd54-cf19-4caa-beaa-9e6e7e21e26c', '客舍贈鄭賁', '客舍贈鄭賁', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["結交意不薄，匪席言莫違。","世義隨波久，人生知己稀。","先鳴誓相達，未遇還相依。","一望金門詔，三看黃鳥飛。","暝投同旅食，朝出易儒衣。","嵇向林廬接，攜手行將歸。"]', '["結交意不薄，匪席言莫違。","世義隨波久，人生知己稀。","先鳴誓相達，未遇還相依。","一望金门詔，三看黄鸟飞。","暝投同旅食，朝出易儒衣。","嵇向林廬接，携手行將归。"]', '诗', 'shi', '', NULL, '客舍贈鄭賁 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60dddd12-62e4-4ed4-ac46-ffdd5d3194f6', '山中春仲寄上王恒潁川沈沖', '山中春仲寄上王恒潁川沈沖', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["隱者守恬泊，春山日深淨。","誰知蟠木材，得性無人境。","座隅泉出洞，竹上雲起嶺。","飢貁入山廚，飲虹過藥井。","前溪堪放逸，仲月好風景。","遊目來遠思，摘芳寄汝潁。"]', '["隐者守恬泊，春山日深淨。","誰知蟠木材，得性無人境。","座隅泉出洞，竹上云起嶺。","飢貁入山廚，饮虹過藥井。","前溪堪放逸，仲月好风景。","游目来远思，摘芳寄汝潁。"]', '诗', 'shi', '', NULL, '山中春仲寄上王恒潁川沈沖 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b73dd1d-d744-4620-965f-163b4b45127d', '南中春意', '南中春意', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["入仕無知言，遊方隨世道。","平生願開濟，遇物干懷抱。","已阻青雲期，甘同散樗老。","客遊南海曲，坐見韶陽蚤。","舊國別佳人，他鄉思芳草。","惜無鴻鵠翅，安得凌蒼昊。"]', '["入仕無知言，游方隨世道。","平生願开濟，遇物干懷抱。","已阻青云期，甘同散樗老。","客游南海曲，坐见韶陽蚤。","旧国別佳人，他乡思芳草。","惜無鴻鵠翅，安得凌蒼昊。"]', '诗', 'shi', '', NULL, '南中春意 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8ca42aa-af38-44f6-88f6-b2b510fe5b00', '東陵藥堂寄張道士', '东陵藥堂寄張道士', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["木落蒼山空，當軒秋水色。","清旦振衣坐，永吟意何極。","願言金丹壽，一假鸞鳳翼。","日夕開真經，言忘心更默。","玄都有仙子，採藥早相識。","煙霞難再期，焚香空歎息。"]', '["木落蒼山空，當軒秋水色。","清旦振衣坐，永吟意何極。","願言金丹壽，一假鸾鳳翼。","日夕开真經，言忘心更默。","玄都有仙子，採藥早相識。","煙霞难再期，焚香空歎息。"]', '诗', 'shi', '', NULL, '東陵藥堂寄張道士 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e72009f8-45a1-4dd7-9981-4146223b7696', '苦雨憶皇甫冉', '苦雨憶皇甫冉', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["涼雨門巷深，窮居成習靜。","獨吟愁霖雨，更使秋思永。","疲痾苦昏墊，日夕開軒屏。","草木森已悲，衾幬清且冷。","如何遊宦客，江海隨泛梗。","延首長相思，憂襟孰能整。"]', '["涼雨门巷深，窮居成習静。","独吟愁霖雨，更使秋思永。","疲痾苦昏墊，日夕开軒屏。","草木森已悲，衾幬清且冷。","如何游宦客，江海隨泛梗。","延首长相思，憂襟孰能整。"]', '诗', 'shi', '', NULL, '苦雨憶皇甫冉 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df243c22-a6e7-4b60-9428-7d253ba4f371', '寄任山人', '寄任山人', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["天階崇黼黻，世路有趨競。","獨抱中孚爻，誰知苦寒詠。","行潦難朝海，散材空遇聖。","豈無鳴鳳時，其如問津命。","所思青山郭，再夢綠蘿徑。","林泉春可遊，羨爾得其性。"]', '["天階崇黼黻，世路有趨競。","独抱中孚爻，誰知苦寒詠。","行潦难朝海，散材空遇聖。","豈無鳴鳳时，其如问津命。","所思青山郭，再梦綠蘿徑。","林泉春可游，羨爾得其性。"]', '诗', 'shi', '', NULL, '寄任山人 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26f494c7-13e8-42e6-9b7c-ff9296fa699b', '登秦嶺半巖遇雨', '登秦嶺半巖遇雨', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["屏翳忽騰氣，浮陽慘無暉。","千峰挂飛雨，百尺搖翠微。","震電閃雲逕，奔流翻石磯。","倚巖假松蓋，臨水羨荷衣。","不得采苓去，空思乘月歸。","且憐東臯上，水色侵荆扉。"]', '["屏翳忽腾氣，浮陽慘無暉。","千峰挂飞雨，百尺搖翠微。","震電閃云逕，奔流翻石磯。","倚巖假松蓋，臨水羨荷衣。","不得采苓去，空思乘月归。","且怜东臯上，水色侵荆扉。"]', '诗', 'shi', '', NULL, '登秦嶺半巖遇雨 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9962e0d-5b78-44d6-b6db-fad25dddaf80', '杪秋南山西峰題準上人蘭若', '杪秋南山西峰題準上人蘭若', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["向山看霽色，步步豁幽性。","返照亂流明，寒空千嶂淨。","石門有餘好，霞殘月欲映。","上詣遠公廬，孤峰懸一逕。","雲裏隔窗火，松下聞山磬。","客到兩忘言，猨心與禪定。"]', '["向山看霽色，步步豁幽性。","返照亂流明，寒空千嶂淨。","石门有餘好，霞殘月欲映。","上詣远公廬，孤峰懸一逕。","云裏隔窗火，松下闻山磬。","客到兩忘言，猨心與禪定。"]', '诗', 'shi', '', NULL, '杪秋南山西峰題準上人蘭若 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11e193d2-f374-43c1-b475-94751f6569b8', '田園雨後贈鄰人', '田园雨後贈鄰人', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["安排常任性，偃臥晚開戶。","樵客荷蓑歸，向來春山雨。","殘雲虹未落，返景霞初吐。","時鳥鳴村墟，新泉遶林圃。","堯年尚恬泊，鄰里成太古。","室邇人遂遙，相思怨芳杜。"]', '["安排常任性，偃臥晚开戶。","樵客荷蓑归，向来春山雨。","殘云虹未落，返景霞初吐。","时鸟鳴村墟，新泉遶林圃。","堯年尚恬泊，鄰里成太古。","室邇人遂遙，相思怨芳杜。"]', '诗', 'shi', '', NULL, '田園雨後贈鄰人 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c004054-61d3-442e-b15c-07ee460b9cfe', '天門谷題孫逸人石壁', '天门谷題孫逸人石壁', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["崖石亂流處，竹深斜照歸。","主人臥磻石，心耳滌清暉。","春雷近作解，空谷半芳菲。","雲棟綵虹宿，藥圃蝴蝶飛。","惡囂慕嘉遯，幾夜瞻少微。","相見竟何說，忘情同息機。"]', '["崖石亂流处，竹深斜照归。","主人臥磻石，心耳滌清暉。","春雷近作解，空谷半芳菲。","云棟綵虹宿，藥圃蝴蝶飞。","惡囂慕嘉遯，幾夜瞻少微。","相见竟何说，忘情同息機。"]', '诗', 'shi', '', NULL, '天門谷題孫逸人石壁 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8a394a4-9136-4b82-9875-2eb2796fc597', '藍溪休沐寄趙八給事', '藍溪休沐寄趙八給事', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["蟲鳴歸舊里，田野秋農閑。","即事敦夙尚，衡門方再關。","夕陽入東籬，爽氣高前山。","霜蕙後時老，巢禽知暝還。","侍臣黃樞寵，鳴玉青雲間。","肯想觀魚處，寒泉照髮斑。"]', '["蟲鳴归旧里，田野秋農闲。","即事敦夙尚，衡门方再关。","夕陽入东籬，爽氣高前山。","霜蕙後时老，巢禽知暝還。","侍臣黄樞寵，鳴玉青云间。","肯想观鱼处，寒泉照髮斑。"]', '诗', 'shi', '', NULL, '藍溪休沐寄趙八給事 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8610b5a-7535-4772-955d-e31edbb5687c', '遊輞川至南山寄谷口王十六', '游輞川至南山寄谷口王十六', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["山色不厭遠，我行隨處深。","蹟幽青蘿逕，思絕孤霞岑。","獨鶴引過浦，鳴猨呼入林。","褰裳百泉裏，一步一清心。","王子在何處，隔雲雞犬音。","折麻定延佇，乘月期招尋。"]', '["山色不厭远，我行隨处深。","蹟幽青蘿逕，思絕孤霞岑。","独鹤引過浦，鳴猨呼入林。","褰裳百泉裏，一步一清心。","王子在何处，隔云雞犬音。","折麻定延佇，乘月期招尋。"]', '诗', 'shi', '', NULL, '遊輞川至南山寄谷口王十六 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abb4dc83-2b30-4924-9e78-dbf3dbd84b70', '藍田溪與漁者宿', '藍田溪與漁者宿', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["獨遊屢忘歸，況此隱淪處。","濯髮清泠泉，月明不能去。","更憐垂綸叟，靜若沙上鷺。","一論白雲心，千里滄洲趣。","蘆中夜火盡，浦口秋山曙。","歎息分枝禽，何時更相遇。"]', '["独游屢忘归，況此隐淪处。","濯髮清泠泉，月明不能去。","更怜垂綸叟，静若沙上鷺。","一論白云心，千里滄洲趣。","蘆中夜火尽，浦口秋山曙。","歎息分枝禽，何时更相遇。"]', '诗', 'shi', '', NULL, '藍田溪與漁者宿 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82b40e28-bad6-4349-a1f5-b87a4a8353fb', '淮上別范大', '淮上別范大', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["悲風隕涼葉，送歸怨南楚。","窮年將別離，寸晷申宴語。","長淮流不盡，征櫂忽復舉。","碧落半愁雲，黃鶴時顧侶。","遊宦且未達，前途各修阻。","分袂一相嗟，良辰更何許。"]', '["悲风隕涼葉，送归怨南楚。","窮年將別離，寸晷申宴語。","长淮流不尽，征櫂忽复舉。","碧落半愁云，黄鹤时顧侶。","游宦且未達，前途各修阻。","分袂一相嗟，良辰更何許。"]', '诗', 'shi', '', NULL, '淮上別范大 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29a648c9-f4bd-410b-9365-7abf073cd174', '離居夜雨奉寄李京兆', '離居夜雨奉寄李京兆', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["永夜不可度，蛩吟秋雨滴。","寂寞想章臺，始歎雲泥隔。","雷聲匪君車，猶時過我廬。","電影非君燭，猶能明我目。","如何瓊樹枝，夢裏看不足。","望望佳期阻，愁生寒草綠。"]', '["永夜不可度，蛩吟秋雨滴。","寂寞想章台，始歎云泥隔。","雷声匪君车，猶时過我廬。","電影非君燭，猶能明我目。","如何瓊樹枝，梦裏看不足。","望望佳期阻，愁生寒草綠。"]', '诗', 'shi', '', NULL, '離居夜雨奉寄李京兆 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6307f77c-5aae-4837-ab68-507f4add7149', '歎畢少府以持法無隱見繫', '歎畢少府以持法無隐见繫', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["用法本禁邪，盡心翻自極。","畢公在囹圄，世事何糺纆。","翠鳳呈其瑞，虞羅寄鎩翼。","囚中千念時，窗外百花色。","落景閉圜扉，春蟲網叢棘。","古人不念文，紛淚莫霑臆。"]', '["用法本禁邪，尽心翻自極。","畢公在囹圄，世事何糺纆。","翠鳳呈其瑞，虞羅寄鎩翼。","囚中千念时，窗外百花色。","落景閉圜扉，春蟲網叢棘。","古人不念文，紛泪莫霑臆。"]', '诗', 'shi', '', NULL, '歎畢少府以持法無隱見繫 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99ca19fa-6ba1-4f1f-9de5-1460c4386357', '小園招隱', '小园招隐', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["支離鮮兄弟，形影如手足。","但遂飲冰節，甘辭代耕祿。","斑衣在林巷，始覺無羈束。","交柯低戶陰，閑鳥將雛宿。","窮通世情阻，日夜苔徑綠。","誰言北郭貧，能分晏嬰粟。"]', '["支離鲜兄弟，形影如手足。","但遂饮冰節，甘辞代耕祿。","斑衣在林巷，始覺無羈束。","交柯低戶陰，闲鸟將雛宿。","窮通世情阻，日夜苔徑綠。","誰言北郭貧，能分晏嬰粟。"]', '诗', 'shi', '', NULL, '小園招隱 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('122d575f-769c-4a90-a7c1-c7a5c134a9c2', '過溫逸人舊居', '過溫逸人旧居', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["返真難合道，懷舊仍無弔。","浮俗漸澆淳，斯人誰繼妙。","聲容在心耳，寧覺阻言笑。","玄堂閉幾春，拱木齊雲嶠。","鶴傳居士舞，猨得蘇門嘯。","酹酒片陽微，空山想埋照。"]', '["返真难合道，懷旧仍無弔。","浮俗漸澆淳，斯人誰繼妙。","声容在心耳，寧覺阻言笑。","玄堂閉幾春，拱木齊云嶠。","鹤傳居士舞，猨得蘇门嘯。","酹酒片陽微，空山想埋照。"]', '诗', 'shi', '', NULL, '過溫逸人舊居 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b0c1013-99b2-4cee-a26d-22c9c24df2a2', '縣內水亭晨興聽訟', '縣內水亭晨兴听訟', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["晨光起宿露，池上判黎甿。","借問秋泉色，何如拙宦情。","磨鉛辱利用，策蹇愁前程。","昨夜明月滿，中心如鵲驚。","負恩時易失，多病績難成。","坐惜寒塘晚，霜風吹杜蘅。"]', '["晨光起宿露，池上判黎甿。","借问秋泉色，何如拙宦情。","磨鉛辱利用，策蹇愁前程。","昨夜明月满，中心如鵲驚。","負恩时易失，多病績难成。","坐惜寒塘晚，霜风吹杜蘅。"]', '诗', 'shi', '', NULL, '縣內水亭晨興聽訟 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('725b1b9c-cfc9-4782-bbf4-a0c28693e67d', '海畔秋思', '海畔秋思', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["匡濟難道合，去留隨興牽。","偶爲謝客事，不顧平子田。","魏闕賁翹楚，此身長棄捐。","箕裘空在念，咄咄誰推賢。","無用即明代，養痾仍壯年。","日夕望佳期，帝鄉路幾千。","秋風晨夜起，零落愁芳荃。"]', '["匡濟难道合，去留隨兴牽。","偶爲謝客事，不顧平子田。","魏闕賁翹楚，此身长棄捐。","箕裘空在念，咄咄誰推賢。","無用即明代，養痾仍壯年。","日夕望佳期，帝乡路幾千。","秋风晨夜起，零落愁芳荃。"]', '诗', 'shi', '', NULL, '海畔秋思 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a851dad9-2c0f-4085-bc4a-2886f25c907c', '太子李舍人城東別業', '太子李舍人城东別業', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["南山轉羣木，昏曉擁山翠。","小澤近龍居，清蒼常雨氣。","君家北原上，千金買勝事。","丹闕退朝廻，白雲迎賞至。","新晴村落外，處處煙景異。","片水明斷岸，餘霞入古寺。","東臯指歸翼，目盡有餘意。"]', '["南山轉羣木，昏晓擁山翠。","小澤近龙居，清蒼常雨氣。","君家北原上，千金買勝事。","丹闕退朝廻，白云迎賞至。","新晴村落外，处处煙景異。","片水明斷岸，餘霞入古寺。","东臯指归翼，目尽有餘意。"]', '诗', 'shi', '', NULL, '太子李舍人城東別業 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc7da4c6-4993-4dcf-b784-26208e23a113', '谷口新居寄同省朋故', '谷口新居寄同省朋故', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["種黍傍煙溪，榛蕪兼沮洳。","亦知生計薄，所貴隱身處。","橡栗石上村，莓苔水中路。","蕭然授衣日，得此還山趣。","汲井愛秋泉，結茅因古樹。","閑雲與幽鳥，對我不能去。","寄謝鴛鷺羣，狎鷗拙所慕。"]', '["種黍傍煙溪，榛蕪兼沮洳。","亦知生計薄，所貴隐身处。","橡栗石上村，莓苔水中路。","蕭然授衣日，得此還山趣。","汲井愛秋泉，結茅因古樹。","闲云與幽鸟，对我不能去。","寄謝鴛鷺羣，狎鷗拙所慕。"]', '诗', 'shi', '', NULL, '谷口新居寄同省朋故 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcc295d7-ba1d-43b3-a9a3-7739771ccde7', '京兆尹廳前甘棠樹降甘露', '京兆尹廳前甘棠樹降甘露', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["內史用堯意，理京宣惠慈。","氣和祥則降，孰謂天難知。","濟旱露爲兆，有如塤應篪。","豈無夭桃樹，灑此甘棠枝。","玉色與人淨，珠光臨筆垂。","協風與之俱，物性皆熙熙。","何必鳳池上，方看作霖時。"]', '["內史用堯意，理京宣惠慈。","氣和祥則降，孰謂天难知。","濟旱露爲兆，有如塤應篪。","豈無夭桃樹，灑此甘棠枝。","玉色與人淨，珠光臨笔垂。","協风與之俱，物性皆熙熙。","何必鳳池上，方看作霖时。"]', '诗', 'shi', '', NULL, '京兆尹廳前甘棠樹降甘露 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b11b665-e4ea-4edd-a46b-51f191183111', '秋夜作', '秋夜作', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["萬計各無成，寸心日悠漫。","浮生竟何窮，巧曆不能算。","流落四海間，辛勤百年半。","商歌向秋月，哀韻兼浩歎。","寤寐怨佳期，美人隔霄漢。","寒雲度窮水，別業遶垂幔。","窗中問談雞，長夜何時旦。"]', '["万計各無成，寸心日悠漫。","浮生竟何窮，巧曆不能算。","流落四海间，辛勤百年半。","商歌向秋月，哀韻兼浩歎。","寤寐怨佳期，美人隔霄漢。","寒云度窮水，別業遶垂幔。","窗中问談雞，长夜何时旦。"]', '诗', 'shi', '', NULL, '秋夜作 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6eae5ecc-fda0-4ced-ac00-b93e573e381c', '觀村人牧山田', '观村人牧山田', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["六府且未盈，三農爭務作。","貧民乏井稅，塉土皆墾鑿。","禾黍入寒雲，茫茫半山郭。","秋來積霖雨，霜降方銍獲。","中田聚黎甿，反景空村落。","顧慚不耕者，微祿同衛鶴。","庶追周任言，敢負謝生諾。"]', '["六府且未盈，三農爭務作。","貧民乏井稅，塉土皆墾鑿。","禾黍入寒云，茫茫半山郭。","秋来積霖雨，霜降方銍獲。","中田聚黎甿，反景空村落。","顧慚不耕者，微祿同衛鹤。","庶追周任言，敢負謝生諾。"]', '诗', 'shi', '', NULL, '觀村人牧山田 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e46d6dff-6b75-4e72-8637-707d78481256', '裴侍郎湘川迴以青竹筒相遺因而贈之', '裴侍郎湘川迴以青竹筒相遺因而贈之', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["楚竹青玉潤，從來湘水陰。","緘書取直節，君子知虛心。","入用隨憲簡，積文不受金。","體將丹鳳直，色映秋霜深。","寧肯假伶倫，謬爲龍鳳吟。","唯將翰院客，昔祕瑤華音。","長跪捧嘉貺，歲寒慚所欽。"]', '["楚竹青玉潤，從来湘水陰。","緘书取直節，君子知虛心。","入用隨憲簡，積文不受金。","體將丹鳳直，色映秋霜深。","寧肯假伶倫，謬爲龙鳳吟。","唯將翰院客，昔祕瑤华音。","长跪捧嘉貺，歲寒慚所欽。"]', '诗', 'shi', '', NULL, '裴侍郎湘川迴以青竹筒相遺因而贈之 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43dd39dd-c995-43b1-8d5b-6256b3861891', '東城初陷與薛員外王補闕暝投南山佛寺', '东城初陷與薛員外王補闕暝投南山佛寺', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["日昃石門裏，松聲山寺寒。","香雲空靜影，定水無驚湍。","洗足解塵纓，忽覺天形寬。","清鐘揚虛谷，微月深重巒。","噫我朝露世，翻浮與波瀾。","行運遘憂患，何緣親盤桓。","庶將鏡中象，盡作無生觀。"]', '["日昃石门裏，松声山寺寒。","香云空静影，定水無驚湍。","洗足解塵纓，忽覺天形寬。","清鐘揚虛谷，微月深重巒。","噫我朝露世，翻浮與波瀾。","行運遘憂患，何緣親盤桓。","庶將镜中象，尽作無生观。"]', '诗', 'shi', '', NULL, '東城初陷與薛員外王補闕暝投南山佛寺 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a7c167c-1831-413c-99c5-6c86bb7ff512', '奉和張荆州巡農晚望', '奉和張荆州巡農晚望', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["太清霽雲雷，陽春陶物象。","明牧行春令，仁風助昇長。","時和俗勤業，播殖農厥壤。","陰陰桑陌連，漠漠水田廣。","郡中忽無事，方外還獨往。","日暮駐歸軒，湖山有佳賞。","宣城傳逸韻，千載誰此響。"]', '["太清霽云雷，陽春陶物象。","明牧行春令，仁风助昇长。","时和俗勤業，播殖農厥壤。","陰陰桑陌連，漠漠水田廣。","郡中忽無事，方外還独往。","日暮駐归軒，湖山有佳賞。","宣城傳逸韻，千載誰此响。"]', '诗', 'shi', '', NULL, '奉和張荆州巡農晚望 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18a33a4e-11a3-46e7-82e2-b231241fd4ca', '送包何東遊', '送包何东游', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["水國嘗獨往，送君還念茲。","湖山遠近色，昏旦煙霞時。","子好謝公跡，常吟孤嶼詩。","果乘扁舟去，若與白鷗期。","野趣及春好，客遊欣此辭。","入雲投館僻，采碧過帆遲。","江上日迴首，琴中勞別思。","春鴻刷歸翼，一寄杜蘅枝。"]', '["水国嘗独往，送君還念茲。","湖山远近色，昏旦煙霞时。","子好謝公跡，常吟孤嶼诗。","果乘扁舟去，若與白鷗期。","野趣及春好，客游欣此辞。","入云投館僻，采碧過帆遲。","江上日迴首，琴中勞別思。","春鴻刷归翼，一寄杜蘅枝。"]', '诗', 'shi', '', NULL, '送包何東遊 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f1c1974-9bd4-4c4e-acf2-aac18a4f65b6', '酬陶六辭秩歸舊居見柬', '酬陶六辞秩归旧居见柬', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["靖節昔高尚，令孫嗣清徽。","舊廬雲峰下，獻歲車騎歸。","去俗因解綬，憶山得採薇。","田疇春事起，里巷相尋稀。","淵明醉乘興，閑門秪掩扉。","花禽驚曙月，鄰女上鳴機。","畢娶願已果，養恬志寧違。","吾當挂朝服，同爾緝荷衣。"]', '["靖節昔高尚，令孫嗣清徽。","旧廬云峰下，獻歲车騎归。","去俗因解綬，憶山得採薇。","田疇春事起，里巷相尋稀。","淵明醉乘兴，闲门秪掩扉。","花禽驚曙月，鄰女上鳴機。","畢娶願已果，養恬志寧違。","吾當挂朝服，同爾緝荷衣。"]', '诗', 'shi', '', NULL, '酬陶六辭秩歸舊居見柬 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96a483bc-6822-490e-a891-e13f609af452', '奉使採箭簳竹谷中晨興赴嶺', '奉使採箭簳竹谷中晨兴赴嶺', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["孤客倦夜坐，聞猨乘早發。","背溪已斜漢，登棧尚殘月。","重峰轉森爽，幽步更超越。","雲木聳鶴巢，風蘿掃虎穴。","人羣從自遠，世役終難歇。","入山非買山，采竹異采蕨。","誰見子牟意，悁勞書魏闕。"]', '["孤客倦夜坐，闻猨乘早發。","背溪已斜漢，登棧尚殘月。","重峰轉森爽，幽步更超越。","云木聳鹤巢，风蘿掃虎穴。","人羣從自远，世役終难歇。","入山非買山，采竹異采蕨。","誰见子牟意，悁勞书魏闕。"]', '诗', 'shi', '', NULL, '奉使採箭簳竹谷中晨興赴嶺 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb61ff3e-c0ed-42c4-9d5f-932620e10267', '同嚴逸人東溪泛舟', '同嚴逸人东溪泛舟', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["子陵江海心，高跡此閑放。","漁舟在溪水，曾是敦夙尚。","朝霽收雲物，垂綸獨清曠。","寒花古岸傍，唳鶴晴沙上。","紛吾好貞逸，不遠來相訪。","已接方外遊，仍陪郢中唱。","歡言盡佳酌，高興延秋望。","日暮浩歌還，紅霞亂青嶂。"]', '["子陵江海心，高跡此闲放。","漁舟在溪水，曾是敦夙尚。","朝霽收云物，垂綸独清曠。","寒花古岸傍，唳鹤晴沙上。","紛吾好貞逸，不远来相訪。","已接方外游，仍陪郢中唱。","歡言尽佳酌，高兴延秋望。","日暮浩歌還，紅霞亂青嶂。"]', '诗', 'shi', '', NULL, '同嚴逸人東溪泛舟 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c560cd98-91e5-4ff0-933f-5e6c97689ac0', '過沈氏山居', '過沈氏山居', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["雞鳴孤煙起，靜者能卜築。","喬木出雲心，閑門掩山腹。","貧交喜相見，把臂歡不足。","空林留宴言，永日清耳目。","泉聲冷尊俎，荷氣香童僕。","往往仙犬鳴，樵人度深竹。","酒酣出谷口，世網何羈束。","始願今不從，區區折腰祿。"]', '["雞鳴孤煙起，静者能卜築。","喬木出云心，闲门掩山腹。","貧交喜相见，把臂歡不足。","空林留宴言，永日清耳目。","泉声冷尊俎，荷氣香童僕。","往往仙犬鳴，樵人度深竹。","酒酣出谷口，世網何羈束。","始願今不從，區區折腰祿。"]', '诗', 'shi', '', NULL, '過沈氏山居 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4377489d-f898-43dd-869b-2b183e4dd616', '贈柏巖老人', '贈柏巖老人', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["日與麋鹿羣，賢哉買山叟。","龐眉忽相見，避世一何久。","林栖古崖曲，野事佳春後。","瓠葉覆荆扉，栗苞垂甕牖。","獨歌還獨酌，不耕亦不耦。","磽田隔雲溪，多雨長稂莠。","煙霞得情性，身世同芻狗。","寄謝營道人，天真此翁有。"]', '["日與麋鹿羣，賢哉買山叟。","龐眉忽相见，避世一何久。","林栖古崖曲，野事佳春後。","瓠葉覆荆扉，栗苞垂甕牖。","独歌還独酌，不耕亦不耦。","磽田隔云溪，多雨长稂莠。","煙霞得情性，身世同芻狗。","寄謝營道人，天真此翁有。"]', '诗', 'shi', '', NULL, '贈柏巖老人 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74d34a61-03e5-4a1d-be37-db75682317ef', '送薛判官赴蜀', '送薛判官赴蜀', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["橫笛聲轉悲，羽觴酣欲別。","舉目叩關遠，離心不可說。","邊陲勞帝念，日下降才傑。","路極巴水長，天銜劍峰缺。","單車動夙夜，越境正炎節。","星橋過客稀，火井蒸雲熱。","陰符能制勝，千里在坐決。","始見儒者雄，長纓繫餘孽。"]', '["橫笛声轉悲，羽觴酣欲別。","舉目叩关远，離心不可说。","邊陲勞帝念，日下降才傑。","路極巴水长，天銜劍峰缺。","單车动夙夜，越境正炎節。","星橋過客稀，火井蒸云熱。","陰符能制勝，千里在坐決。","始见儒者雄，长纓繫餘孽。"]', '诗', 'shi', '', NULL, '送薛判官赴蜀 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01b077b6-659b-436b-9085-3c693bd0f48c', '詔許昌崔明府拜補闕', '詔許昌崔明府拜補闕', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["儒者久營道，詔書方問賢。","至精一耀世，高步誰同年。","何樹可棲鳳，高梧枝拂天。","脫身鳧舄裏，載筆虎闈前。","日月傳軒后，衣冠真列仙。","則知驪龍珠，不祕清泠泉。","才子貴難見，郢歌空復傳。","惜哉效顰客，心想勞嬋娟。"]', '["儒者久營道，詔书方问賢。","至精一耀世，高步誰同年。","何樹可棲鳳，高梧枝拂天。","脫身鳧舄裏，載笔虎闈前。","日月傳軒后，衣冠真列仙。","則知驪龙珠，不祕清泠泉。","才子貴难见，郢歌空复傳。","惜哉效顰客，心想勞嬋娟。"]', '诗', 'shi', '', NULL, '詔許昌崔明府拜補闕 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('718d9e5a-34a7-4aca-b678-59d3b46cdac3', '仲春晚尋覆釜山', '仲春晚尋覆釜山', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["蝴蝶弄和風，飛花不知晚。","王孫尋芳草，步步忘路遠。","況我愛青山，涉趣皆遊踐。","縈迴必中路，陰晦陽復顯。","古岸生新泉，霞峰映雪巘。","交枝花色異，奇石雲根淺。","碧洞志忘歸，紫芝行可搴。","應嗤嵇叔夜，林臥方沈湎。"]', '["蝴蝶弄和风，飞花不知晚。","王孫尋芳草，步步忘路远。","況我愛青山，涉趣皆游踐。","縈迴必中路，陰晦陽复显。","古岸生新泉，霞峰映雪巘。","交枝花色異，奇石云根淺。","碧洞志忘归，紫芝行可搴。","應嗤嵇叔夜，林臥方沈湎。"]', '诗', 'shi', '', NULL, '仲春晚尋覆釜山 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddc729cd-09a7-4178-bd40-9284abbc7222', '贈東鄰鄭少府', '贈东鄰鄭少府', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["一聞白雪唱，願見清揚久。","誰謂結綬來，得陪趨府後。","小邑藍溪上，卑棲愜所偶。","忘言復連牆，片月亦攜手。","草色同春逕，鶯聲共高柳。","美景百花時，平生一盃酒。","聖朝法天地，以我爲芻狗。","秩滿歸白雲，期君訪谷口。"]', '["一闻白雪唱，願见清揚久。","誰謂結綬来，得陪趨府後。","小邑藍溪上，卑棲愜所偶。","忘言复連牆，片月亦携手。","草色同春逕，鶯声共高柳。","美景百花时，平生一盃酒。","聖朝法天地，以我爲芻狗。","秩满归白云，期君訪谷口。"]', '诗', 'shi', '', NULL, '贈東鄰鄭少府 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ab9a8e7-1c8c-46bd-b852-7d7fa4451978', '謝張法曹萬頃小山暇景見憶', '謝張法曹万頃小山暇景见憶', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["樂道隨去處，養和解朝簪。","茅堂近丹闕，佳致亦何深。","退食不趨府，忘機還在林。","清風亂流上，永日小山陰。","解籜雨中竹，將雛花際禽。","物華對幽寂，弦酌兼詠吟。","自昔仰高步，及茲勞所欽。","郢歌叨繼組，知己復知音。"]', '["乐道隨去处，養和解朝簪。","茅堂近丹闕，佳致亦何深。","退食不趨府，忘機還在林。","清风亂流上，永日小山陰。","解籜雨中竹，將雛花際禽。","物华对幽寂，弦酌兼詠吟。","自昔仰高步，及茲勞所欽。","郢歌叨繼組，知己复知音。"]', '诗', 'shi', '', NULL, '謝張法曹萬頃小山暇景見憶 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6b17d14-af6f-4bb9-9ccd-5fd486bfac52', '罷章陵令山居過中峰道者二首 一', '罷章陵令山居過中峰道者二首 一', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["寧辭園令秩，不改淵明調。","解印無與言，見山始一笑。","幽人還絕境，誰道苦奔峭。","隨雲剩渡溪，出門更垂釣。","吾廬青霞裏，窗樹玄猨嘯。","微月清風來，方知散髮妙。"]', '["寧辞园令秩，不改淵明調。","解印無與言，见山始一笑。","幽人還絕境，誰道苦奔峭。","隨云剩渡溪，出门更垂釣。","吾廬青霞裏，窗樹玄猨嘯。","微月清风来，方知散髮妙。"]', '诗', 'shi', '', NULL, '罷章陵令山居過中峰道者二首 一 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b98c9db8-b90e-47e2-8c01-ba9272aeb2ba', '罷章陵令山居過中峰道者二首 二', '罷章陵令山居過中峰道者二首 二', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["丘壑趣如此，暮年始棲偃。","賴遇無心雲，不笑歸來晚。","鳴鳩拂紅枝，初服傍清畎。","昨日山僧來，猶嫌嘉遯淺。","託君紫陽家，路滅心更遠。","梯雲創其居，抱犢上絕巘。","杏田溪一曲，霞境峰幾轉。","路石挂飛泉，謝公應在眼。","願言攜手去，採藥長不返。"]', '["丘壑趣如此，暮年始棲偃。","賴遇無心云，不笑归来晚。","鳴鳩拂紅枝，初服傍清畎。","昨日山僧来，猶嫌嘉遯淺。","託君紫陽家，路滅心更远。","梯云創其居，抱犢上絕巘。","杏田溪一曲，霞境峰幾轉。","路石挂飞泉，謝公應在眼。","願言携手去，採藥长不返。"]', '诗', 'shi', '', NULL, '罷章陵令山居過中峰道者二首 二 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cba72aae-1578-4a21-a2ff-3dd200e1ff52', '登覆釜山遇道人二首 一', '登覆釜山遇道人二首 一', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["晨策趣無涯，名山深轉秀。","三休變覆景，萬轉迷宇宙。","攀崖到天窗，入洞窮玉溜。","側逕蹲怪石，飛蘿擲驚狖。","花間鍊藥人，雞犬和乳竇。","散髮便迎客，采芝仍滿袖。","郭璞賦遊仙，始願今可就。"]', '["晨策趣無涯，名山深轉秀。","三休变覆景，万轉迷宇宙。","攀崖到天窗，入洞窮玉溜。","側逕蹲怪石，飞蘿擲驚狖。","花间鍊藥人，雞犬和乳竇。","散髮便迎客，采芝仍满袖。","郭璞賦游仙，始願今可就。"]', '诗', 'shi', '', NULL, '登覆釜山遇道人二首 一 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4c64173-3d40-45fc-8f6b-a9e76e38b50e', '登覆釜山遇道人二首 二', '登覆釜山遇道人二首 二', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["真氣重嶂裏，知君嘉遯幽。","山堦壓丹穴，藥井通洑流。","道者帶經出，洞中攜我遊。","欲驂白蜺去，且爲紫芝留。","忽憶武陵事，別家疑數秋。"]', '["真氣重嶂裏，知君嘉遯幽。","山堦壓丹穴，藥井通洑流。","道者带經出，洞中携我游。","欲驂白蜺去，且爲紫芝留。","忽憶武陵事，別家疑數秋。"]', '诗', 'shi', '', NULL, '登覆釜山遇道人二首 二 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ceb871e-c8a7-488a-95e9-46d34a6f088f', '尋華山雲臺觀道士', '尋华山云台观道士', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["秋日西山明，勝趣引孤策。","桃源數曲盡，洞口兩岸坼。","還從罔象來，忽得仙靈宅。","霓裳誰之子，霞酌能止客。","殘陽在翠微，攜手更登歷。","林行拂煙雨，溪望亂金碧。","飛鳥下天窗，褭松際雲壁。","稍尋玄蹤遠，宛入寥天寂。","願言葛仙翁，終年鍊玉液。"]', '["秋日西山明，勝趣引孤策。","桃源數曲尽，洞口兩岸坼。","還從罔象来，忽得仙靈宅。","霓裳誰之子，霞酌能止客。","殘陽在翠微，携手更登歷。","林行拂煙雨，溪望亂金碧。","飞鸟下天窗，褭松際云壁。","稍尋玄蹤远，宛入寥天寂。","願言葛仙翁，終年鍊玉液。"]', '诗', 'shi', '', NULL, '尋華山雲臺觀道士 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c154375-4cf7-4a77-b792-b211e2dc4842', '海上臥病寄王臨', '海上臥病寄王臨', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["離客窮海陰，蕭辰歸思結。","一隨浮雲滯，幾怨黃鵠別。","妙年即沈痾，生事多所闕。","劒中負明義，枕上惜玄髮。","之子良史才，華簪偶時哲。","相思千里道，愁望飛鳥絕。","歲暮冰雪寒，淮湖不可越。","百年去心慮，孤影守薄劣。","獨餘慕侶情，金石無休歇。"]', '["離客窮海陰，蕭辰归思結。","一隨浮云滯，幾怨黄鵠別。","妙年即沈痾，生事多所闕。","劒中負明義，枕上惜玄髮。","之子良史才，华簪偶时哲。","相思千里道，愁望飞鸟絕。","歲暮冰雪寒，淮湖不可越。","百年去心慮，孤影守薄劣。","独餘慕侶情，金石無休歇。"]', '诗', 'shi', '', NULL, '海上臥病寄王臨 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bdc4aa6-9b3f-4243-9d45-825d13267797', '登玉山諸峰偶至悟真寺', '登玉山諸峰偶至悟真寺', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["郭南雲水佳，訟簡野情發。","紫芝每相引，黃綬不能緤。","稍入石門幽，始知靈境絕。","冥搜未寸晷，仙逕俄九折。","蟠木蓋石梁，崩岸露雲穴。","數峰拔崑崙，秀色與空澈。","玉氣交晴虹，桂花留曙月。","半巖採珉者，一點如片雪。","真賞無前程，奇觀寧暫輟。","更聞東林磬，可聽不可說。","興中尋覺化，寂爾諸象滅。"]', '["郭南云水佳，訟簡野情發。","紫芝每相引，黄綬不能緤。","稍入石门幽，始知靈境絕。","冥搜未寸晷，仙逕俄九折。","蟠木蓋石梁，崩岸露云穴。","數峰拔崑崙，秀色與空澈。","玉氣交晴虹，桂花留曙月。","半巖採珉者，一点如片雪。","真賞無前程，奇观寧暫輟。","更闻东林磬，可听不可说。","兴中尋覺化，寂爾諸象滅。"]', '诗', 'shi', '', NULL, '登玉山諸峰偶至悟真寺 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f50b001-74c4-4c85-a2a3-626560010c86', '長安客舍贈李行父明府', '长安客舍贈李行父明府', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["藏器待時少，知人自古難。","遂令丹穴鳳，晚食金琅玕。","誰謂兵戈際，鳴琴方一彈。","理煩善用簡，濟猛能兼寬。","夙夜念黎庶，寢興非宴安。","洪波未靜壑，何樹不驚鸞。","鳧舄傍京輦，甿心懸灌壇。","高槐暗苦雨，長劍生秋寒。","旅食還爲客，饑年亦盡歡。","親勞攜斗水，往往救泥蟠。","但恐酬明義，蹉跎芳歲闌。"]', '["藏器待时少，知人自古难。","遂令丹穴鳳，晚食金琅玕。","誰謂兵戈際，鳴琴方一彈。","理煩善用簡，濟猛能兼寬。","夙夜念黎庶，寢兴非宴安。","洪波未静壑，何樹不驚鸾。","鳧舄傍京輦，甿心懸灌壇。","高槐暗苦雨，长劍生秋寒。","旅食還爲客，饑年亦尽歡。","親勞携斗水，往往救泥蟠。","但恐酬明義，蹉跎芳歲闌。"]', '诗', 'shi', '', NULL, '長安客舍贈李行父明府 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('426d940d-bdcc-4ea8-bcdd-018eb4e9f030', '美楊侍御清文見示', '美楊侍御清文见示', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["伯牙道喪來，弦絕無人續。","誰知絕唱後，更有難和曲。","層峰與清流，逸勢競奔蹙。","清文不出戶，仿像皆在目。","霧雪看滿懷，蘭荃坐盈掬。","孤光碧潭月，一片崑崙玉。","初見歌陽春，韶光變枯木。","再見吟白雪，便覺雲肅肅。","則知造化源，方寸能展縮。","斯文不易遇，清爽心豈足。","願言書諸紳，可以爲佩服。"]', '["伯牙道喪来，弦絕無人續。","誰知絕唱後，更有难和曲。","層峰與清流，逸勢競奔蹙。","清文不出戶，仿像皆在目。","霧雪看满懷，蘭荃坐盈掬。","孤光碧潭月，一片崑崙玉。","初见歌陽春，韶光变枯木。","再见吟白雪，便覺云肅肅。","則知造化源，方寸能展縮。","斯文不易遇，清爽心豈足。","願言书諸紳，可以爲佩服。"]', '诗', 'shi', '', NULL, '美楊侍御清文見示 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34f5e0f3-6c43-46fd-b73b-d3e4579545cf', '山居新種花藥與道土同遊賦詩', '山居新種花藥與道土同游賦诗', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["自樂魚鳥性，寧求農牧資。","淺深愛巖壑，疏鑿盡幽奇。","雨花相助好，鶯鳴春草時。","種蘭入山翠，引葛上花枝。","風露拆紅紫，緣溪復映池。","新泉香杜若，片石引江蘺。","宛謂武陵洞，潛鷹造化移。","杖策攜煙客，滿袖掇芳蕤。","蝴蝶舞留我，仙雞閑傍籬。","但令黃精熟，不慮韶光遲。","笑指雲蘿逕，樵人那得知。"]', '["自乐鱼鸟性，寧求農牧資。","淺深愛巖壑，疏鑿尽幽奇。","雨花相助好，鶯鳴春草时。","種蘭入山翠，引葛上花枝。","风露拆紅紫，緣溪复映池。","新泉香杜若，片石引江蘺。","宛謂武陵洞，潛鷹造化移。","杖策携煙客，满袖掇芳蕤。","蝴蝶舞留我，仙雞闲傍籬。","但令黄精熟，不慮韶光遲。","笑指云蘿逕，樵人那得知。"]', '诗', 'shi', '', NULL, '山居新種花藥與道土同遊賦詩 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dbaa97c-7606-44ca-9dbd-ea6f62448025', '初黃綬赴藍田縣作', '初黄綬赴藍田縣作', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["蟠木無匠伯，終年棄山樊。","苦心非良知，安得入君門。","忽忝英達顧，寧窺造化恩。","螢光起腐草，雲翼騰沈鯤。","片石世何用，良工心所存。","一叨尉京甸，三省慚黎元。","賢尹正趨府，僕夫儼歸軒。","眼中縣胥色，耳裏蒼生言。","居人散山水，即景真桃源。","鹿聚入田逕，雞鳴隔嶺村。","飡和俗久清，到邑政空論。","且嘉訟庭寂，前階滿芳蓀。"]', '["蟠木無匠伯，終年棄山樊。","苦心非良知，安得入君门。","忽忝英達顧，寧窺造化恩。","螢光起腐草，云翼腾沈鯤。","片石世何用，良工心所存。","一叨尉京甸，三省慚黎元。","賢尹正趨府，僕夫儼归軒。","眼中縣胥色，耳裏蒼生言。","居人散山水，即景真桃源。","鹿聚入田逕，雞鳴隔嶺村。","飡和俗久清，到邑政空論。","且嘉訟庭寂，前階满芳蓀。"]', '诗', 'shi', '', NULL, '初黃綬赴藍田縣作 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b388c43-8ac8-412d-b310-d063c4149afa', '歸義寺題震上人壁', '归義寺題震上人壁', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["入谷逢雨花，香綠引幽步。","招提饒泉石，萬轉同一趣。","向背森碧峰，淺深羅古樹。","堯皇未登極，此地曾隱霧。","祕讖得神謀，因高思虎踞。","太陽忽臨照，物象俄光煦。","梵王宮始開，長者金先布。","白水入禪境，碭山通覺路。","往往無心雲，猶起潛龍處。","仍聞七祖後，佛子繼調御。","溪鳥投慧燈，山蟬飽甘露。","不作解纓客，寧知捨筏喻。","身世已悟空，歸途復何去。"]', '["入谷逢雨花，香綠引幽步。","招提饒泉石，万轉同一趣。","向背森碧峰，淺深羅古樹。","堯皇未登極，此地曾隐霧。","祕讖得神謀，因高思虎踞。","太陽忽臨照，物象俄光煦。","梵王宮始开，长者金先布。","白水入禪境，碭山通覺路。","往往無心云，猶起潛龙处。","仍闻七祖後，佛子繼調御。","溪鸟投慧灯，山蟬飽甘露。","不作解纓客，寧知捨筏喻。","身世已悟空，归途复何去。"]', '诗', 'shi', '', NULL, '歸義寺題震上人壁 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ca2e832-3b2c-479c-ba5a-173018656d79', '奉和聖製登會昌山應制', '奉和聖製登會昌山應制', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["睿想入希夷，真遊到具茨。","玉鑾登嶂遠，雲輅出花遲。","泉壑凝神處，陽和布澤時。","六龍多順動，四海正雍熙。"]', '["睿想入希夷，真游到具茨。","玉鑾登嶂远，云輅出花遲。","泉壑凝神处，陽和布澤时。","六龙多順动，四海正雍熙。"]', '诗', 'shi', '', NULL, '奉和聖製登會昌山應制 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd4a34f9-8b94-4729-af0f-6e14d6dce327', '省中對雪寄元判官拾遺昆季', '省中对雪寄元判官拾遺昆季', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["萬點瑤臺雪，飛來錦帳前。","瓊枝應比淨，鶴髮敢爭先。","散影成花月，流光透竹煙。","今朝謝家興，幾處郢歌傳。"]', '["万点瑤台雪，飞来錦帳前。","瓊枝應比淨，鹤髮敢爭先。","散影成花月，流光透竹煙。","今朝謝家兴，幾处郢歌傳。"]', '诗', 'shi', '', NULL, '省中對雪寄元判官拾遺昆季 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e24f1757-676d-440e-a4aa-40759524f9e8', '山齋獨坐喜玄上人夕至', '山斋独坐喜玄上人夕至', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["舍下虎溪徑，煙霞入暝開。","柴門兼竹靜，山月與僧來。","心瑩紅蓮水，言忘綠茗杯。","前峰曙更好，斜漢欲西迴。"]', '["舍下虎溪徑，煙霞入暝开。","柴门兼竹静，山月與僧来。","心瑩紅蓮水，言忘綠茗杯。","前峰曙更好，斜漢欲西迴。"]', '诗', 'shi', '', NULL, '山齋獨坐喜玄上人夕至 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91fbd4dc-24ea-4f79-8a47-69744f4acd35', '秋夜寄張韋二主簿', '秋夜寄張韋二主簿', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["涼夜褰簾好，輕雲過月初。","碧空河色淺，紅葉露聲虛。","道阻天難問，機忘世易疎。","不知雙翠鳳，棲棘復何如。"]', '["涼夜褰簾好，轻云過月初。","碧空河色淺，紅葉露声虛。","道阻天难问，機忘世易疎。","不知雙翠鳳，棲棘复何如。"]', '诗', 'shi', '', NULL, '秋夜寄張韋二主簿 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66f4e9d7-1d9a-41b7-bbe7-b2dedede83dd', '歸故山路逢鄰居隱者', '归故山路逢鄰居隐者', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["握手雲棲路，澘然恨幾重。","誰知綠林盜，長占彩霞峰。","心死池塘草，聲悲石徑松。","無因芳杜月，琴酒更相逢。"]', '["握手云棲路，澘然恨幾重。","誰知綠林盜，长占彩霞峰。","心死池塘草，声悲石徑松。","無因芳杜月，琴酒更相逢。"]', '诗', 'shi', '', NULL, '歸故山路逢鄰居隱者 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8b24b6c-5c3e-4292-b4ab-dd39f8fe13c6', '落第劉拾遺相送東歸', '落第劉拾遺相送东归', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["不醉百花酒，傷心千里歸。","獨收和氏玉，還採舊山薇。","出處離心盡，榮枯會面稀。","預愁芳草色，一徑入衡闈。"]', '["不醉百花酒，傷心千里归。","独收和氏玉，還採旧山薇。","出处離心尽，榮枯會面稀。","預愁芳草色，一徑入衡闈。"]', '诗', 'shi', '', NULL, '落第劉拾遺相送東歸 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88a56b30-c190-4149-9876-6751971c2597', '和劉七讀書', '和劉七读书', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["夜雨深館靜，苦心黃卷前。","雲陰留墨沼，螢影傍華編。","夢鳥富清藻，通經仍妙年。","何愁丹穴鳳，不飲玉池泉。"]', '["夜雨深館静，苦心黄卷前。","云陰留墨沼，螢影傍华編。","梦鸟富清藻，通經仍妙年。","何愁丹穴鳳，不饮玉池泉。"]', '诗', 'shi', '', NULL, '和劉七讀書 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d825ed4-f12c-47f9-b1c4-f07beafa26ea', '早下江寧', '早下江寧', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["暮天微雨散，涼吹片帆輕。","雲物高秋節，山川孤客情。","霜蘋留楚水，寒鴈別吳城。","宿浦有歸夢，愁猨莫夜鳴。"]', '["暮天微雨散，涼吹片帆轻。","云物高秋節，山川孤客情。","霜蘋留楚水，寒鴈別吳城。","宿浦有归梦，愁猨莫夜鳴。"]', '诗', 'shi', '', NULL, '早下江寧 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('870497b5-1b87-4628-8312-ca514ec68006', '登復州南樓', '登复州南楼', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["孤樹延春日，他山捲曙霞。","客心湖上鴈，歸思日邊花。","行李迷方久，歸期涉歲賒。"]', '["孤樹延春日，他山捲曙霞。","客心湖上鴈，归思日邊花。","行李迷方久，归期涉歲賒。"]', '诗', 'shi', '', NULL, '登復州南樓 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ddd99a6-8dde-485c-afdb-a774d9c4daef', '江陵晦日陪諸官泛舟', '江陵晦日陪諸官泛舟', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["節物堪爲樂，江湖有主人。","舟行深更好，山趣久彌新。","尊酒平生意，煙花異國春。","城南無夜月，長袖莫留賓。"]', '["節物堪爲乐，江湖有主人。","舟行深更好，山趣久彌新。","尊酒平生意，煙花異国春。","城南無夜月，长袖莫留賓。"]', '诗', 'shi', '', NULL, '江陵晦日陪諸官泛舟 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11afd30d-0798-46ec-b62d-28bfe2cbc1ba', '縣城秋夕', '縣城秋夕', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["山城日易夕，愁生先掩扉。","俸薄不沽酒，家貧忘授衣。","露重蕙花落，月冷莎難飛。","効拙慚無補，雲林歎再歸。"]', '["山城日易夕，愁生先掩扉。","俸薄不沽酒，家貧忘授衣。","露重蕙花落，月冷莎难飞。","効拙慚無補，云林歎再归。"]', '诗', 'shi', '', NULL, '縣城秋夕 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a95630b-2c86-4bcc-b735-eb3176a8d023', '秋夜梁七兵曹同宿二首 一', '秋夜梁七兵曹同宿二首 一', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["一笑不可得，同心相見稀。","摘菱頻貰酒，待月未扃扉。","星影低驚鵲，蟲聲傍旅衣。","卑棲歲已晚，共羨鴈南飛。"]', '["一笑不可得，同心相见稀。","摘菱頻貰酒，待月未扃扉。","星影低驚鵲，蟲声傍旅衣。","卑棲歲已晚，共羨鴈南飞。"]', '诗', 'shi', '', NULL, '秋夜梁七兵曹同宿二首 一 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db9d91d8-9d41-4922-82a7-1c8d23f66238', '秋夜梁七兵曹同宿二首 二', '秋夜梁七兵曹同宿二首 二', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["好欲棄吾道，今宵又遇君。","老夫相勸酒，稚子待題文。","月下誰家笛，城頭幾片雲。","如何此幽興，明日重離羣。"]', '["好欲棄吾道，今宵又遇君。","老夫相勸酒，稚子待題文。","月下誰家笛，城头幾片云。","如何此幽兴，明日重離羣。"]', '诗', 'shi', '', NULL, '秋夜梁七兵曹同宿二首 二 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e034e19d-8938-4d73-934c-4a656426dbc3', '和萬年成少府寓直', '和万年成少府寓直', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["赤縣新秋夜，文人藻思催。","鐘聲自仙掖，月色近霜臺。","一葉兼螢度，孤雲帶鴈來。","明朝紫書下，應問長卿才。"]', '["赤縣新秋夜，文人藻思催。","鐘声自仙掖，月色近霜台。","一葉兼螢度，孤云带鴈来。","明朝紫书下，應问长卿才。"]', '诗', 'shi', '', NULL, '和萬年成少府寓直 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8d2011c-dc24-4e9a-a795-92e7473c7ad1', '春夜過長孫繹別業', '春夜過长孫繹別業', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["佳期難再得，清夜此雲林。","帶竹新泉冷，穿花片月深。","含毫凝逸思，酌水話幽心。","不覺星河轉，山枝驚曙禽。"]', '["佳期难再得，清夜此云林。","带竹新泉冷，穿花片月深。","含毫凝逸思，酌水話幽心。","不覺星河轉，山枝驚曙禽。"]', '诗', 'shi', '', NULL, '春夜過長孫繹別業 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80f35550-53c7-4dd4-a386-0710a32fd153', '題溫處士山居', '題溫处士山居', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["誰知白雲外，別有綠蘿春。","苔繞溪邊徑，花深洞裏人。","逸妻看種藥，稚子伴垂綸。","潁上逃堯者，何如此養真。"]', '["誰知白云外，別有綠蘿春。","苔繞溪邊徑，花深洞裏人。","逸妻看種藥，稚子伴垂綸。","潁上逃堯者，何如此養真。"]', '诗', 'shi', '', NULL, '題溫處士山居 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e3ff051-fdb1-404f-9e68-934a16173b9d', '題陳季壁', '題陳季壁', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["郢人何苦調，飲水仍布衾。","煙火晝不起，蓬蒿春欲深。","前庭少喬木，鄰舍聞新禽。","雖有徵賢詔，終傷不遇心。"]', '["郢人何苦調，饮水仍布衾。","煙火晝不起，蓬蒿春欲深。","前庭少喬木，鄰舍闻新禽。","雖有徵賢詔，終傷不遇心。"]', '诗', 'shi', '', NULL, '題陳季壁 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f205b0a-46af-47d6-84c4-7e446aa0a9e3', '贈鄰居齊六司倉', '贈鄰居齊六司倉', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["沈冥衆所遺，咫尺絕佳期。","始覺衡門下，翛然太古時。","雞聲共鄰巷，燭影隔茅茨。","坐惜牛羊逕，芳蓀白露滋。"]', '["沈冥衆所遺，咫尺絕佳期。","始覺衡门下，翛然太古时。","雞声共鄰巷，燭影隔茅茨。","坐惜牛羊逕，芳蓀白露滋。"]', '诗', 'shi', '', NULL, '贈鄰居齊六司倉 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c28f2ecf-ebf2-4509-a621-b726f62af5a2', '送征鴈', '送征鴈', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["秋空萬里淨，嘹唳獨南征。","風急翻霜冷，雲開見月驚。","塞長怯去翼，影滅有餘聲。","悵望遙天外，鄉愁滿目生。"]', '["秋空万里淨，嘹唳独南征。","风急翻霜冷，云开见月驚。","塞长怯去翼，影滅有餘声。","悵望遙天外，乡愁满目生。"]', '诗', 'shi', '', NULL, '送征鴈 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1497c98-2f27-4350-aacd-dff5667b4ca6', '宴鬱林觀張道士房', '宴鬱林观張道士房', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["滅跡人間世，忘歸象外情。","竹壇秋月冷，山殿夜鐘清。","仙侶披雲集，霞杯達曙斜。","同歡不可再，朝暮赤龍迎。"]', '["滅跡人间世，忘归象外情。","竹壇秋月冷，山殿夜鐘清。","仙侶披云集，霞杯達曙斜。","同歡不可再，朝暮赤龙迎。"]', '诗', 'shi', '', NULL, '宴鬱林觀張道士房 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a795cf16-8572-40f7-91dc-37300ae34782', '秋夕與梁鍠文宴', '秋夕與梁鍠文宴', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["客到衡門下，林香蕙草時。","好風能自至，明月不須期。","秋日翻荷影，晴光脆柳枝。","留歡美清夜，寧覺曉鐘遲。"]', '["客到衡门下，林香蕙草时。","好风能自至，明月不須期。","秋日翻荷影，晴光脆柳枝。","留歡美清夜，寧覺晓鐘遲。"]', '诗', 'shi', '', NULL, '秋夕與梁鍠文宴 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2070b3e-05ee-448c-b938-55313c1e0930', '哭空寂寺玄上人', '哭空寂寺玄上人', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["悽然雙樹下，垂淚遠公房。","燈續生前火，爐添沒後香。","陰堦明片雪，寒竹響空廊。","寂滅應爲樂，塵心徒自傷。"]', '["悽然雙樹下，垂泪远公房。","灯續生前火，爐添沒後香。","陰堦明片雪，寒竹响空廊。","寂滅應爲乐，塵心徒自傷。"]', '诗', 'shi', '', NULL, '哭空寂寺玄上人 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fae3e2e-eca8-4e95-a80d-f04ff4a0a139', '題精舍寺', '題精舍寺', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["勝景不易遇，入門神頓清。","房房占山色，處處分泉聲。","詩思竹間得，道心松下生。","何時來此地，擺落世間情。"]', '["勝景不易遇，入门神頓清。","房房占山色，处处分泉声。","诗思竹间得，道心松下生。","何时来此地，擺落世间情。"]', '诗', 'shi', '', NULL, '題精舍寺 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd320057-e939-44de-9e43-3b0dc118f8c4', '開元觀遇張侍御', '开元观遇張侍御', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["碧落忘歸處，佳期不厭逢。","晚涼生玉井，新暑避煙松。","欲醉流霞酌，還醒度竹鐘。","更憐琪樹下，歷歷見遙峰。"]', '["碧落忘归处，佳期不厭逢。","晚涼生玉井，新暑避煙松。","欲醉流霞酌，還醒度竹鐘。","更怜琪樹下，歷歷见遙峰。"]', '诗', 'shi', '', NULL, '開元觀遇張侍御 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6cbbc32-11dd-42a0-9ab1-dcf9033bcaa0', '和人秋歸終南山別業', '和人秋归終南山別業', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["舊居三顧後，晚節重幽尋。","野逕到門盡，山窗連竹陰。","昔年鶯山谷，今日鳳歸林。","物外凌雲操，誰能繼此心。"]', '["旧居三顧後，晚節重幽尋。","野逕到门尽，山窗連竹陰。","昔年鶯山谷，今日鳳归林。","物外凌云操，誰能繼此心。"]', '诗', 'shi', '', NULL, '和人秋歸終南山別業 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abb5650b-f4be-4bcd-9d25-a04c06f66612', '故相國苗公挽歌', '故相国苗公挽歌', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["灞陵誰寵葬，漢主念蕭何。","盛業留青史，浮榮逐逝波。","隴雲仍作雨，薤露已成歌。","悽愴平津閣，秋風弔客過。"]', '["灞陵誰寵葬，漢主念蕭何。","盛業留青史，浮榮逐逝波。","隴云仍作雨，薤露已成歌。","悽愴平津閣，秋风弔客過。"]', '诗', 'shi', '', NULL, '故相國苗公挽歌 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd2c5bc7-370f-4fb8-a5c0-47c9cdf17218', '酬劉員外雨中見寄', '酬劉員外雨中见寄', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["苦雨滴蘭砌，秋風生葛衣。","潢污三逕絕，砧杵四鄰稀。","分與玄豹隱，不爲湘燕飛。","慚君角巾折，猶肯問衡闈。"]', '["苦雨滴蘭砌，秋风生葛衣。","潢污三逕絕，砧杵四鄰稀。","分與玄豹隐，不爲湘燕飞。","慚君角巾折，猶肯问衡闈。"]', '诗', 'shi', '', NULL, '酬劉員外雨中見寄 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9282ea7-ac4d-4f66-a960-517e1420d1b7', '賦得歸雲送李山人歸華山', '賦得归云送李山人归华山', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["秀色橫千里，歸雲積幾重。","欲依毛女岫，初卷少姨峰。","蓋影隨征馬，衣香拂臥龍。","秪應函谷上，真氣日溶溶。"]', '["秀色橫千里，归云積幾重。","欲依毛女岫，初卷少姨峰。","蓋影隨征马，衣香拂臥龙。","秪應函谷上，真氣日溶溶。"]', '诗', 'shi', '', NULL, '賦得歸雲送李山人歸華山 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0102e9d2-3488-495e-a148-393235f77168', '過裴長官新亭', '過裴长官新亭', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["茅屋多新意，芳林昨試移。","野人知石路，戲鳥認花枝。","慢水縈蓬戶，閑雲挂竹籬。","到家成一醉，歸馬不能騎。"]', '["茅屋多新意，芳林昨試移。","野人知石路，戲鸟認花枝。","慢水縈蓬戶，闲云挂竹籬。","到家成一醉，归马不能騎。"]', '诗', 'shi', '', NULL, '過裴長官新亭 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b51f625-6e0f-4814-9fd0-5477aea04478', '寄郢州郎士元使君', '寄郢州郎士元使君', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["龍節知無事，江城不掩扉。","詩傳過客遠，書到故人稀。","坐嘯看潮起，行春送鴈歸。","望舒三五夜，思盡謝玄暉。"]', '["龙節知無事，江城不掩扉。","诗傳過客远，书到故人稀。","坐嘯看潮起，行春送鴈归。","望舒三五夜，思尽謝玄暉。"]', '诗', 'shi', '', NULL, '寄郢州郎士元使君 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0b251a5-be1f-43fe-bcf5-f87911834bdd', '過長孫宅與朗上人茶會', '過长孫宅與朗上人茶會', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["偶與息心侶，忘歸才子家。","玄談兼藻思，綠茗代榴花。","岸幘看雲卷，含毫任景斜。","松喬若逢此，不復醉流霞。"]', '["偶與息心侶，忘归才子家。","玄談兼藻思，綠茗代榴花。","岸幘看云卷，含毫任景斜。","松喬若逢此，不复醉流霞。"]', '诗', 'shi', '', NULL, '過長孫宅與朗上人茶會 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18e0b8cc-e35e-44c2-9756-c08d1bd2a2f6', '下第題長安客舍', '下第題长安客舍', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["不遂青雲望，愁看黃鳥飛。","棃花度寒食，客子未春衣。","世事隨時變，交情與我違。","空餘主人柳，相見却依依。"]', '["不遂青云望，愁看黄鸟飞。","棃花度寒食，客子未春衣。","世事隨时变，交情與我違。","空餘主人柳，相见却依依。"]', '诗', 'shi', '', NULL, '下第題長安客舍 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c80573c-dcba-49fb-a6e0-7560e4e049bf', '陪考功王員外城東池亭宴', '陪考功王員外城东池亭宴', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["無雙錦帳郎，絕境有林塘。","鶴靜疎羣羽，蓬開失衆芳。","晴山看不厭，流水趣何長。","日晚催歸騎，鐘聲下夕陽。"]', '["無雙錦帳郎，絕境有林塘。","鹤静疎羣羽，蓬开失衆芳。","晴山看不厭，流水趣何长。","日晚催归騎，鐘声下夕陽。"]', '诗', 'shi', '', NULL, '陪考功王員外城東池亭宴 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0184a8fb-c02b-4699-b211-6e812551c1f7', '過孫員外藍田山居', '過孫員外藍田山居', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["不知香署客，謝病翠微間。","去幄蘭將老，辭車雉亦閑。","近窗雲出洞，當戶竹連山。","對酒溪霞晚，家人採蕨還。"]', '["不知香署客，謝病翠微间。","去幄蘭將老，辞车雉亦闲。","近窗云出洞，當戶竹連山。","对酒溪霞晚，家人採蕨還。"]', '诗', 'shi', '', NULL, '過孫員外藍田山居 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e38096c1-8394-4dec-89f3-de0e43594944', '秋園晚沐', '秋园晚沐', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["黃卷在窮巷，歸來生道心。","五株衰柳下，三徑小園深。","倒薤翻成字，寒花不假林。","龐眉謝羣彥，獨酌且閑吟。"]', '["黄卷在窮巷，归来生道心。","五株衰柳下，三徑小园深。","倒薤翻成字，寒花不假林。","龐眉謝羣彥，独酌且闲吟。"]', '诗', 'shi', '', NULL, '秋園晚沐 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4389f1ff-feca-448f-9542-a8e9d2dabeb2', '窮秋對雨', '窮秋对雨', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["晦日連苦雨，動息更邅迴。","生事萍無定，愁心雲不開。","翟門悲暝雀，墨竈上寒苔。","始信宜城守，乘流畏曝腮。"]', '["晦日連苦雨，动息更邅迴。","生事萍無定，愁心云不开。","翟门悲暝雀，墨竈上寒苔。","始信宜城守，乘流畏曝腮。"]', '诗', 'shi', '', NULL, '窮秋對雨 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51c06436-24b4-4161-a8d0-d5e63547b52c', '裴迪南門秋夜對月', '裴迪南门秋夜对月', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["夜來詩酒興，月滿謝公樓。","影閉重門靜，寒生獨樹秋。","鵲驚隨葉散，螢遠入煙流。","今夕遙天末，清光幾處愁。"]', '["夜来诗酒兴，月满謝公楼。","影閉重门静，寒生独樹秋。","鵲驚隨葉散，螢远入煙流。","今夕遙天末，清光幾处愁。"]', '诗', 'shi', '', NULL, '裴迪南門秋夜對月 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('715c0b46-b62a-47f1-9ebc-485d96308141', '和蜀縣段明府秋城望歸期', '和蜀縣段明府秋城望归期', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["製錦蜀江靜，飛鳧漢闕遙。","一茲風靡草，再視露盈條。","旅望多愁思，秋天更泬寥。","河陽傳麗藻，清韻入歌謠。"]', '["製錦蜀江静，飞鳧漢闕遙。","一茲风靡草，再視露盈條。","旅望多愁思，秋天更泬寥。","河陽傳丽藻，清韻入歌謠。"]', '诗', 'shi', '', NULL, '和蜀縣段明府秋城望歸期 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8d11097-ddd2-4ec5-9bcd-e47676e01f82', '晚歸藍田酬王維給事贈別', '晚归藍田酬王維給事贈別', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["卑棲却得性，每與白雲歸。","徇祿仍懷橘，看山免採薇。","暮禽先去馬，新月待開扉。","霄漢時回首，知音青瑣闈。"]', '["卑棲却得性，每與白云归。","徇祿仍懷橘，看山免採薇。","暮禽先去马，新月待开扉。","霄漢时回首，知音青瑣闈。"]', '诗', 'shi', '', NULL, '晚歸藍田酬王維給事贈別 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3afa795-acd1-41ca-a63a-a5d2d6bf4e03', '再得畢侍御書聞巴中臥病', '再得畢侍御书闻巴中臥病', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["芳信來相續，同心遠更親。","數重雲外樹，不隔眼中人。","夢寐花驄色，相思黃鳥春。","更聞公幹病，一夜二毛新。"]', '["芳信来相續，同心远更親。","數重云外樹，不隔眼中人。","梦寐花驄色，相思黄鸟春。","更闻公幹病，一夜二毛新。"]', '诗', 'shi', '', NULL, '再得畢侍御書聞巴中臥病 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6685f109-3162-4c45-be83-60f02090bebe', '宿新里館', '宿新里館', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["愁人待曉雞，秋雨暗淒淒。","度燭螢時滅，傳書鴈漸低。","客來知計誤，夢裏泣津迷。","無以逃悲思，寒螿處處啼。"]', '["愁人待晓雞，秋雨暗淒淒。","度燭螢时滅，傳书鴈漸低。","客来知計誤，梦裏泣津迷。","無以逃悲思，寒螿处处啼。"]', '诗', 'shi', '', NULL, '宿新里館 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b700208d-d859-4e36-96bf-883c81d4df0f', '谷口書齋寄楊補闕', '谷口书斋寄楊補闕', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["泉壑帶茅茨，雲霞生薜帷。","竹憐新雨後，山愛夕陽時。","閑鷺棲常早，秋花落更遲。","家童掃蘿逕，昨與故人期。"]', '["泉壑带茅茨，云霞生薜帷。","竹怜新雨後，山愛夕陽时。","闲鷺棲常早，秋花落更遲。","家童掃蘿逕，昨與故人期。"]', '诗', 'shi', '', NULL, '谷口書齋寄楊補闕 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c45d431-e735-4f15-9068-45a4b3cf300c', '衡門春夜', '衡门春夜', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["不厭晴林下，微風度葛巾。","寧唯北牕月，自謂上皇人。","叢篠輕新暑，孤花占晚春。","寄言莊叟蝶，與爾得天真。"]', '["不厭晴林下，微风度葛巾。","寧唯北牕月，自謂上皇人。","叢篠轻新暑，孤花占晚春。","寄言莊叟蝶，與爾得天真。"]', '诗', 'shi', '', NULL, '衡門春夜 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe7bf6cc-0541-4615-95f7-a16d90404617', '題吳通微主人', '題吳通微主人', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["食貧無盡日，有願幾時諧。","長嘯秋光晚，誰知志士懷。","朝煙不起竈，寒葉欲連堦。","飲水仍留我，孤燈點夜齋。"]', '["食貧無尽日，有願幾时諧。","长嘯秋光晚，誰知志士懷。","朝煙不起竈，寒葉欲連堦。","饮水仍留我，孤灯点夜斋。"]', '诗', 'shi', '', NULL, '題吳通微主人 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b87a2865-9ecd-410d-b86f-b1abb2bee2fb', '晚次宿預館', '晚次宿預館', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["鄉心不可問，秋氣又相逢。","飄泊方千里，離悲復幾重。","迴雲隨去鴈，寒露滴鳴蛩。","延頸遙天末，如聞故國鐘。"]', '["乡心不可问，秋氣又相逢。","飄泊方千里，離悲复幾重。","迴云隨去鴈，寒露滴鳴蛩。","延頸遙天末，如闻故国鐘。"]', '诗', 'shi', '', NULL, '晚次宿預館 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0acbf434-aeb8-4d14-89d9-fbdc5ae84e01', '藍上茅茨期王維補闕', '藍上茅茨期王維補闕', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["山中人不見，雲去夕陽過。","淺瀨寒魚少，叢蘭秋蝶多。","老年疎世事，幽性樂天和。","酒熟思才子，溪頭望玉珂。"]', '["山中人不见，云去夕陽過。","淺瀨寒鱼少，叢蘭秋蝶多。","老年疎世事，幽性乐天和。","酒熟思才子，溪头望玉珂。"]', '诗', 'shi', '', NULL, '藍上茅茨期王維補闕 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deb27b44-93ee-4123-ab36-8a612f0392b8', '春宵寓直', '春宵寓直', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["養拙慣雲臥，爲郎如鳥棲。","不知仙閣峻，惟覺玉繩低。","帳喜香煙暖，詩慚賜筆題。","未央春漏促，殘夢謝晨雞。"]', '["養拙慣云臥，爲郎如鸟棲。","不知仙閣峻，惟覺玉繩低。","帳喜香煙暖，诗慚賜笔題。","未央春漏促，殘梦謝晨雞。"]', '诗', 'shi', '', NULL, '春宵寓直 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb9fec75-f8e3-4c8a-8e59-5c8ba7c1c4d5', '新昌里言懷', '新昌里言懷', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["性拙偶從宦，心閑多掩扉。","雖看北堂草，不忘舊山薇。","花月霽來好，雲泉堪夢歸。","如何建章漏，催著早朝衣。"]', '["性拙偶從宦，心闲多掩扉。","雖看北堂草，不忘旧山薇。","花月霽来好，云泉堪梦归。","如何建章漏，催著早朝衣。"]', '诗', 'shi', '', NULL, '新昌里言懷 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30e8595b-bbcc-4ff3-873f-a5618e4c2c1f', '秋夜寄袁中丞王員外', '秋夜寄袁中丞王員外', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["一夕盈千念，方知別者勞。","衰榮難會面，魂夢暫同袍。","片月臨堦早，晴河度鴈高。","應憐蔣生逕，秋露滿蓬蒿。"]', '["一夕盈千念，方知別者勞。","衰榮难會面，魂梦暫同袍。","片月臨堦早，晴河度鴈高。","應怜蔣生逕，秋露满蓬蒿。"]', '诗', 'shi', '', NULL, '秋夜寄袁中丞王員外 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecf2dcb8-310d-42f1-821d-7a5b85727a89', '九日閑居寄登高數子', '九日闲居寄登高數子', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["初服棲窮巷，重陽憶舊遊。","門閑謝病日，心醉授衣秋。","酒盡寒花笑，庭空暝雀愁。","今朝落帽客，幾處管弦留。"]', '["初服棲窮巷，重陽憶旧游。","门闲謝病日，心醉授衣秋。","酒尽寒花笑，庭空暝雀愁。","今朝落帽客，幾处管弦留。"]', '诗', 'shi', '', NULL, '九日閑居寄登高數子 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('871c7846-e164-4c7b-ad22-07884332ded1', '晚入宣城界', '晚入宣城界', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["斜日片帆陰，春風孤客心。","山來指樵路，岸去惜花林。","海氣蒸雲黑，潮聲隔雨深。","鄉愁不可道，浦宿聽猨吟。"]', '["斜日片帆陰，春风孤客心。","山来指樵路，岸去惜花林。","海氣蒸云黑，潮声隔雨深。","乡愁不可道，浦宿听猨吟。"]', '诗', 'shi', '', NULL, '晚入宣城界 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26443368-af44-4a33-8f76-ec7f78d87448', '靜夜酬通上人問疾', '静夜酬通上人问疾', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["東林生早涼，高枕遠公房。","大士看心後，中宵清漏長。","驚蟬出暗柳，微月隱迴廊。","何事沈痾久，含毫問藥王。"]', '["东林生早涼，高枕远公房。","大士看心後，中宵清漏长。","驚蟬出暗柳，微月隐迴廊。","何事沈痾久，含毫问藥王。"]', '诗', 'shi', '', NULL, '靜夜酬通上人問疾 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9eb063a-1b77-427e-9cce-9d9cec335a16', '奉陪使君十四叔晚憩大雲門寺', '奉陪使君十四叔晚憩大云门寺', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["野寺千家外，閑行晚暫過。","炎氛臨水盡，夕照傍林多。","境對知心妄，人安覺政和。","繩牀搖麈尾，佳趣滿滄波。"]', '["野寺千家外，闲行晚暫過。","炎氛臨水尽，夕照傍林多。","境对知心妄，人安覺政和。","繩牀搖麈尾，佳趣满滄波。"]', '诗', 'shi', '', NULL, '奉陪使君十四叔晚憩大雲門寺 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0e9fe34-bbb9-4763-be64-4d7ea74b65ec', '省中春暮酬嵩陽焦道士見招', '省中春暮酬嵩陽焦道士见招', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["朝花飛暝林，對酒傷春心。","流年催素髮，不覺映華簪。","垂老遇知己，酬恩看寸陰。","如何紫芝客，相憶白雲深。"]', '["朝花飞暝林，对酒傷春心。","流年催素髮，不覺映华簪。","垂老遇知己，酬恩看寸陰。","如何紫芝客，相憶白云深。"]', '诗', 'shi', '', NULL, '省中春暮酬嵩陽焦道士見招 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f38e3009-6e49-4f94-b999-fe189c1e87ce', '酬苗發員外宿龍池寺見寄', '酬苗發員外宿龙池寺见寄', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["寧知待漏客，清夜此從容。","暫別迎車雉，還隨護法龍。","香煙輕上月，林嶺靜聞鐘。","郢曲傳甘露，塵心洗幾重。"]', '["寧知待漏客，清夜此從容。","暫別迎车雉，還隨護法龙。","香煙轻上月，林嶺静闻鐘。","郢曲傳甘露，塵心洗幾重。"]', '诗', 'shi', '', NULL, '酬苗發員外宿龍池寺見寄 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e25d8397-9aa0-434d-8a0e-6bfe7df1ef90', '貞懿皇后挽詞', '貞懿皇后挽词', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["淑麗詩傳美，徽章禮飾哀。","有恩加象服，無日祀高禖。","曉月孤秋殿，寒山出夜臺。","通靈深眷想，青鳥獨飛來。"]', '["淑丽诗傳美，徽章禮飾哀。","有恩加象服，無日祀高禖。","晓月孤秋殿，寒山出夜台。","通靈深眷想，青鸟独飞来。"]', '诗', 'shi', '', NULL, '貞懿皇后挽詞 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a25f4ca-5260-4f87-a6e1-4769ff842b47', '歲初歸舊山', '歲初归旧山', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["欲知愚谷好，久別與春還。","鶯暖初歸樹，雲晴却戀山。","石田耕種少，野客性情閑。","求仲應難見，殘陽且掩關。"]', '["欲知愚谷好，久別與春還。","鶯暖初归樹，云晴却戀山。","石田耕種少，野客性情闲。","求仲應难见，殘陽且掩关。"]', '诗', 'shi', '', NULL, '歲初歸舊山 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b36c019-2f0c-433b-b1a9-a4b5dec9b64b', '鑾駕避狄歲寄別韓雲卿', '鑾駕避狄歲寄別韓云卿', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["白髮壯心死，愁看國步移。","關山慘無色，親愛忽驚離。","影絕龍分劍，聲衰鳥戀枝。","茫茫雲海外，相憶不相知。"]', '["白髮壯心死，愁看国步移。","关山慘無色，親愛忽驚離。","影絕龙分劍，声衰鸟戀枝。","茫茫云海外，相憶不相知。"]', '诗', 'shi', '', NULL, '鑾駕避狄歲寄別韓雲卿 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e38349c3-2b96-4c2a-8516-706cb95510b8', '詠白油帽送客', '詠白油帽送客', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["薄質慚加首，愁陰幸庇身。","卷舒無定日，行止必依人。","已沐脂膏惠，寧辭雨露頻。","雖同客衣色，不染洛陽塵。"]', '["薄質慚加首，愁陰幸庇身。","卷舒無定日，行止必依人。","已沐脂膏惠，寧辞雨露頻。","雖同客衣色，不染洛陽塵。"]', '诗', 'shi', '', NULL, '詠白油帽送客 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5aa54cc-b4d0-4246-9231-f92ef9ab0402', '藍上採石芥寄前李明府', '藍上採石芥寄前李明府', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["淵明遺愛處，山芥綠芳初。","翫此春陰色，猶滋夜雨餘。","隔溪煙葉小，覆石雪花舒。","采采還相贈，瑤華信不如。"]', '["淵明遺愛处，山芥綠芳初。","翫此春陰色，猶滋夜雨餘。","隔溪煙葉小，覆石雪花舒。","采采還相贈，瑤华信不如。"]', '诗', 'shi', '', NULL, '藍上採石芥寄前李明府 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dc69405-d3a4-49dd-80e6-1c5e4b43efc5', '送贇法師往上都', '送贇法師往上都', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["遠近化人天，王城指日邊。","宰君迎說法，童子伴隨緣。","到處花爲雨，行時杖出泉。","今霄松月下，門閉想安禪。"]', '["远近化人天，王城指日邊。","宰君迎说法，童子伴隨緣。","到处花爲雨，行时杖出泉。","今霄松月下，门閉想安禪。"]', '诗', 'shi', '', NULL, '送贇法師往上都 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db418a55-123e-4532-8e52-3ba2e870cee3', '送沈少府還江寧', '送沈少府還江寧', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["遠宦碧雲外，此行佳興牽。","湖山入閭井，鷗鳥傍神仙。","斜日背鄉樹，春潮迎客船。","江樓新詠發，應與政聲傳。"]', '["远宦碧云外，此行佳兴牽。","湖山入閭井，鷗鸟傍神仙。","斜日背乡樹，春潮迎客船。","江楼新詠發，應與政声傳。"]', '诗', 'shi', '', NULL, '送沈少府還江寧 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ff3b2e1-ed3d-4593-8f48-3a9cf9847db9', '送虞說擢第東遊', '送虞说擢第东游', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["湖山不可厭，東望有餘情。","片玉登科後，孤舟任興行。","月中嚴子瀨，花際楚王城。","歲暮雲臯鶴，聞天更一鳴。"]', '["湖山不可厭，东望有餘情。","片玉登科後，孤舟任兴行。","月中嚴子瀨，花際楚王城。","歲暮云臯鹤，闻天更一鳴。"]', '诗', 'shi', '', NULL, '送虞說擢第東遊 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ff36d5d-66cc-48ce-9c48-924ef008666f', '送少微師西行', '送少微師西行', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["隨緣忽西去，何日返東林。","世路寧磋別，空門久息心。","人煙一飯少，山雪獨行深。","天外猨啼處，誰聞清梵音。"]', '["隨緣忽西去，何日返东林。","世路寧磋別，空门久息心。","人煙一飯少，山雪独行深。","天外猨啼处，誰闻清梵音。"]', '诗', 'shi', '', NULL, '送少微師西行 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81df76ac-bed1-4083-94ee-133c494cbf20', '送崑山孫少府', '送崑山孫少府', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["徇祿近滄海，乘流看碧霄。","誰知仙吏去，宛與世塵遙。","遠帆背歸鳥，孤舟抵上潮。","懸知訟庭靜，窗竹日蕭蕭。"]', '["徇祿近滄海，乘流看碧霄。","誰知仙吏去，宛與世塵遙。","远帆背归鸟，孤舟抵上潮。","懸知訟庭静，窗竹日蕭蕭。"]', '诗', 'shi', '', NULL, '送崑山孫少府 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d34a063-6d37-4826-a56d-27929651e4c6', '送屈突司馬充安西書記', '送屈突司马充安西书記', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["制勝三軍勁，澄清萬里餘。","星飛龐統驥，箭發魯連書。","海月低雲斾，江霞入錦車。","遙知太阿劍，計日斬鯨魚。"]', '["制勝三軍勁，澄清万里餘。","星飞龐統驥，箭發魯連书。","海月低云斾，江霞入錦车。","遙知太阿劍，計日斬鯨鱼。"]', '诗', 'shi', '', NULL, '送屈突司馬充安西書記 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1499f490-bfb2-4440-b758-d76ded7d60d3', '送時暹避難適荆南', '送时暹避难適荆南', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["三歎把離袂，七哀深我情。","雲天愁遠別，豺虎擁前程。","駐馬戀攜手，隔河聞哭聲。","相思昏若夢，淚眼幾時明。"]', '["三歎把離袂，七哀深我情。","云天愁远別，豺虎擁前程。","駐马戀携手，隔河闻哭声。","相思昏若梦，泪眼幾时明。"]', '诗', 'shi', '', NULL, '送時暹避難適荆南 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d113ec8-5790-4724-a680-475c54639a07', '送邊補闕東歸省覲', '送邊補闕东归省覲', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["東去有餘意，春風生賜衣。","鳳凰銜詔下，才子采蘭歸。","斗酒百花裏，情人一笑稀。","別離須計日，相望在彤闈。"]', '["东去有餘意，春风生賜衣。","鳳凰銜詔下，才子采蘭归。","斗酒百花裏，情人一笑稀。","別離須計日，相望在彤闈。"]', '诗', 'shi', '', NULL, '送邊補闕東歸省覲 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7b30c8b-c4b4-497b-9747-341109ffb41c', '送彈琴李長史往洪州', '送彈琴李长史往洪州', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["抱琴爲傲吏，孤棹復南行。","幾度秋江水，皆添白雪聲。","佳期來客夢，幽思緩王程。","佐牧無勞問，心和政自平。"]', '["抱琴爲傲吏，孤棹复南行。","幾度秋江水，皆添白雪声。","佳期来客梦，幽思緩王程。","佐牧無勞问，心和政自平。"]', '诗', 'shi', '', NULL, '送彈琴李長史往洪州 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aede046-f51a-4cfc-8c28-68a202505e94', '送宋徵君讓官還山', '送宋徵君讓官還山', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["至人無滯跡，謁帝復思玄。","魏闕辭花綬，春山有杏田。","紫霞開別酒，黃鶴舞離弦。","今夜思君夢，遙遙入洞天。"]', '["至人無滯跡，謁帝复思玄。","魏闕辞花綬，春山有杏田。","紫霞开別酒，黄鹤舞離弦。","今夜思君梦，遙遙入洞天。"]', '诗', 'shi', '', NULL, '送宋徵君讓官還山 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07439c01-0f4e-4587-b5a3-3a4883367827', '送陳供奉恩勅放歸覲省', '送陳供奉恩勅放归覲省', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["得意今如此，清光不可攀。","臣心堯日下，鄉思楚雲間。","楊柳依歸棹，芙蓉棲舊山。","采蘭兼衣錦，何似買臣還。"]', '["得意今如此，清光不可攀。","臣心堯日下，乡思楚云间。","楊柳依归棹，芙蓉棲旧山。","采蘭兼衣錦，何似買臣還。"]', '诗', 'shi', '', NULL, '送陳供奉恩勅放歸覲省 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21ce82b1-4c6f-4601-8493-bd83b9a3e116', '送外甥范勉赴任常州長史兼覲省', '送外甥范勉赴任常州长史兼覲省', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["憐君展驥去，能解倚門愁。","就養仍榮祿，還鄉即晝遊。","橘花低客舍，蓴菜繞歸舟。","與報垂綸叟，知吾世網留。"]', '["怜君展驥去，能解倚门愁。","就養仍榮祿，還乡即晝游。","橘花低客舍，蓴菜繞归舟。","與報垂綸叟，知吾世網留。"]', '诗', 'shi', '', NULL, '送外甥范勉赴任常州長史兼覲省 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('882e2711-9385-4212-9879-8ca7c429e6c8', '隴右送韋三還京', '隴右送韋三還京', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["春風起東道，握手望京關。","柳色從鄉至，鶯聲送客還。","嘶驂顧近驛，歸路出他山。","舉目情難盡，羈離失志間。"]', '["春风起东道，握手望京关。","柳色從乡至，鶯声送客還。","嘶驂顧近驛，归路出他山。","舉目情难尽，羈離失志间。"]', '诗', 'shi', '', NULL, '隴右送韋三還京 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac3f71b3-42d0-4998-b94b-e52565966adf', '送元評事歸山居', '送元評事归山居', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["憶家望雲路，東去獨依依。","水宿隨漁火，山行到竹扉。","寒花催酒熟，山犬喜人歸。","遙羨書窗下，千峰出翠微。"]', '["憶家望云路，东去独依依。","水宿隨漁火，山行到竹扉。","寒花催酒熟，山犬喜人归。","遙羨书窗下，千峰出翠微。"]', '诗', 'shi', '', NULL, '送元評事歸山居 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33b28be1-bac7-4cb9-9d18-f20cf995eb47', '送武進韋明府', '送武進韋明府', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["理邑想無事，鳴琴不下堂。","井田通楚越，津市半漁商。","盧橘垂殘雨，紅蓮拆早霜。","送君催白首，臨水獨思鄉。"]', '["理邑想無事，鳴琴不下堂。","井田通楚越，津市半漁商。","盧橘垂殘雨，紅蓮拆早霜。","送君催白首，臨水独思乡。"]', '诗', 'shi', '', NULL, '送武進韋明府 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e57b65b7-0644-43db-9cb7-24c1f048abd1', '送上官侍御', '送上官侍御', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["執簡朝方下，乘軺去不賒。","感恩輕遠道，入幕比還家。","碣石春雲色，邯鄲古樹花。","飛書報明主，烽火靜天涯。"]', '["執簡朝方下，乘軺去不賒。","感恩轻远道，入幕比還家。","碣石春云色，邯鄲古樹花。","飞书報明主，烽火静天涯。"]', '诗', 'shi', '', NULL, '送上官侍御 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('697a2b30-e242-4535-a940-f1813ccae9bc', '送郭秀才制舉下第南遊', '送郭秀才制舉下第南游', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["失志思浪跡，知君晦近名。","出關塵漸遠，過郢興彌清。","山盡溪初廣，人閑舟自行。","探幽無旅思，莫畏楚猨鳴。"]', '["失志思浪跡，知君晦近名。","出关塵漸远，過郢兴彌清。","山尽溪初廣，人闲舟自行。","探幽無旅思，莫畏楚猨鳴。"]', '诗', 'shi', '', NULL, '送郭秀才制舉下第南遊 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fa9b03f-f99b-4a0a-9ce6-e690bef3d02c', '送夏侯審校書東歸', '送夏侯審校书东归', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["楚鄉飛鳥沒，獨與碧雲還。","破鏡催歸客，殘陽見舊山。","詩成流水上，夢盡落花間。","儻寄相思字，愁人定解顏。"]', '["楚乡飞鸟沒，独與碧云還。","破镜催归客，殘陽见旧山。","诗成流水上，梦尽落花间。","儻寄相思字，愁人定解顏。"]', '诗', 'shi', '', NULL, '送夏侯審校書東歸 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8903dec-37ab-4e3c-94f6-8028f5560c69', '送衛功曹赴荆南', '送衛功曹赴荆南', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["漢家仍用武，才子晚成名。","惆悵江陵去，誰知魏闕情。","碧雲愁楚水，春酒醉宜城。","定想褰帷政，還聞坐嘯聲。"]', '["漢家仍用武，才子晚成名。","惆悵江陵去，誰知魏闕情。","碧云愁楚水，春酒醉宜城。","定想褰帷政，還闻坐嘯声。"]', '诗', 'shi', '', NULL, '送衛功曹赴荆南 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77a72612-f6ed-4316-9e1a-9580744de2d8', '送馬使君赴鄭州', '送马使君赴鄭州', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["東土忽無事，專城復任賢。","喜觀班瑞禮，還在偃兵年。","膏雨帶滎水，歸人耕圃田。","遙知下車日，萬井起新煙。"]', '["东土忽無事，專城复任賢。","喜观班瑞禮，還在偃兵年。","膏雨带滎水，归人耕圃田。","遙知下车日，万井起新煙。"]', '诗', 'shi', '', NULL, '送馬使君赴鄭州 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e37e031-c670-4905-a417-756155eabbfd', '送郎四補闕東歸', '送郎四補闕东归', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["無事共干世，多時廢隱淪。","相看戀簪組，不覺老風塵。","勸酒憐今別，傷心倍去春。"]', '["無事共干世，多时廢隐淪。","相看戀簪組，不覺老风塵。","勸酒怜今別，傷心倍去春。"]', '诗', 'shi', '', NULL, '送郎四補闕東歸 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61c08a87-013c-433f-9c57-5bfcf8cea376', '送陸三出尉', '送陸三出尉', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["春草晚來色，東門愁送君。","盛才仍下位，明代負奇文。","且樂神仙道，終隨鴛鷺羣。","梅生寄黃綬，不日在青雲。"]', '["春草晚来色，东门愁送君。","盛才仍下位，明代負奇文。","且乐神仙道，終隨鴛鷺羣。","梅生寄黄綬，不日在青云。"]', '诗', 'shi', '', NULL, '送陸三出尉 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58b76ad1-a9b1-4fb5-af59-5fc8cd7e3417', '送安都秀才北還', '送安都秀才北還', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["年少工文客，言離却解顏。","不嗟荆寶退，能喜綵衣還。","新月來前館，高陽出故關。","相思東北望，燕趙隔青山。"]', '["年少工文客，言離却解顏。","不嗟荆寶退，能喜綵衣還。","新月来前館，高陽出故关。","相思东北望，燕趙隔青山。"]', '诗', 'shi', '', NULL, '送安都秀才北還 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2338e8b5-844c-472a-a4e4-2937308e2fa9', '送褚十一澡擢第歸吳覲省', '送褚十一澡擢第归吳覲省', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["林表吳山色，詩人思不忘。","向家流水便，懷橘綵衣香。","滿酌留歸騎，前程未夕陽。","愴茲江海去，誰惜杜蘅芳。"]', '["林表吳山色，诗人思不忘。","向家流水便，懷橘綵衣香。","满酌留归騎，前程未夕陽。","愴茲江海去，誰惜杜蘅芳。"]', '诗', 'shi', '', NULL, '送褚十一澡擢第歸吳覲省 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('921db4f3-4649-4ec8-849c-676d47aecd3c', '送費秀才歸衡州', '送費秀才归衡州', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["南望瀟湘渚，詞人遠憶家。","客心隨楚水，歸棹宿江花。","不畏心期阻，惟愁面會賒。","雲天有飛翼，方寸佇瑤華。"]', '["南望瀟湘渚，词人远憶家。","客心隨楚水，归棹宿江花。","不畏心期阻，惟愁面會賒。","云天有飞翼，方寸佇瑤华。"]', '诗', 'shi', '', NULL, '送費秀才歸衡州 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92bac245-5bd3-48dd-96ed-55580b4daab7', '送陸郎中', '送陸郎中', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["事邊仍戀主，舉酒復悲歌。","粉署含香別，轅門載筆過。","鶯聲出漢苑，柳色過漳河。","相憶情難盡，離居春草多。"]', '["事邊仍戀主，舉酒复悲歌。","粉署含香別，轅门載笔過。","鶯声出漢苑，柳色過漳河。","相憶情难尽，離居春草多。"]', '诗', 'shi', '', NULL, '送陸郎中 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15274300-bd45-4898-ab14-9a3dead4b620', '送僧歸日本', '送僧归日本', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["上國隨緣住，來途若夢行。","浮天滄海遠，去世法舟輕。","水月通禪觀，魚龍聽梵聲。","惟憐一燈影，萬里眼中明。"]', '["上国隨緣住，来途若梦行。","浮天滄海远，去世法舟轻。","水月通禪观，鱼龙听梵声。","惟怜一灯影，万里眼中明。"]', '诗', 'shi', '', NULL, '送僧歸日本 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9615ed8-64d5-4106-b37e-feca45697b6c', '送楊皞擢第遊江南', '送楊皞擢第游江南', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["行人臨水去，新詠復新悲。","萬里高秋月，孤山遠別時。","挂帆嚴子瀨，酹酒敬亭祠。"]', '["行人臨水去，新詠复新悲。","万里高秋月，孤山远別时。","挂帆嚴子瀨，酹酒敬亭祠。"]', '诗', 'shi', '', NULL, '送楊皞擢第遊江南 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5642c138-026d-482f-bef7-c83eff52cf97', '送田倉曹歸覲', '送田倉曹归覲', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["青絲絡驄馬，去府望梁城。","節下趨庭處，秋來懷橘情。","別筵寒日晚，歸路碧雲生。","千里相思夜，愁看新月明。"]', '["青絲絡驄马，去府望梁城。","節下趨庭处，秋来懷橘情。","別筵寒日晚，归路碧云生。","千里相思夜，愁看新月明。"]', '诗', 'shi', '', NULL, '送田倉曹歸覲 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd52cc4e-6e22-4b4c-96a1-0e55a5cf67fe', '送張管書記', '送張管书記', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["邊事多勞役，儒衣逐鼓鼙。","日寒關樹外，峰盡塞雲西。","河廣篷難度，天遙鴈漸低。","班超封定遠，之子去思齊。"]', '["邊事多勞役，儒衣逐鼓鼙。","日寒关樹外，峰尽塞云西。","河廣篷难度，天遙鴈漸低。","班超封定远，之子去思齊。"]', '诗', 'shi', '', NULL, '送張管書記 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64921405-3e4e-4666-8dba-07e13c6b0294', '送蕭常侍北使', '送蕭常侍北使', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["絳節引雕戈，鳴騶動玉珂。","戎城去日遠，漢使隔年多。","鴈宿常連雪，沙飛半渡河。","明光朝即邇，[杕]杜早成歌。"]', '["絳節引雕戈，鳴騶动玉珂。","戎城去日远，漢使隔年多。","鴈宿常連雪，沙飞半渡河。","明光朝即邇，[杕]杜早成歌。"]', '诗', 'shi', '', NULL, '送蕭常侍北使 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da7e5017-c5ed-43a9-9400-e1a77958aa19', '送李棲桐道舉擢第還鄉省侍', '送李棲桐道舉擢第還乡省侍', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["幾年深道要，一舉過賢關。","名與玄珠出，鄉宜晝錦還。","蓮舟同宿浦，柳岸向家山。","欲見寧親孝，儒衣稚子斑。"]', '["幾年深道要，一舉過賢关。","名與玄珠出，乡宜晝錦還。","蓮舟同宿浦，柳岸向家山。","欲见寧親孝，儒衣稚子斑。"]', '诗', 'shi', '', NULL, '送李棲桐道舉擢第還鄉省侍 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab8714f5-9716-490c-ba80-04926c6c4849', '送柳道士', '送柳道士', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["去世能成道，遊仙不定家。","歸期千歲鶴，行邁五雲車。","海上春應盡，壺中日未斜。","不知相憶處，琪樹幾枝花。"]', '["去世能成道，游仙不定家。","归期千歲鹤，行邁五云车。","海上春應尽，壺中日未斜。","不知相憶处，琪樹幾枝花。"]', '诗', 'shi', '', NULL, '送柳道士 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecaec030-04ce-4401-b30a-a9424d79b486', '送陸珽侍御使新羅', '送陸珽侍御使新羅', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["衣冠周柱史，才學我鄉人。","受命辭雲陛，傾城送使臣。","去程滄海月，歸思上林春。","始覺儒風遠，殊方禮樂新。"]', '["衣冠周柱史，才学我乡人。","受命辞云陛，傾城送使臣。","去程滄海月，归思上林春。","始覺儒风远，殊方禮乐新。"]', '诗', 'shi', '', NULL, '送陸珽侍御使新羅 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf5e6e60-ad0d-4fdc-93c3-55ef968b2615', '重送陸侍御使日本', '重送陸侍御使日本', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["萬里三韓國，行人滿目愁。","辭天使星遠，臨水澗霜秋。","雲佩迎仙島，虹旌過蜃樓。","定知懷魏闕，迴首海西頭。"]', '["万里三韓国，行人满目愁。","辞天使星远，臨水澗霜秋。","云佩迎仙島，虹旌過蜃楼。","定知懷魏闕，迴首海西头。"]', '诗', 'shi', '', NULL, '重送陸侍御使日本 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71e47eff-9cd4-4a6a-b186-3af398e97267', '送陸贄擢第還蘇州', '送陸贄擢第還蘇州', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["鄉路歸何早，雲間喜擅名。","思親盧橘熟，帶雨客帆輕。","夜火臨津驛，晨鐘隔浦城。","華亭養仙羽，計日再飛鳴。"]', '["乡路归何早，云间喜擅名。","思親盧橘熟，带雨客帆轻。","夜火臨津驛，晨鐘隔浦城。","华亭養仙羽，計日再飞鳴。"]', '诗', 'shi', '', NULL, '送陸贄擢第還蘇州 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f44a29ef-6aeb-4316-a987-13e730fa54d1', '送虞說擢第南歸覲省', '送虞说擢第南归覲省', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["南風起別袂，心到衡湘間。","歸客楚山遠，孤舟雲水閑。","愛君採蓮處，花島連家山。","得意且寧省，人生難此還。"]', '["南风起別袂，心到衡湘间。","归客楚山远，孤舟云水闲。","愛君採蓮处，花島連家山。","得意且寧省，人生难此還。"]', '诗', 'shi', '', NULL, '送虞說擢第南歸覲省 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('637e0642-9318-471d-b191-f0548b99dfe2', '送原公南遊', '送原公南游', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["有意兼程去，飄然二翼輕。","故鄉多久別，春草不傷情。","洗鉢泉初暖，焚香曉更清。"]', '["有意兼程去，飄然二翼轻。","故乡多久別，春草不傷情。","洗鉢泉初暖，焚香晓更清。"]', '诗', 'shi', '', NULL, '送原公南遊 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45a484be-7542-4810-9abd-3363a55deaf0', '送萬兵曹赴廣陵', '送万兵曹赴廣陵', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["秋日思還客，臨流語別難。","楚城將坐嘯，郢曲有餘悲。","山晚桂花老，江寒蘋葉衰。","應須楊得意，更誦長卿辭。"]', '["秋日思還客，臨流語別难。","楚城將坐嘯，郢曲有餘悲。","山晚桂花老，江寒蘋葉衰。","應須楊得意，更誦长卿辞。"]', '诗', 'shi', '', NULL, '送萬兵曹赴廣陵 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c2c9bd8-aa22-4ad2-b36a-8cd3a74dff86', '送李判官赴桂州幕', '送李判官赴桂州幕', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["欲知儒道貴，縫掖見諸侯。","且感千金諾，寧辭萬里遊。","鴈峰侵瘴遠，桂水出雲流。","坐惜離居晚，相思綠蕙秋。"]', '["欲知儒道貴，縫掖见諸侯。","且感千金諾，寧辞万里游。","鴈峰侵瘴远，桂水出云流。","坐惜離居晚，相思綠蕙秋。"]', '诗', 'shi', '', NULL, '送李判官赴桂州幕 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6f0de4d-03de-41d8-9a8e-362dd1e7adf6', '題蘇公林亭', '題蘇公林亭', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["平津東閣在，別是竹林期。","萬葉秋聲裏，千家落照時。","門隨深巷靜，窗過遠鐘遲。","客位苔生處，依然又賦詩。"]', '["平津东閣在，別是竹林期。","万葉秋声裏，千家落照时。","门隨深巷静，窗過远鐘遲。","客位苔生处，依然又賦诗。"]', '诗', 'shi', '', NULL, '題蘇公林亭 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad02adcf-723b-444d-94eb-ad88a922cb82', '賦得寒雲輕重色送子恂入京', '賦得寒云轻重色送子恂入京', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["無限寒雲色，蒼茫淺更深。","從龍如有瑞，捧日不成陰。","積翠全低嶺，虛明半出林。","帝鄉遙在目，鐵馬又駸駸。"]', '["無限寒云色，蒼茫淺更深。","從龙如有瑞，捧日不成陰。","積翠全低嶺，虛明半出林。","帝乡遙在目，鐵马又駸駸。"]', '诗', 'shi', '', NULL, '賦得寒雲輕重色送子恂入京 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7a8cf84-8ca8-4c19-848d-2c0a85e9979d', '賦得叢蘭曙後色送梁侍御人京', '賦得叢蘭曙後色送梁侍御人京', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["曙色傳芳意，分明錦繡叢。","蘭生齊後日，花發夜來風。","不向三峰裏，全勝一縣中。","遙知大苑內，應待五花驄。"]', '["曙色傳芳意，分明錦繡叢。","蘭生齊後日，花發夜来风。","不向三峰裏，全勝一縣中。","遙知大苑內，應待五花驄。"]', '诗', 'shi', '', NULL, '賦得叢蘭曙後色送梁侍御人京 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38e89878-ecf2-487f-9e70-ce7eec141b1c', '賦得餘冰', '賦得餘冰', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["曉日餘冰上，春池一鏡明。","多從履處薄，偏向飲時清。","比雪光仍在，因風片不成。","更隨舟楫去，猶可助堅貞。"]', '["晓日餘冰上，春池一镜明。","多從履处薄，偏向饮时清。","比雪光仍在，因风片不成。","更隨舟楫去，猶可助堅貞。"]', '诗', 'shi', '', NULL, '賦得餘冰 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a72f6dee-8210-4c3e-b57a-11c96b4ba978', '賦得浦口望斜月送皇甫判官', '賦得浦口望斜月送皇甫判官', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["起見西樓月，依依向浦斜。","動搖生淺浪，明滅照寒沙。","水渚猶疑雪，梅林不辨花。","送君無可贈，持此代瑤華。"]', '["起见西楼月，依依向浦斜。","动搖生淺浪，明滅照寒沙。","水渚猶疑雪，梅林不辨花。","送君無可贈，持此代瑤华。"]', '诗', 'shi', '', NULL, '賦得浦口望斜月送皇甫判官 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0af63d3-04d0-4f96-a760-fdf7ea775311', '賦得綿綿思遠道送岑判官入嶺', '賦得綿綿思远道送岑判官入嶺', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["極目煙霞外，孤舟一使星。","興中尋白雪，夢裏過滄溟。","夜月松江戍，秋風竹塢亭。","不知行遠近，芳草日青青。"]', '["極目煙霞外，孤舟一使星。","兴中尋白雪，梦裏過滄溟。","夜月松江戍，秋风竹塢亭。","不知行远近，芳草日青青。"]', '诗', 'shi', '', NULL, '賦得綿綿思遠道送岑判官入嶺 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4adde461-704c-44bf-a173-f9d16560efcb', '江寧春夜裴使君席送蕭員外', '江寧春夜裴使君席送蕭員外', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["花院日扶疎，江雲自卷舒。","主人熊軾任，歸客稚門車。","曙月稀星裏，春煙紫禁餘。","行看石頭戍，記得是南徐。"]', '["花院日扶疎，江云自卷舒。","主人熊軾任，归客稚门车。","曙月稀星裏，春煙紫禁餘。","行看石头戍，記得是南徐。"]', '诗', 'shi', '', NULL, '江寧春夜裴使君席送蕭員外 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6835ebd2-0605-408a-b22f-cc4bdd01f5cc', '送薛八謫居', '送薛八謫居', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["東水將孤客，南行路幾千。","虹翻潮上雨，鳥落瘴中天。","謫去寧留恨，思歸豈待年。","銜杯且一醉，別淚莫潸然。"]', '["东水將孤客，南行路幾千。","虹翻潮上雨，鸟落瘴中天。","謫去寧留恨，思归豈待年。","銜杯且一醉，別泪莫潸然。"]', '诗', 'shi', '', NULL, '送薛八謫居 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65a66bc7-8f3c-4181-8a52-c3f36f44593f', '送衡陽歸客', '送衡陽归客', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["歸客愛鳴榔，南征憶舊鄉。","江山追宋玉，雲雨憶荆王。","醉裏宜城近，歌中郢路長。","憐君從此去，日夕望三湘。"]', '["归客愛鳴榔，南征憶旧乡。","江山追宋玉，云雨憶荆王。","醉裏宜城近，歌中郢路长。","怜君從此去，日夕望三湘。"]', '诗', 'shi', '', NULL, '送衡陽歸客 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e6d149a-cb0c-4d0a-98cb-7a9807f5bc80', '送員外侍御入朝', '送員外侍御入朝', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["別思亂無緒，妖氛猶未清。","含香五夜客，持賦十年兄。","霜拂金波樹，星迴玉斗城。","自憐江上鶴，垂翅羨飛鳴。"]', '["別思亂無緒，妖氛猶未清。","含香五夜客，持賦十年兄。","霜拂金波樹，星迴玉斗城。","自怜江上鹤，垂翅羨飞鳴。"]', '诗', 'shi', '', NULL, '送員外侍御入朝 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a122b31d-4d92-4ea9-b5b9-26aacfabfba5', '送李諫議歸荆州', '送李諫議归荆州', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["歸舟同不繫，纖草剩忘憂。","禁掖曾通籍，江城舊列侯。","暮帆依夏口，春雨夢荆州。","何日朝雲陛，隨君拜冕旒。"]', '["归舟同不繫，纖草剩忘憂。","禁掖曾通籍，江城旧列侯。","暮帆依夏口，春雨梦荆州。","何日朝云陛，隨君拜冕旒。"]', '诗', 'shi', '', NULL, '送李諫議歸荆州 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('158c3e3b-5f59-4b94-84c4-7353d437ac56', '送元中丞江淮轉運', '送元中丞江淮轉運', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["薄稅歸天府，輕徭賴使臣。","歡霑賜帛老，恩及卷綃人。","去問殊官俗，來經幾劫春。","東南御亭上，莫問有風塵。"]', '["薄稅归天府，轻徭賴使臣。","歡霑賜帛老，恩及卷綃人。","去问殊官俗，来經幾劫春。","东南御亭上，莫问有风塵。"]', '诗', 'shi', '', NULL, '送元中丞江淮轉運 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f3f4eee-eb4c-46a6-8104-3e79b82760e2', '送唐別駕赴郢州', '送唐別駕赴郢州', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["少年從事好，此去別愁輕。","滿座詩人興，隨君郢路行。","蒹葭侵驛樹，雲水抱山城。","遙愛下車日，江臯春草生。"]', '["少年從事好，此去別愁轻。","满座诗人兴，隨君郢路行。","蒹葭侵驛樹，云水抱山城。","遙愛下车日，江臯春草生。"]', '诗', 'shi', '', NULL, '送唐別駕赴郢州 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5610b026-455e-4bcb-871f-2fcfb028aacb', '送鄭巨及第後歸覲', '送鄭巨及第後归覲', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["多才白華子，初擅桂枝名。","嘉慶送歸客，新秋帶雨行。","離人背水去，喜鵲近家迎。","別贈難爲此，衰年畏後生。"]', '["多才白华子，初擅桂枝名。","嘉慶送归客，新秋带雨行。","離人背水去，喜鵲近家迎。","別贈难爲此，衰年畏後生。"]', '诗', 'shi', '', NULL, '送鄭巨及第後歸覲 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8fd3313-7058-4b9d-9564-7cd94a77a05f', '宿遠上人蘭若', '宿远上人蘭若', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["香花閉一林，真士此看心。","行道白雲近，然燈翠壁深。","梵筵清水月，禪坐冷山陰。","更說東溪好，明朝乘興尋。"]', '["香花閉一林，真士此看心。","行道白云近，然灯翠壁深。","梵筵清水月，禪坐冷山陰。","更说东溪好，明朝乘兴尋。"]', '诗', 'shi', '', NULL, '宿遠上人蘭若 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebd8f4d7-775c-49d4-999e-ca5300464d28', '酬元祕書晚出藍溪見寄', '酬元祕书晚出藍溪见寄', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["野興引才子，獨行幽徑遲。","雲留下山處，鳥靜出溪時。","拙宦不忘隱，歸休常在茲。","知音倘相訪，炊黍掃茅茨。"]', '["野兴引才子，独行幽徑遲。","云留下山处，鸟静出溪时。","拙宦不忘隐，归休常在茲。","知音倘相訪，炊黍掃茅茨。"]', '诗', 'shi', '', NULL, '酬元祕書晚出藍溪見寄 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e74768e-6bef-49ce-b838-bdb3bd30ea98', '別張起居', '別張起居', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["有別時留恨，銷魂況在今。","風濤初振海，鵷鷺各辭林。","舊國關河絕，新秋草露深。","陸機嬰世網，應負故山心。"]', '["有別时留恨，銷魂況在今。","风濤初振海，鵷鷺各辞林。","旧国关河絕，新秋草露深。","陸機嬰世網，應負故山心。"]', '诗', 'shi', '', NULL, '別張起居 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3425dd3-21da-490e-97fd-10172f811ebc', '郭司徒廳夜宴', '郭司徒廳夜宴', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["秋堂復夜闌，舉目盡悲端。","霜堞鳥聲苦，更樓月色寒。","美人深別意，斗酒少留歡。","明發將何贈，平生雙玉盤。"]', '["秋堂复夜闌，舉目尽悲端。","霜堞鸟声苦，更楼月色寒。","美人深別意，斗酒少留歡。","明發將何贈，平生雙玉盤。"]', '诗', 'shi', '', NULL, '郭司徒廳夜宴 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6d723fc-04be-4802-9241-01541140c5e9', '初至京口示諸弟', '初至京口示諸弟', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["還家百戰後，訪故幾人存。","兄弟得相見，榮枯何處論。","新詩添卷軸，舊業見兒孫。","點檢平生事，焉能出蓽門。"]', '["還家百戰後，訪故幾人存。","兄弟得相见，榮枯何处論。","新诗添卷軸，旧業见兒孫。","点檢平生事，焉能出蓽门。"]', '诗', 'shi', '', NULL, '初至京口示諸弟 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8f42b5f-825f-40f6-bc7b-9987a77f9f26', '月下洗藥', '月下洗藥', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["汲井向新月，分流入衆芳。","溼花低桂影，翻葉靜泉光。","露下添餘潤，蜂驚引暗香。","寄言養生客，來此共提筐。"]', '["汲井向新月，分流入衆芳。","溼花低桂影，翻葉静泉光。","露下添餘潤，蜂驚引暗香。","寄言養生客，来此共提筐。"]', '诗', 'shi', '', NULL, '月下洗藥 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5f4c0a5-e669-4943-85bd-6b9c2f15d98d', '晚春永寧墅小園獨坐寄上王相公', '晚春永寧墅小园独坐寄上王相公', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["東閣一何靜，鶯聲落日愁。","夔龍暫爲別，昏旦思兼秋。","蕙草出籬外，花枝寄竹幽。","上方傳雅頌，七夕讓風流。"]', '["东閣一何静，鶯声落日愁。","夔龙暫爲別，昏旦思兼秋。","蕙草出籬外，花枝寄竹幽。","上方傳雅頌，七夕讓风流。"]', '诗', 'shi', '', NULL, '晚春永寧墅小園獨坐寄上王相公 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e15628e8-7fe3-49d3-a007-16563c6ea5ce', '歲暇題茅茨', '歲暇題茅茨', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["谷口逃名客，歸來遂野心。","薄田供歲酒，喬木待新禽。","溪路春雲重，山廚夜火深。","桃源應漸好，仙客許相尋。"]', '["谷口逃名客，归来遂野心。","薄田供歲酒，喬木待新禽。","溪路春云重，山廚夜火深。","桃源應漸好，仙客許相尋。"]', '诗', 'shi', '', NULL, '歲暇題茅茨 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5f3ef7b-7f39-432f-89c0-21796198025c', '九日登玉山', '九日登玉山', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["霞景青山上，誰知此勝遊。","龍沙傳往事，菊酒對今秋。","步石隨雲起，題詩向水流。","忘歸更有處，松下片雲幽。"]', '["霞景青山上，誰知此勝游。","龙沙傳往事，菊酒对今秋。","步石隨云起，題诗向水流。","忘归更有处，松下片云幽。"]', '诗', 'shi', '', NULL, '九日登玉山 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33995463-1861-4c9f-a172-99cefa8b94f8', '宴崔駙馬玉山別業', '宴崔駙马玉山別業', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["金榜開青瑣，驕奢半隱淪。","玉簫惟送酒，羅袖愛留賓。","竹館煙催瞑，梅園雪誤春。","滿朝辭賦客，盡是入林人。"]', '["金榜开青瑣，驕奢半隐淪。","玉簫惟送酒，羅袖愛留賓。","竹館煙催瞑，梅园雪誤春。","满朝辞賦客，尽是入林人。"]', '诗', 'shi', '', NULL, '宴崔駙馬玉山別業 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88ad8702-4be6-43e9-af9b-ba168afc50bb', '春谷幽居', '春谷幽居', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["黃鳥鳴園柳，新陽改舊陰。","春來此幽興，宛是謝公心。","掃逕蘭芽出，添池山影深。","虛名隨振鷺，安得久棲林。"]', '["黄鸟鳴园柳，新陽改旧陰。","春来此幽兴，宛是謝公心。","掃逕蘭芽出，添池山影深。","虛名隨振鷺，安得久棲林。"]', '诗', 'shi', '', NULL, '春谷幽居 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('189b5ead-688e-46b3-8d16-699ef1f70b05', '賦得池上雙丁香樹', '賦得池上雙丁香樹', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["得地移根遠，交柯遶指柔。","露香濃結桂，池影鬬蟠虬。","黛葉輕筠綠，金花笑菊秋。","何如南海外，雨露隔炎洲。"]', '["得地移根远，交柯遶指柔。","露香濃結桂，池影鬬蟠虬。","黛葉轻筠綠，金花笑菊秋。","何如南海外，雨露隔炎洲。"]', '诗', 'shi', '', NULL, '賦得池上雙丁香樹 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15d66eb1-8986-4601-b6fa-44de684fc5ea', '題樊川杜相公別業', '題樊川杜相公別業', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["數畝園林好，人知賢相家。","結茅書閣儉，帶水槿籬斜。","古樹生春蘚，新荷卷落花。","聖恩加玉鉉，安得臥青霞。"]', '["數畝园林好，人知賢相家。","結茅书閣儉，带水槿籬斜。","古樹生春蘚，新荷卷落花。","聖恩加玉鉉，安得臥青霞。"]', '诗', 'shi', '', NULL, '題樊川杜相公別業 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28e1d8fc-0aac-4a3b-91c0-1064e8d13c06', '酬盧十一過宿', '酬盧十一過宿', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["乞還方未遂，日夕望雲林。","況復逢青草，何妨問此心。","閉門公務散，枉策故情深。","遙夜他鄉宿，同君梁甫吟。"]', '["乞還方未遂，日夕望云林。","況复逢青草，何妨问此心。","閉门公務散，枉策故情深。","遙夜他乡宿，同君梁甫吟。"]', '诗', 'shi', '', NULL, '酬盧十一過宿 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ec80e34-9397-4132-9568-b1d1c9f5f295', '崔十四宅問候', '崔十四宅问候', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["曉日早鶯啼，江城旅思迷。","微官同寄傲，移疾阻招攜。","遠水閭閻內，青山稚堞西。","王孫莫久臥，春草欲萋萋。"]', '["晓日早鶯啼，江城旅思迷。","微官同寄傲，移疾阻招携。","远水閭閻內，青山稚堞西。","王孫莫久臥，春草欲萋萋。"]', '诗', 'shi', '', NULL, '崔十四宅問候 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a853ea87-07a2-401d-85ab-ff6ad9767bdc', '山路見梅感而有作', '山路见梅感而有作', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["莫言山路僻，還被好風催。","行客淒涼過，村籬冷落開。","晚溪寒水照，晴日數蜂來。","重憶江南酒，何因把一杯。"]', '["莫言山路僻，還被好风催。","行客淒涼過，村籬冷落开。","晚溪寒水照，晴日數蜂来。","重憶江南酒，何因把一杯。"]', '诗', 'shi', '', NULL, '山路見梅感而有作 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92d5420b-996a-47cc-a58a-7c23cc5ba0d1', '詠門上畫松上元王杜三相公', '詠门上畫松上元王杜三相公', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["昔聞生澗底，今見起毫端。","衆草此時沒，何人知歲寒。","豈能裨棟宇，且欲出門闌。","只在丹青筆，凌雲也不難。"]', '["昔闻生澗底，今见起毫端。","衆草此时沒，何人知歲寒。","豈能裨棟宇，且欲出门闌。","只在丹青笔，凌云也不难。"]', '诗', 'shi', '', NULL, '詠門上畫松上元王杜三相公 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('366418c8-3215-4ab6-9d95-3fea73f419ef', '早發東陽', '早發东陽', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["信風催過客，早發梅花橋。","數鴈起前渚，千艘爭便潮。","將隨浮雲去，日惜故山遙。","惆悵煙波末，佳期在碧霄。"]', '["信风催過客，早發梅花橋。","數鴈起前渚，千艘爭便潮。","將隨浮云去，日惜故山遙。","惆悵煙波末，佳期在碧霄。"]', '诗', 'shi', '', NULL, '早發東陽 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e9f77a6-9622-49f9-a00e-a41ccd302cb2', '舟中寄李起居', '舟中寄李起居', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["南行風景好，昏旦水臯閑。","春色郢中樹，晴霞湖上山。","去家旅帆遠，回首暮潮還。","蕙草知何贈，故人雲漢間。"]', '["南行风景好，昏旦水臯闲。","春色郢中樹，晴霞湖上山。","去家旅帆远，回首暮潮還。","蕙草知何贈，故人云漢间。"]', '诗', 'shi', '', NULL, '舟中寄李起居 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('927c9bec-9136-454d-b94a-8270b58d1a42', '夜雨寄寇校書', '夜雨寄寇校书', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["秋館煙雨合，重城鐘漏深。","佳期阻清夜，孤興發離心。","燭影出綃幕，蟲聲連素琴。","此時蓬閣友，應念昔同衾。"]', '["秋館煙雨合，重城鐘漏深。","佳期阻清夜，孤兴發離心。","燭影出綃幕，蟲声連素琴。","此时蓬閣友，應念昔同衾。"]', '诗', 'shi', '', NULL, '夜雨寄寇校書 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f38327e-33d4-4a5f-9311-7a29de57ddc3', '喜李侍御拜郎官入省', '喜李侍御拜郎官入省', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["粉署花驄入，丹霄紫誥垂。","直廬驚漏近，賜被覺霜移。","漢主前瑤席，穰侯許鳳池。","應憐後行鴈，空羨上林枝。"]', '["粉署花驄入，丹霄紫誥垂。","直廬驚漏近，賜被覺霜移。","漢主前瑤席，穰侯許鳳池。","應怜後行鴈，空羨上林枝。"]', '诗', 'shi', '', NULL, '喜李侍御拜郎官入省 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2a53e73-debe-4b43-a3b8-fb9d157aaec6', '蘇端林亭對酒喜雨', '蘇端林亭对酒喜雨', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["小雨飛林頂，浮涼入晚多。","能知留客處，偏與好風過。","濯錦飜紅蕊，跳珠亂碧荷。","芳尊深幾許，此興可酣歌。"]', '["小雨飞林頂，浮涼入晚多。","能知留客处，偏與好风過。","濯錦飜紅蕊，跳珠亂碧荷。","芳尊深幾許，此兴可酣歌。"]', '诗', 'shi', '', NULL, '蘇端林亭對酒喜雨 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5082a98-967f-45dd-aa62-6a0217f71d65', '見上林春鴈翔青雲寄楊起居李員外', '见上林春鴈翔青云寄楊起居李員外', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["上林春更好，賓鴈不知歸。","顧影憐青籞，傳聲入紫微。","夜陪池鷺宿，朝出苑花飛。","寧憶寒鄉侶，鸞凰一見稀。"]', '["上林春更好，賓鴈不知归。","顧影怜青籞，傳声入紫微。","夜陪池鷺宿，朝出苑花飞。","寧憶寒乡侶，鸾凰一见稀。"]', '诗', 'shi', '', NULL, '見上林春鴈翔青雲寄楊起居李員外 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30ba5613-6830-4f6b-b6dd-d2bb46e7dfdd', '偶成', '偶成', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["含毫意不淺，微月上簾櫳。","門靜吏人息，心閑囹圄空。","繁星入疎樹，驚鵲倦秋風。","始覺牽卑劇，宵眠亦在公。"]', '["含毫意不淺，微月上簾櫳。","门静吏人息，心闲囹圄空。","繁星入疎樹，驚鵲倦秋风。","始覺牽卑劇，宵眠亦在公。"]', '诗', 'shi', '', NULL, '偶成 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('642cb2fc-86b1-47be-9d21-17a21e956df4', '漁潭值雨', '漁潭值雨', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["日入林島異，鶴鳴風草間。","孤帆泊枉渚，飛雨來前山。","客意念留滯，川途忽阻艱。","赤亭仍數里，夜待安流還。"]', '["日入林島異，鹤鳴风草间。","孤帆泊枉渚，飞雨来前山。","客意念留滯，川途忽阻艱。","赤亭仍數里，夜待安流還。"]', '诗', 'shi', '', NULL, '漁潭值雨 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7db02472-06a9-4006-8618-7fc64e6da99b', '題蕭丞小池', '題蕭丞小池', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["鶯鳴蕙草綠，朝興情人期。","林沼忘言處，鴛鴻養翮時。","春泉滋藥暖，晴日度花遲。","此會無辭醉，良辰難再追。"]', '["鶯鳴蕙草綠，朝兴情人期。","林沼忘言处，鴛鴻養翮时。","春泉滋藥暖，晴日度花遲。","此會無辞醉，良辰难再追。"]', '诗', 'shi', '', NULL, '題蕭丞小池 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e3b6637-7090-4b8f-bbd3-54b114e1ddb1', '送集賢崔八叔承恩括圖書', '送集賢崔八叔承恩括圖书', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["雨露滿儒服，天心知子虛。","還勞五經笥，更訪百家書。","贈別傾文苑，光華比使車。","晚雲隨客散，寒樹出關疎。","相見應朝夕，歸期在玉除。"]', '["雨露满儒服，天心知子虛。","還勞五經笥，更訪百家书。","贈別傾文苑，光华比使车。","晚云隨客散，寒樹出关疎。","相见應朝夕，归期在玉除。"]', '诗', 'shi', '', NULL, '送集賢崔八叔承恩括圖書 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2450dd9e-ced8-4ce2-b6f0-3bdc3631ab19', '送張五員外東歸楚州', '送張五員外东归楚州', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["纓佩不爲美，人羣寧免辭。","杳然黃鵠去，未負白雲期。","此別清興盡，高秋臨水時。","好山枉帆僻，浪跡到家遲。","他日詔書下，梁鴻安可追。"]', '["纓佩不爲美，人羣寧免辞。","杳然黄鵠去，未負白云期。","此別清兴尽，高秋臨水时。","好山枉帆僻，浪跡到家遲。","他日詔书下，梁鴻安可追。"]', '诗', 'shi', '', NULL, '送張五員外東歸楚州 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fda79b9-7fe8-4f5a-a38d-1cfa9d7bc5cd', '閑居寄包何', '闲居寄包何', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["去名即棲遁，何必歸滄浪。","種藥幽不淺，杜門喧自忘。","林眠多曉夢，鴉散驚初陽。","片雪幽雲至，迴風鄰果香。","佳期碧天末，惆悵紫蘭芳。"]', '["去名即棲遁，何必归滄浪。","種藥幽不淺，杜门喧自忘。","林眠多晓梦，鴉散驚初陽。","片雪幽云至，迴风鄰果香。","佳期碧天末，惆悵紫蘭芳。"]', '诗', 'shi', '', NULL, '閑居寄包何 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cce789ae-4e39-4b0d-9aba-9424144389ce', '津梁寺尋李侍御', '津梁寺尋李侍御', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["禪林絕過客，柱史正焚香。","馴鴿不猜隼，慈雲能護霜。","驄聲隔暗竹，吏事散空廊。","霄漢期鴛鷺，狐狸避憲章。","遶堦春色至，屈草待君芳。"]', '["禪林絕過客，柱史正焚香。","馴鴿不猜隼，慈云能護霜。","驄声隔暗竹，吏事散空廊。","霄漢期鴛鷺，狐狸避憲章。","遶堦春色至，屈草待君芳。"]', '诗', 'shi', '', NULL, '津梁寺尋李侍御 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ce3d9b7-7247-4172-a3bb-2abf95e6b64e', '山園秋晚寄杜黃裳少府', '山园秋晚寄杜黄裳少府', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["惆悵佳期阻，園林秋景閑。","終朝碧雲外，唯見暮禽還。","泉石思攜手，煙霞不閉關。","杖藜仍把菊，對卷也看山。","望望離心起，非君誰解顏。"]', '["惆悵佳期阻，园林秋景闲。","終朝碧云外，唯见暮禽還。","泉石思携手，煙霞不閉关。","杖藜仍把菊，对卷也看山。","望望離心起，非君誰解顏。"]', '诗', 'shi', '', NULL, '山園秋晚寄杜黃裳少府 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce62dd6c-a9da-4bb1-a9b2-66824fdcda91', '東溪杜野人致酒', '东溪杜野人致酒', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["萬重雲樹下，數畝子平居。","野院羅泉石，荆扉背里閭。","早冬耕鑿暇，弋雁復烹魚。","靜掃寒花徑，唯邀傲吏車。","晚來留客好，小雪下山初。"]', '["万重云樹下，數畝子平居。","野院羅泉石，荆扉背里閭。","早冬耕鑿暇，弋雁复烹鱼。","静掃寒花徑，唯邀傲吏车。","晚来留客好，小雪下山初。"]', '诗', 'shi', '', NULL, '東溪杜野人致酒 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e5e1e08-1ffb-4923-a607-59470b231998', '憶山中寄舊友', '憶山中寄旧友', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["數歲白雲裏，與君同采薇。","樹深煙不散，溪靜鷺忘飛。","更憶東巖趣，殘陽破翠微。","脫巾花下醉，洗藥月前歸。","風景今還好，如何與世違。"]', '["數歲白云裏，與君同采薇。","樹深煙不散，溪静鷺忘飞。","更憶东巖趣，殘陽破翠微。","脫巾花下醉，洗藥月前归。","风景今還好，如何與世違。"]', '诗', 'shi', '', NULL, '憶山中寄舊友 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4ea0292-30c1-4c35-9c28-e610184254a8', '東臯早春寄郎四校書', '东臯早春寄郎四校书', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["祿微賴學稼，歲起歸衡茅。","窮達戀明主，耕桑亦近郊。","夜來霽山雪，陽氣動林梢。","蘭蕙暖初吐，春鳩鳴欲巢。","蓬萊時入夢，知子憶貧交。"]', '["祿微賴学稼，歲起归衡茅。","窮達戀明主，耕桑亦近郊。","夜来霽山雪，陽氣动林梢。","蘭蕙暖初吐，春鳩鳴欲巢。","蓬萊时入梦，知子憶貧交。"]', '诗', 'shi', '', NULL, '東臯早春寄郎四校書 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3ee3ceb-3231-4131-a343-819ced236a14', '玉山東溪題李叟屋壁', '玉山东溪題李叟屋壁', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["霞景已斜照，煙溪方暝投。","山家歸路僻，轍跡亂泉流。","野老採薇暇，蝸廬招客幽。","麏麚突荒院，鸕鵲步閑疇。","偶此愜真性，令人輕宦遊。"]', '["霞景已斜照，煙溪方暝投。","山家归路僻，轍跡亂泉流。","野老採薇暇，蝸廬招客幽。","麏麚突荒院，鸕鵲步闲疇。","偶此愜真性，令人轻宦游。"]', '诗', 'shi', '', NULL, '玉山東溪題李叟屋壁 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54257db5-62c2-41db-8544-fb50aec77eec', '溫泉宮禮見', '溫泉宮禮见', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["新豐佳氣滿，聖主在溫泉。","雲曖龍行處，山明日馭前。","順風求至道，側席問遺賢。","靈雪瑤墀降，晨霞綵仗懸。","滄溟不讓水，疵賤也朝天。"]', '["新豐佳氣满，聖主在溫泉。","云曖龙行处，山明日馭前。","順风求至道，側席问遺賢。","靈雪瑤墀降，晨霞綵仗懸。","滄溟不讓水，疵賤也朝天。"]', '诗', 'shi', '', NULL, '溫泉宮禮見 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c2c401b-c1cc-4f1d-8340-516a94623607', '遊襄陽泉石晚歸', '游襄陽泉石晚归', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["遊目隨山勝，迴橈愛浦長。","往來幽不淺，昏旦興難忘。","木末看歸翼，蓮西失夕陽。","人聲指閭井，野趣惜林塘。","稍近垂楊路，菱舟擁岸香。"]', '["游目隨山勝，迴橈愛浦长。","往来幽不淺，昏旦兴难忘。","木末看归翼，蓮西失夕陽。","人声指閭井，野趣惜林塘。","稍近垂楊路，菱舟擁岸香。"]', '诗', 'shi', '', NULL, '遊襄陽泉石晚歸 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ba9c076-eec4-4a12-9c78-b4379864e15f', '夏日陪史郎中宴杜郎中果園', '夏日陪史郎中宴杜郎中果园', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["何事重逢迎，春醪晚更清。","林端花自老，池上月初明。","路入仙郎次，烏連柱史名。","竹陰疎柰院，山翠傍蕪城。","引滿不辭醉，風來待曙更。"]', '["何事重逢迎，春醪晚更清。","林端花自老，池上月初明。","路入仙郎次，烏連柱史名。","竹陰疎柰院，山翠傍蕪城。","引满不辞醉，风来待曙更。"]', '诗', 'shi', '', NULL, '夏日陪史郎中宴杜郎中果園 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8558df16-4368-4416-9be3-fcc3350284f6', '南溪春耕', '南溪春耕', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["荷蓑趣南逕，戴勝鳴條枚。","溪雨有餘潤，土膏寧厭開。","溝塍落花盡，耒耜度雲迴。","誰道耦耕倦，仍兼勝賞催。","日長農有暇，悔不帶經來。"]', '["荷蓑趣南逕，戴勝鳴條枚。","溪雨有餘潤，土膏寧厭开。","溝塍落花尽，耒耜度云迴。","誰道耦耕倦，仍兼勝賞催。","日长農有暇，悔不带經来。"]', '诗', 'shi', '', NULL, '南溪春耕 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2dbfc77-725a-4aac-af95-f54e8e73d2e3', '省試湘靈鼓瑟', '省試湘靈鼓瑟', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["善鼓雲和瑟，常聞帝子靈。","馮夷空自舞，楚客不堪聽。","苦調淒金石，清音入杳冥。","蒼梧來怨慕，白芷動芳馨。","流水傳瀟浦，悲風過洞庭。","曲終人不見，江上數峰青。"]', '["善鼓云和瑟，常闻帝子靈。","馮夷空自舞，楚客不堪听。","苦調淒金石，清音入杳冥。","蒼梧来怨慕，白芷动芳馨。","流水傳瀟浦，悲风過洞庭。","曲終人不见，江上數峰青。"]', '诗', 'shi', '', NULL, '省試湘靈鼓瑟 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4781b27-2f82-41f7-ac3f-75c0c5e36458', '觀法駕自鳳翔迴', '观法駕自鳳翔迴', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["欃槍一掃滅，閶闔九重開。","海晏鯨鯢盡，天旋日月來。","聖情蘇品物，龍御闢雲雷。","曉漏移仙仗，朝陽出帝臺。","周慚散馬出，禹讓濬川迴。","欲識封人願，南山舉酒杯。"]', '["欃槍一掃滅，閶闔九重开。","海晏鯨鯢尽，天旋日月来。","聖情蘇品物，龙御闢云雷。","晓漏移仙仗，朝陽出帝台。","周慚散马出，禹讓濬川迴。","欲識封人願，南山舉酒杯。"]', '诗', 'shi', '', NULL, '觀法駕自鳳翔迴 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac1f760e-ae13-4cfd-81c8-23078f643e80', '題玉山村叟屋壁', '題玉山村叟屋壁', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["谷口好泉石，居人能陸沈。","牛羊下山小，煙火隔雲深。","一逕入溪色，數家連竹陰。","藏虹辭晚雨，驚隼落殘禽。","涉趣皆流目，將歸羨在林。","却思黃綬事，辜負紫芝心。"]', '["谷口好泉石，居人能陸沈。","牛羊下山小，煙火隔云深。","一逕入溪色，數家連竹陰。","藏虹辞晚雨，驚隼落殘禽。","涉趣皆流目，將归羨在林。","却思黄綬事，辜負紫芝心。"]', '诗', 'shi', '', NULL, '題玉山村叟屋壁 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44f744e6-ab04-4af4-82e9-5a28fe9142a2', '縣中池竹言懷', '縣中池竹言懷', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["官小志已足，時清免負薪。","卑棲且得地，榮耀不關身。","自愛賞心處，叢篁流水濱。","荷香度高枕，山色滿南鄰。","道在即爲樂，機忘寧厭貧。","却愁丹鳳詔，來訪漆園人。"]', '["官小志已足，时清免負薪。","卑棲且得地，榮耀不关身。","自愛賞心处，叢篁流水濱。","荷香度高枕，山色满南鄰。","道在即爲乐，機忘寧厭貧。","却愁丹鳳詔，来訪漆园人。"]', '诗', 'shi', '', NULL, '縣中池竹言懷 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a111b81f-c4b1-4bc9-95fe-f714055f8888', '山園棲隱', '山园棲隐', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["守靜信推分，灌園樂在茲。","且忘堯舜力，寧顧尚書期。","晚景采蘭暇，空林散帙時。","卷荷藏露滴，黃口觸蟲絲。","三徑與囂遠，一瓢常自怡。","情人半雲外，風月詎相思。"]', '["守静信推分，灌园乐在茲。","且忘堯舜力，寧顧尚书期。","晚景采蘭暇，空林散帙时。","卷荷藏露滴，黄口觸蟲絲。","三徑與囂远，一瓢常自怡。","情人半云外，风月詎相思。"]', '诗', 'shi', '', NULL, '山園棲隱 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bca69516-afc2-4fac-8169-22591527282c', '送王諫議任東都居守', '送王諫議任东都居守', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["車徒鳳掖東，去去洛陽宮。","暫以青蒲隔，還看紫禁同。","經過乘雨露，瀟灑出鴛鴻。","官署名臺下，雲山舊苑中。","暮天雙闕靜，秋月九重空。","且喜成周地，詩人播國風。"]', '["车徒鳳掖东，去去洛陽宮。","暫以青蒲隔，還看紫禁同。","經過乘雨露，瀟灑出鴛鴻。","官署名台下，云山旧苑中。","暮天雙闕静，秋月九重空。","且喜成周地，诗人播国风。"]', '诗', 'shi', '', NULL, '送王諫議任東都居守 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbda7bf3-886d-49a8-b855-117d39ac92e2', '送鄭書記', '送鄭书記', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["決勝無遺策，辭天便起纓。","出身唯殉死，報國且能兵。","受命麒膦殿，參謀驃騎營。","短簫催別酒，斜日駐前旌。","義勇千夫敵，風沙萬里行。","幾年丹闕下，侯印錫書生。"]', '["決勝無遺策，辞天便起纓。","出身唯殉死，報国且能兵。","受命麒膦殿，參謀驃騎營。","短簫催別酒，斜日駐前旌。","義勇千夫敵，风沙万里行。","幾年丹闕下，侯印錫书生。"]', '诗', 'shi', '', NULL, '送鄭書記 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49544d4a-9de5-439d-b034-b66dff009d1a', '送族姪赴任', '送族姪赴任', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["林下不成興，仲容微祿牽。","客程千里遠，別念一帆懸。","欲歡卑棲去，其如勝趣偏。","雲山深郡郭，花木淨潮田。","坐嘯帷應下，離居月復圓。","此時知小阮，相憶綠尊前。"]', '["林下不成兴，仲容微祿牽。","客程千里远，別念一帆懸。","欲歡卑棲去，其如勝趣偏。","云山深郡郭，花木淨潮田。","坐嘯帷應下，離居月复圓。","此时知小阮，相憶綠尊前。"]', '诗', 'shi', '', NULL, '送族姪赴任 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e0c11c1-816c-40a7-86bc-41a98d7f3fad', '長安落第作', '长安落第作', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["始願今如此，前途復若何。","無媒獻詞賦，生事日蹉跎。","不遇張華識，空悲甯戚歌。","故山歸夢遠，新歲客愁多。","刷羽思喬木，登龍恨失波。","散才非世用，回音謝雲蘿。"]', '["始願今如此，前途复若何。","無媒獻词賦，生事日蹉跎。","不遇張华識，空悲甯戚歌。","故山归梦远，新歲客愁多。","刷羽思喬木，登龙恨失波。","散才非世用，回音謝云蘿。"]', '诗', 'shi', '', NULL, '長安落第作 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aed12ad5-d797-4487-8f0b-0126d16d8f62', '酬長孫繹藍溪寄杏', '酬长孫繹藍溪寄杏', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["愛君藍水上，種杏近成田。","拂逕清陰合，臨流彩實懸。","清香和宿雨，佳色出晴煙。","懿此傾筐贈，想知懷橘年。","芳馨來滿袖，瓊玖願詶篇。","把玩情何極，雲林若眼前。"]', '["愛君藍水上，種杏近成田。","拂逕清陰合，臨流彩實懸。","清香和宿雨，佳色出晴煙。","懿此傾筐贈，想知懷橘年。","芳馨来满袖，瓊玖願詶篇。","把玩情何極，云林若眼前。"]', '诗', 'shi', '', NULL, '酬長孫繹藍溪寄杏 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('628be1f2-39fd-4c2c-b1e6-07d9a1cf5ba2', '藥堂秋暮', '藥堂秋暮', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["隱來未得道，歲去媿雲松。","茅屋空山暮，荷衣白露濃。","唯憐石苔色，不染世人蹤。","潭靜宜孤鶴，山深絕遠鐘。","有時丹竈上，數點綵霞重。","勉事壺公術，仙期待赤龍。"]', '["隐来未得道，歲去媿云松。","茅屋空山暮，荷衣白露濃。","唯怜石苔色，不染世人蹤。","潭静宜孤鹤，山深絕远鐘。","有时丹竈上，數点綵霞重。","勉事壺公術，仙期待赤龙。"]', '诗', 'shi', '', NULL, '藥堂秋暮 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c56c0d66-ebe7-4504-8808-cdbb935fa756', '哭常徴君', '哭常徴君', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["萬化一朝盡，窮泉悲此君。","如何丹竈術，能誤紫芝焚。","不遂蒼生望，空留封禪文。","遠年隨逝水，真氣盡浮雲。","山閉龍蛇蟄，林寒麋鹿羣。","傷心載酒地，仙菊爲誰薰。"]', '["万化一朝尽，窮泉悲此君。","如何丹竈術，能誤紫芝焚。","不遂蒼生望，空留封禪文。","远年隨逝水，真氣尽浮云。","山閉龙蛇蟄，林寒麋鹿羣。","傷心載酒地，仙菊爲誰薰。"]', '诗', 'shi', '', NULL, '哭常徴君 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8be3de21-22b3-43eb-bd76-e9a343252aa4', '送鮑中丞赴太原軍營', '送鲍中丞赴太原軍營', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["年壯才仍美，時來道易行。","寵兼三獨任，威肅貳師營。","將略過南仲，天心寄北京。","雲旂臨塞色，龍笛出關聲。","漢月隨霜去，邊塵計日清。","漸知王事好，文武用書生。"]', '["年壯才仍美，时来道易行。","寵兼三独任，威肅貳師營。","將略過南仲，天心寄北京。","云旂臨塞色，龙笛出关声。","漢月隨霜去，邊塵計日清。","漸知王事好，文武用书生。"]', '诗', 'shi', '', NULL, '送鮑中丞赴太原軍營 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('287bc2ee-eb64-4d40-9f02-07052ccea9ca', '奉送劉相公江淮催轉運', '奉送劉相公江淮催轉運', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["國用資戎事，臣勞爲主憂。","將徴任土貢，更發濟川舟。","擁傳星還去，過池鳳不留。","唯高飲水節，稍淺別家愁。","落葉淮邊雨，孤山海上秋。","遙知謝公興，微月上江樓。"]', '["国用資戎事，臣勞爲主憂。","將徴任土貢，更發濟川舟。","擁傳星還去，過池鳳不留。","唯高饮水節，稍淺別家愁。","落葉淮邊雨，孤山海上秋。","遙知謝公兴，微月上江楼。"]', '诗', 'shi', '', NULL, '奉送劉相公江淮催轉運 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f1b66c6-16e3-4ae0-9982-31f1edeb14bd', '送李秀才落第遊荆楚', '送李秀才落第游荆楚', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["翠羽雖成夢，遷鶯尚後羣。","名逃郄詵策，興發謝玄文。","昏旦扁舟去，江山幾路分。","上潮吞海日，歸雁出湖雲。","詩思應須苦，猨聲莫厭聞。","離居見新月，那得不思君。"]', '["翠羽雖成梦，遷鶯尚後羣。","名逃郄詵策，兴發謝玄文。","昏旦扁舟去，江山幾路分。","上潮吞海日，归雁出湖云。","诗思應須苦，猨声莫厭闻。","離居见新月，那得不思君。"]', '诗', 'shi', '', NULL, '送李秀才落第遊荆楚 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cc95944-7f7d-494e-b1d4-38f59aff1696', '奉陪郭常侍宴滻川山池', '奉陪郭常侍宴滻川山池', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["掖垣攜愛客，勝地賞年光。","向竹過賓館，尋山到妓堂。","歌聲掩金谷，舞態出平陽。","地滿簪裾影，花添蘭麝香。","鶯啼春未老，酒冷日猶長。","安石風流事，須歸問省郎。"]', '["掖垣携愛客，勝地賞年光。","向竹過賓館，尋山到妓堂。","歌声掩金谷，舞態出平陽。","地满簪裾影，花添蘭麝香。","鶯啼春未老，酒冷日猶长。","安石风流事，須归问省郎。"]', '诗', 'shi', '', NULL, '奉陪郭常侍宴滻川山池 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a42f270e-43f2-4a27-a30d-d9c662e0ca17', '寇中送張司馬歸洛', '寇中送張司马归洛', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["戎狄寇周日，衣冠適洛年。","客亭新驛騎，歸路舊人煙。","吾道將東矣，秋風更颯然。","雲愁百戰地，樹隔兩鄉天。","旅思蓬飄陌，驚魂雁怯弦。","今朝一尊酒，莫惜醉離筵。"]', '["戎狄寇周日，衣冠適洛年。","客亭新驛騎，归路旧人煙。","吾道將东矣，秋风更颯然。","云愁百戰地，樹隔兩乡天。","旅思蓬飄陌，驚魂雁怯弦。","今朝一尊酒，莫惜醉離筵。"]', '诗', 'shi', '', NULL, '寇中送張司馬歸洛 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de6284ed-d6da-4b87-a501-c4f7ae4e7066', '奉和宣城張太守南亭秋夕懷友', '奉和宣城張太守南亭秋夕懷友', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["池館蟪蛄聲，梧桐秋露晴。","月臨朱戟靜，河近畫樓明。","捲幔浮涼入，聞鐘永夜清。","片雲懸曙斗，數雁過秋城。","羽扇揚風暇，瑤琴悵別情。","江山飛麗藻，謝朓讓前名。"]', '["池館蟪蛄声，梧桐秋露晴。","月臨朱戟静，河近畫楼明。","捲幔浮涼入，闻鐘永夜清。","片云懸曙斗，數雁過秋城。","羽扇揚风暇，瑤琴悵別情。","江山飞丽藻，謝朓讓前名。"]', '诗', 'shi', '', NULL, '奉和宣城張太守南亭秋夕懷友 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8728fa66-2c0e-479f-b876-258a492939e9', '過山人所居因寄諸遺補', '過山人所居因寄諸遺補', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["空谷春雲滿，愚公晦跡深。","一隨玄豹隱，幾換綠蘿陰。","絕徑人稀道，芳蓀我獨尋。","廚煙住峭壁，酒氣出重林。","蝴蝶晴還舞，黃鸝晚暫吟。","所思青瑣客，瑤草寄幽心。"]', '["空谷春云满，愚公晦跡深。","一隨玄豹隐，幾換綠蘿陰。","絕徑人稀道，芳蓀我独尋。","廚煙住峭壁，酒氣出重林。","蝴蝶晴還舞，黄鸝晚暫吟。","所思青瑣客，瑤草寄幽心。"]', '诗', 'shi', '', NULL, '過山人所居因寄諸遺補 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95016fcd-87f8-4828-9d26-b9a2b43c5a89', '過鳴臯隱者', '過鳴臯隐者', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["磻石老紅鮮，徴君臥幾年。","飛泉出林下，一徑過崖巔。","雞犬逐人靜，雲霞宜地偏。","終朝數峰勝，不遠一壺前。","仲月霽春雨，香風生藥田。","丹溪不可別，瓊草色芊芊。"]', '["磻石老紅鲜，徴君臥幾年。","飞泉出林下，一徑過崖巔。","雞犬逐人静，云霞宜地偏。","終朝數峰勝，不远一壺前。","仲月霽春雨，香风生藥田。","丹溪不可別，瓊草色芊芊。"]', '诗', 'shi', '', NULL, '過鳴臯隱者 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('377877bd-d58d-4ffc-b26f-de48862aeb00', '送楊錥歸隱', '送楊錥归隐', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["悔作掃門事，還吟招隱詩。","今年芳草色，不失故山期。","遙想白雲裏，采苓春日遲。","溪花藏石徑，巖翠帶茅茨。","九轉莫飛去，三迴良在茲。","還嗤茂陵客，貧病老明時。"]', '["悔作掃门事，還吟招隐诗。","今年芳草色，不失故山期。","遙想白云裏，采苓春日遲。","溪花藏石徑，巖翠带茅茨。","九轉莫飞去，三迴良在茲。","還嗤茂陵客，貧病老明时。"]', '诗', 'shi', '', NULL, '送楊錥歸隱 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dc509bf-e84f-4620-a96e-1cae4e90568e', '酬劉起居臥病見寄', '酬劉起居臥病见寄', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["承顏看彩服，不覺別丹墀。","味道能忘病，過庭更學詩。","繚垣多畫戟，遠岫入書帷。","竹靜攜琴處，林香讓果時。","聲同叨眷早，交澹在年衰。","更枉兼金贈，難爲繼組詞。"]', '["承顏看彩服，不覺別丹墀。","味道能忘病，過庭更学诗。","繚垣多畫戟，远岫入书帷。","竹静携琴处，林香讓果时。","声同叨眷早，交澹在年衰。","更枉兼金贈，难爲繼組词。"]', '诗', 'shi', '', NULL, '酬劉起居臥病見寄 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29662366-bce9-48c6-8472-b01e35ce558b', '陪南省諸公宴殿中李監宅', '陪南省諸公宴殿中李監宅', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["將門高勝霍，相子寵過韋。","宦貴攀龍後，心傾待士時。","壺觴開雅宴，鴛鷺眷相隨。","舞退燕姬曲，歌徴謝朓詩。","晚鐘過竹靜，醉客出花遲。","莫惜留餘興，良辰不可追。"]', '["將门高勝霍，相子寵過韋。","宦貴攀龙後，心傾待士时。","壺觴开雅宴，鴛鷺眷相隨。","舞退燕姬曲，歌徴謝朓诗。","晚鐘過竹静，醉客出花遲。","莫惜留餘兴，良辰不可追。"]', '诗', 'shi', '', NULL, '陪南省諸公宴殿中李監宅 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a93b3a91-73b6-4087-8757-5a8f1c8d4161', '山齋讀書寄時校書杜叟', '山斋读书寄时校书杜叟', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["日愛蘅茅下，閑觀山海圖。","幽人自守樸，窮谷也名愚。","倒嶺和溪雨，新泉到戶樞。","叢蘭齊稚子，蟠木老潛夫。","憶戴差過剡，遊仙慣入壺。","濠梁時一訪，莊叟亦吾徒。"]', '["日愛蘅茅下，闲观山海圖。","幽人自守樸，窮谷也名愚。","倒嶺和溪雨，新泉到戶樞。","叢蘭齊稚子，蟠木老潛夫。","憶戴差過剡，游仙慣入壺。","濠梁时一訪，莊叟亦吾徒。"]', '诗', 'shi', '', NULL, '山齋讀書寄時校書杜叟 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd4b2d0e-0589-42d8-8360-5d464a7f69ba', '晚歸藍田舊居', '晚归藍田旧居', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["雲卷東臯下，歸來省故蹊。","泉移憐石在，林長覺原低。","舊里情難盡，前山賞未迷。","引藤看古木，嘗酒咒春雞。","興與時髦背，年將野老齊。","才微甘引退，應得遂霞棲。"]', '["云卷东臯下，归来省故蹊。","泉移怜石在，林长覺原低。","旧里情难尽，前山賞未迷。","引藤看古木，嘗酒咒春雞。","兴與时髦背，年將野老齊。","才微甘引退，應得遂霞棲。"]', '诗', 'shi', '', NULL, '晚歸藍田舊居 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3a14148-94d9-47f2-afff-9f9ef345b018', '寄袁州李嘉祐員外', '寄袁州李嘉祐員外', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["誰謂江山阻，心親夢想偏。","容輝常在目，離別任經年。","郡國通流水，雲霞共遠天。","行春鶯幾囀，遲客月頻圓。","雁有歸鄉羽，人無訪戴船。","願徴黃霸入，相見玉堦前。"]', '["誰謂江山阻，心親梦想偏。","容輝常在目，離別任經年。","郡国通流水，云霞共远天。","行春鶯幾囀，遲客月頻圓。","雁有归乡羽，人無訪戴船。","願徴黄霸入，相见玉堦前。"]', '诗', 'shi', '', NULL, '寄袁州李嘉祐員外 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f71df05c-fb92-4309-bdd7-42b4bac260e0', '禁闈玩雪寄薛左丞', '禁闈玩雪寄薛左丞', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["玄雲低禁苑，飛雪滿神州。","虛白生臺榭，寒光入冕旒。","粉凝宮壁靜，乳結洞門幽。","細繞迴風轉，輕隨落羽浮。","怒濤堆砌石，新月孕簾鉤。","爲報詩人道，豐年頌聖猷。"]', '["玄云低禁苑，飞雪满神州。","虛白生台榭，寒光入冕旒。","粉凝宮壁静，乳結洞门幽。","細繞迴风轉，轻隨落羽浮。","怒濤堆砌石，新月孕簾鉤。","爲報诗人道，豐年頌聖猷。"]', '诗', 'shi', '', NULL, '禁闈玩雪寄薛左丞 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('640ccaba-b1a4-4514-a86d-a11cbc79ba83', '春暮過石龜谷題溫處士林園', '春暮過石龟谷題溫处士林园', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["隱几無名老，何年此陸沈。","丘園自得性，婚嫁不嬰心。","歲計因山薄，霞棲在谷深。","設罝連草色，曬藥背松陰。","觸興雲生岫，隨耕鳥下林。","搘頤笑來客，頭上有朝簪。"]', '["隐几無名老，何年此陸沈。","丘园自得性，婚嫁不嬰心。","歲計因山薄，霞棲在谷深。","設罝連草色，曬藥背松陰。","觸兴云生岫，隨耕鸟下林。","搘頤笑来客，头上有朝簪。"]', '诗', 'shi', '', NULL, '春暮過石龜谷題溫處士林園 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9d6adb6-6033-4175-baaf-97f3db090c78', '宿畢侍御宅', '宿畢侍御宅', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["交情頻更好，子有古人風。","晤語清霜裏，平生苦節同。","心惟二仲合，室乃一瓢空。","落葉寄秋菊，愁雲低夜鴻。","薄寒燈影外，殘漏雨聲中。","明發南昌去，迴看御史驄。"]', '["交情頻更好，子有古人风。","晤語清霜裏，平生苦節同。","心惟二仲合，室乃一瓢空。","落葉寄秋菊，愁云低夜鴻。","薄寒灯影外，殘漏雨声中。","明發南昌去，迴看御史驄。"]', '诗', 'shi', '', NULL, '宿畢侍御宅 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e43ced07-3782-4596-86e0-e748eccd9622', '中書遇雨', '中书遇雨', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["濟旱惟宸慮，爲霖即上台。","雲銜七曜起，雨拂九門來。","綸閣飛絲度，龍渠激霤迴。","色翻池上藻，香裛鼎前杯。","湘燕皆舒翼，沙鱗豈曝腮。","尺波應萬假，虞海載沿洄。"]', '["濟旱惟宸慮，爲霖即上台。","云銜七曜起，雨拂九门来。","綸閣飞絲度，龙渠激霤迴。","色翻池上藻，香裛鼎前杯。","湘燕皆舒翼，沙鱗豈曝腮。","尺波應万假，虞海載沿洄。"]', '诗', 'shi', '', NULL, '中書遇雨 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7edac9b-6714-4330-95e9-0b695484bd0c', '適楚次徐城', '適楚次徐城', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["去家隨旅雁，幾日到南荆。","行邁改鄉邑，苦辛淹晦明。","畏途在淫雨，未暮息趨程。","窮木對秋館，寒鵶愁古城。","迷津坐爲客，對酒默含情。","感激念知己，匣中孤劒鳴。"]', '["去家隨旅雁，幾日到南荆。","行邁改乡邑，苦辛淹晦明。","畏途在淫雨，未暮息趨程。","窮木对秋館，寒鵶愁古城。","迷津坐爲客，对酒默含情。","感激念知己，匣中孤劒鳴。"]', '诗', 'shi', '', NULL, '適楚次徐城 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c539004-fd69-4e60-98ae-21cabb9fcb5d', '經李蒙潁陽舊居', '經李蒙潁陽旧居', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["同心而早世，天道亦何論。","獨有山陽宅，平生永不諼。","青溪引白鳥，流涕弔芳蓀。","蔓草入空室，叢篁深毀垣。","舊遊還在眼，神理更忘言。","唯見東山月，人亡不去門。"]', '["同心而早世，天道亦何論。","独有山陽宅，平生永不諼。","青溪引白鸟，流涕弔芳蓀。","蔓草入空室，叢篁深毀垣。","旧游還在眼，神理更忘言。","唯见东山月，人亡不去门。"]', '诗', 'shi', '', NULL, '經李蒙潁陽舊居 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55f7b8d1-9abc-4f67-bef9-8e252e8913eb', '贈漢陽隱者', '贈漢陽隐者', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["當年不出世，知子餐霞人。","樂道復安土，遺榮長隱身。","蘅茅古林曲，秔稻清江濱。","桂棹爲漁暇，荷衣禦暑新。","欵顏行在役，幽興惜今晨。","分手天涯去，再來芳杜春。"]', '["當年不出世，知子餐霞人。","乐道复安土，遺榮长隐身。","蘅茅古林曲，秔稻清江濱。","桂棹爲漁暇，荷衣禦暑新。","欵顏行在役，幽兴惜今晨。","分手天涯去，再来芳杜春。"]', '诗', 'shi', '', NULL, '贈漢陽隱者 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13b8dada-0713-4533-b800-e16730f3cb2e', '巨魚縱大壑', '巨鱼縱大壑', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["巨魚縱大壑，遂性似乘時。","奮躍風生鬣，騰凌浪鼓鰭。","龍攄回地軸，鯤化想天池。","方快吞舟意，尤殊在藻嬉。","傾危嗟幕燕，隱晦誚泥龜。","喻士逢明主，才猷得所施。"]', '["巨鱼縱大壑，遂性似乘时。","奮躍风生鬣，腾凌浪鼓鰭。","龙攄回地軸，鯤化想天池。","方快吞舟意，尤殊在藻嬉。","傾危嗟幕燕，隐晦誚泥龟。","喻士逢明主，才猷得所施。"]', '诗', 'shi', '', NULL, '巨魚縱大壑 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('343b032d-f3e3-4653-8f66-693c4759b9ed', '送李九歸河北', '送李九归河北', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["文武資人望，謀猷簡聖情。","南州初臥鼓，東土復維城。","寄重分符去，威仍出閫行。","斗牛移八座，日月送雙旌。","別戀瞻天起，仁風應物生。","佇聞收組練，鏘玉會承明。"]', '["文武資人望，謀猷簡聖情。","南州初臥鼓，东土复維城。","寄重分符去，威仍出閫行。","斗牛移八座，日月送雙旌。","別戀瞻天起，仁风應物生。","佇闻收組練，鏘玉會承明。"]', '诗', 'shi', '', NULL, '送李九歸河北 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61919d72-7cf7-4cb0-892a-f7c1375e2cbf', '送丁著作佐台郡', '送丁著作佐台郡', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["多年金馬客，名遂動歸輪。","佐郡紫書下，過門朱綬新。","揚舲望海嶽，入境背風塵。","水驛偏乘月，梅園別受春。","帶經臨府吏，鱠鯉待鄉人。","始見美高士，逍遙在搢紳。"]', '["多年金马客，名遂动归輪。","佐郡紫书下，過门朱綬新。","揚舲望海嶽，入境背风塵。","水驛偏乘月，梅园別受春。","带經臨府吏，鱠鯉待乡人。","始见美高士，逍遙在搢紳。"]', '诗', 'shi', '', NULL, '送丁著作佐台郡 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55a514f9-8f2d-4808-9dbe-2b5bd9fb2c3a', '送王使君赴太原行營', '送王使君赴太原行營', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["太白明無象，皇威未戢戈。","諸侯持節鉞，千里控山河。","漢驛雙旌度，胡沙七騎過。","驚蓬連雁起，牧馬入雲多。","不賣盧龍塞，能消瀚海波。","須傳出師頌，莫奏式微歌。"]', '["太白明無象，皇威未戢戈。","諸侯持節鉞，千里控山河。","漢驛雙旌度，胡沙七騎過。","驚蓬連雁起，牧马入云多。","不賣盧龙塞，能消瀚海波。","須傳出師頌，莫奏式微歌。"]', '诗', 'shi', '', NULL, '送王使君赴太原行營 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bc9b969-9c4a-4eb5-b04b-f4f35e62ec47', '送王使君移鎮淮南', '送王使君移鎮淮南', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["共許徐方牧，能臨河內人。","郡移棠轉茂，車至鹿還馴。","吏事嘉師旅，鴛行惜搢紳。","別心傾祖席，愁望盡征輪。","紫誥徴黃晚，蒼生借寇頻。","願言青瑣拜，早及上林春。"]', '["共許徐方牧，能臨河內人。","郡移棠轉茂，车至鹿還馴。","吏事嘉師旅，鴛行惜搢紳。","別心傾祖席，愁望尽征輪。","紫誥徴黄晚，蒼生借寇頻。","願言青瑣拜，早及上林春。"]', '诗', 'shi', '', NULL, '送王使君移鎮淮南 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba7ba1ff-412a-4712-882e-a2ec1b98b51d', '李四勸爲尉氏尉李七勉爲開封尉', '李四勸爲尉氏尉李七勉爲开封尉', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["美政惟兄弟，時人數俊賢。","皇枝雙玉樹，吏道二梅仙。","自理堯唐俗，唯將禮讓傳。","采蘭花萼聚，就日雁行聯。","黃綬俄三載，青雲未九遷。","廟堂爲宰制，幾日試龍泉。"]', '["美政惟兄弟，时人數俊賢。","皇枝雙玉樹，吏道二梅仙。","自理堯唐俗，唯將禮讓傳。","采蘭花萼聚，就日雁行聯。","黄綬俄三載，青云未九遷。","廟堂爲宰制，幾日試龙泉。"]', '诗', 'shi', '', NULL, '李四勸爲尉氏尉李七勉爲開封尉 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec9a1596-11c5-4ec6-8703-7aca554401a7', '春夜宴任六昆季宅', '春夜宴任六昆季宅', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["際晚綠煙起，入門芳樹深。","不才叨下客，喜宴齒諸簪。","夜月仍攜妓，清風更在林。","彩毫揮露色，銀燭動花陰。","自接通家好，應知待士心。","向隅逢故識，茲夕願披襟。"]', '["際晚綠煙起，入门芳樹深。","不才叨下客，喜宴齒諸簪。","夜月仍携妓，清风更在林。","彩毫揮露色，銀燭动花陰。","自接通家好，應知待士心。","向隅逢故識，茲夕願披襟。"]', '诗', 'shi', '', NULL, '春夜宴任六昆季宅 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf85b33f-2983-438d-9ece-150704d32a5e', '閑居酬張起居見贈', '闲居酬張起居见贈', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["在林非避世，守拙自離羣。","弱羽謝風水，窮愁依典墳。","良知不遐棄，新詠獨相聞。","能使幽興苦，坐忘清景曛。","前山帶喬木，暮鳥聯歸雲。","向夕野人思，難忘騎省文。"]', '["在林非避世，守拙自離羣。","弱羽謝风水，窮愁依典墳。","良知不遐棄，新詠独相闻。","能使幽兴苦，坐忘清景曛。","前山带喬木，暮鸟聯归云。","向夕野人思，难忘騎省文。"]', '诗', 'shi', '', NULL, '閑居酬張起居見贈 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26943b87-d7f6-4b6d-85ee-f503574d8e48', '奉和王相公秋日戲贈元校書', '奉和王相公秋日戲贈元校书', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["才妙心仍遠，名疎跡可追。","清秋聞禮暇，新雨到山時。","勝事唯愁盡，幽尋不厭遲。","弄雲憐鶴去，隔水許僧期。","賢相敦高躅，雕龍憶所思。","芙蓉洗清露，願比謝公詩。"]', '["才妙心仍远，名疎跡可追。","清秋闻禮暇，新雨到山时。","勝事唯愁尽，幽尋不厭遲。","弄云怜鹤去，隔水許僧期。","賢相敦高躅，雕龙憶所思。","芙蓉洗清露，願比謝公诗。"]', '诗', 'shi', '', NULL, '奉和王相公秋日戲贈元校書 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cf83e73-37ad-49f3-a32f-849763a9c582', '過楊駙馬亭子', '過楊駙马亭子', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["衣冠在漢庭，臺榭接天成。","彩鳳翻簫曲，祥鱣入館名。","歌鐘芳月曙，林嶂碧雲生。","亂水歸潭淨，高花映竹明。","退朝追宴樂，開閤醉簪纓。","長袖留嘉客，棲烏下禁城。"]', '["衣冠在漢庭，台榭接天成。","彩鳳翻簫曲，祥鱣入館名。","歌鐘芳月曙，林嶂碧云生。","亂水归潭淨，高花映竹明。","退朝追宴乐，开閤醉簪纓。","长袖留嘉客，棲烏下禁城。"]', '诗', 'shi', '', NULL, '過楊駙馬亭子 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52f9fa21-bd71-4ad3-b35b-572d2871e34d', '山下別杜少府', '山下別杜少府', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["把手意難盡，前山日漸低。","情人那忍別，宿鳥尚同棲。","寸晷戀言笑，佳期欲阻暌。","離雲愁出岫，去水咽分溪。","莊叟幾虛說，楊朱空自迷。","傷心獨歸路，秋草更萋萋。"]', '["把手意难尽，前山日漸低。","情人那忍別，宿鸟尚同棲。","寸晷戀言笑，佳期欲阻暌。","離云愁出岫，去水咽分溪。","莊叟幾虛说，楊朱空自迷。","傷心独归路，秋草更萋萋。"]', '诗', 'shi', '', NULL, '山下別杜少府 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('330ad11e-9ff8-4a63-94c0-c8ea9d8c1da5', '晚出青門望終南別業', '晚出青门望終南別業', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["能清謝朓思，暫下承明廬。","遠山新水下，寒臯微雨餘。","更憐歸鳥去，宛到臥龍居。","笑指叢林上，閑雲自卷舒。","寧心鳴鳳日，却意釣璜初。","處貴有餘興，伊周位不如。"]', '["能清謝朓思，暫下承明廬。","远山新水下，寒臯微雨餘。","更怜归鸟去，宛到臥龙居。","笑指叢林上，闲云自卷舒。","寧心鳴鳳日，却意釣璜初。","处貴有餘兴，伊周位不如。"]', '诗', 'shi', '', NULL, '晚出青門望終南別業 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6987da5d-1275-4ac6-9694-2b84e5649bc8', '送嚴士良侍奉詹事南遊', '送嚴士良侍奉詹事南游', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["疏傅獨知止，曾參善愛親。","江山侍行邁，長幼出囂塵。","握手想千古，此心能幾人。","風光滿長陌，草色傍征輪。","日夕望荆楚，鶯鳴芳杜新。","漁煙月下淺，花嶼水中春。","點翰遙相憶，含情向白蘋。"]', '["疏傅独知止，曾參善愛親。","江山侍行邁，长幼出囂塵。","握手想千古，此心能幾人。","风光满长陌，草色傍征輪。","日夕望荆楚，鶯鳴芳杜新。","漁煙月下淺，花嶼水中春。","点翰遙相憶，含情向白蘋。"]', '诗', 'shi', '', NULL, '送嚴士良侍奉詹事南遊 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2190396c-d2fe-4c15-ac78-3cec3d332d26', '題祕書王迪城北池亭', '題祕书王迪城北池亭', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["子喬來魏闕，明主賜衣簪。","從宦辭人事，同塵即道心。","還追大隱跡，寄此鳳城陰。","昨夜新煙雨，池臺清且深。","伏泉通粉壁，迸筍出花林。","晚沐常多暇，春醪時獨斟。","西南漢宮月，復對綠窗琴。"]', '["子喬来魏闕，明主賜衣簪。","從宦辞人事，同塵即道心。","還追大隐跡，寄此鳳城陰。","昨夜新煙雨，池台清且深。","伏泉通粉壁，迸筍出花林。","晚沐常多暇，春醪时独斟。","西南漢宮月，复对綠窗琴。"]', '诗', 'shi', '', NULL, '題祕書王迪城北池亭 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70327e7a-b43e-446d-8e1b-7e9960187f27', '過王舍人宅', '過王舍人宅', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["入門花柳暗，知是近臣居。","大隱心何遠，高風物自疎。","翛然靜者事，宛得上皇餘。","雞犬偷仙藥，兒童授道書。","清吟送客後，微月上城初。","彩筆有新詠，文星垂太虛。","承恩金殿宿，應薦馬相如。"]', '["入门花柳暗，知是近臣居。","大隐心何远，高风物自疎。","翛然静者事，宛得上皇餘。","雞犬偷仙藥，兒童授道书。","清吟送客後，微月上城初。","彩笔有新詠，文星垂太虛。","承恩金殿宿，應薦马相如。"]', '诗', 'shi', '', NULL, '過王舍人宅 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f7faa58-f813-4378-b330-1ad84df49fa8', '過瑞龍觀道士', '過瑞龙观道士', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["不知誰氏子，鍊魄家洞天。","鶴待成丹日，人尋種杏田。","靈山含道氣，物性皆自然。","白鹿顧瑞草，驪龍蟠玉泉。","得茲象外趣，便割區中緣。","石竇采雲母，霞堂陪列仙。","主人善止客，柯爛忘歸年。"]', '["不知誰氏子，鍊魄家洞天。","鹤待成丹日，人尋種杏田。","靈山含道氣，物性皆自然。","白鹿顧瑞草，驪龙蟠玉泉。","得茲象外趣，便割區中緣。","石竇采云母，霞堂陪列仙。","主人善止客，柯爛忘归年。"]', '诗', 'shi', '', NULL, '過瑞龍觀道士 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19cff319-a64c-48e5-9d65-72d343467291', '送沈仲', '送沈仲', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["天樸非外假，至人常晏如。","心期邈霄漢，詞律響瓊琚。","舉酒常歎息，無人達子虛。","夜光失隋掌，驥騄伏鹽車。","考室晉山下，歸田秦歲初。","寒雲隨路合，落照下城餘。","千里還同術，無勞怨索居。"]', '["天樸非外假，至人常晏如。","心期邈霄漢，词律响瓊琚。","舉酒常歎息，無人達子虛。","夜光失隋掌，驥騄伏鹽车。","考室晉山下，归田秦歲初。","寒云隨路合，落照下城餘。","千里還同術，無勞怨索居。"]', '诗', 'shi', '', NULL, '送沈仲 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abdfd24a-c447-4736-bff8-b602262b0cd3', '和韋侍御寓直對雨', '和韋侍御寓直对雨', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["名貫四科首，班宜二妙齊。","如何厭白簡，未得步金閨。","寓直晦秋雨，吟餘聞遠雞。","漏聲過旦冷，雲色向窗低。","誰謂霄漢近，翻嗟心事暌。","蘭滋人未握，霜曉鶚還棲。","佇見田郎字，親勞御筆題。"]', '["名貫四科首，班宜二妙齊。","如何厭白簡，未得步金閨。","寓直晦秋雨，吟餘闻远雞。","漏声過旦冷，云色向窗低。","誰謂霄漢近，翻嗟心事暌。","蘭滋人未握，霜晓鶚還棲。","佇见田郎字，親勞御笔題。"]', '诗', 'shi', '', NULL, '和韋侍御寓直對雨 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4113be6-a9a4-4a1d-b35b-9c0d61ecf35f', '奉和聖製登朝元閣', '奉和聖製登朝元閣', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["六合紆玄覽，重軒啓上清。","石林飛棟出，霞頂泰堦平。","拂曙鑾輿上，晞陽瑞雪晴。","翠微回日馭，丹巘駐天行。","御氣升銀漢，垂衣俯錦城。","山通玉苑迥，河抱紫關明。","感物乾文動，凝神道化成。","周王陟喬嶽，列辟讓英聲。"]', '["六合紆玄覽，重軒啓上清。","石林飞棟出，霞頂泰堦平。","拂曙鑾輿上，晞陽瑞雪晴。","翠微回日馭，丹巘駐天行。","御氣升銀漢，垂衣俯錦城。","山通玉苑迥，河抱紫关明。","感物乾文动，凝神道化成。","周王陟喬嶽，列辟讓英声。"]', '诗', 'shi', '', NULL, '奉和聖製登朝元閣 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2557d68d-62fd-4a67-a4fc-1a926ec74c43', '奉和杜相公移長興宅奉呈元相公', '奉和杜相公移长兴宅奉呈元相公', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["守貴常思儉，平津此意深。","能卑丞相宅，何謝故人心。","種蕙初抽帶，移篁不改陰。","院梅朝助鼎，池鳳夕歸林。","覺路經中得，滄州夢裏尋。","道高仍濟代，恩重豈投簪。","報國誰知己，推賢共作霖。","興來文雅振，清韻擲雙金。"]', '["守貴常思儉，平津此意深。","能卑丞相宅，何謝故人心。","種蕙初抽带，移篁不改陰。","院梅朝助鼎，池鳳夕归林。","覺路經中得，滄州梦裏尋。","道高仍濟代，恩重豈投簪。","報国誰知己，推賢共作霖。","兴来文雅振，清韻擲雙金。"]', '诗', 'shi', '', NULL, '奉和杜相公移長興宅奉呈元相公 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf0bd1f5-19cd-4465-944c-b1eda8c18787', '送任先生任唐山丞', '送任先生任唐山丞', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["再命果良願，幾年勤說詩。","上公頻握髮，才子共垂帷。","琢玉成良器，出門偏愴離。","腰章佐墨綬，耀錦到茅茨。","樹老見家日，潮平歸縣時。","衣催蓮女織，頌聽海人詞。","鴻鵠志應在，荃蘭香未衰。","金門定回音，雲路有佳期。"]', '["再命果良願，幾年勤说诗。","上公頻握髮，才子共垂帷。","琢玉成良器，出门偏愴離。","腰章佐墨綬，耀錦到茅茨。","樹老见家日，潮平归縣时。","衣催蓮女织，頌听海人词。","鴻鵠志應在，荃蘭香未衰。","金门定回音，云路有佳期。"]', '诗', 'shi', '', NULL, '送任先生任唐山丞 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('734082e0-4ce9-41a5-bd6d-5079e9dd8894', '送外甥懷素上人歸鄉侍奉', '送外甥懷素上人归乡侍奉', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["釋子吾家寶，神清慧有餘。","能翻梵王字，妙盡伯英書。","遠鶴無前侶，孤雲寄太虛。","狂來輕世界，醉裏得真如。","飛錫離鄉久，寧親喜臘初。","故池殘雪滿，寒柳霽煙疎。","壽酒還嘗藥，晨餐不薦魚。","遙知禪誦外，健筆賦閑居。"]', '["釋子吾家寶，神清慧有餘。","能翻梵王字，妙尽伯英书。","远鹤無前侶，孤云寄太虛。","狂来轻世界，醉裏得真如。","飞錫離乡久，寧親喜臘初。","故池殘雪满，寒柳霽煙疎。","壽酒還嘗藥，晨餐不薦鱼。","遙知禪誦外，健笔賦闲居。"]', '诗', 'shi', '', NULL, '送外甥懷素上人歸鄉侍奉 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c12c75e-bc0c-42b9-9cf4-8ac4551fe6d0', '送張中丞赴桂州', '送張中丞赴桂州', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["出守求人瘼，推賢動聖情。","紫臺初下詔，皁蓋始專城。","寵借飛霜簡，威加却月營。","雲衢降五馬，林木引雙旌。","夙仰敦詩禮，嘗聞偃甲兵。","戍樓雲外靜，訟閣竹間清。","化佇還珠美，心將片玉貞。","寇恂朝望重，計日謁承明。"]', '["出守求人瘼，推賢动聖情。","紫台初下詔，皁蓋始專城。","寵借飞霜簡，威加却月營。","云衢降五马，林木引雙旌。","夙仰敦诗禮，嘗闻偃甲兵。","戍楼云外静，訟閣竹间清。","化佇還珠美，心將片玉貞。","寇恂朝望重，計日謁承明。"]', '诗', 'shi', '', NULL, '送張中丞赴桂州 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3255bc39-f3ff-4c7b-9ac9-ccc21176db06', '送王相公赴范陽', '送王相公赴范陽', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["翊聖銜恩重，頻年按節行。","安危皆報國，文武不緣名。","受脤乃調鼎，爲霖更洗兵。","幕開丞相閣，旗總貳師營。","料敵知無戰，安邊示有征。","代雲橫馬首，燕雁拂笳聲。","去鎮關河靜，歸看日月明。","欲知瞻戀切，遲暮一書生。"]', '["翊聖銜恩重，頻年按節行。","安危皆報国，文武不緣名。","受脤乃調鼎，爲霖更洗兵。","幕开丞相閣，旗總貳師營。","料敵知無戰，安邊示有征。","代云橫马首，燕雁拂笳声。","去鎮关河静，归看日月明。","欲知瞻戀切，遲暮一书生。"]', '诗', 'shi', '', NULL, '送王相公赴范陽 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e39a5238-d181-487d-808d-000779ef2d19', '送蔣尚書居守東都', '送蔣尚书居守东都', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["鳳輦幸秦久，周人徯帝情。","若非君敏德，誰鎮洛陽城。","前席命才彥，舉朝推令名。","綸言動北斗，職事守東京。","鄭履下天去，蘧輪滿路聲。","出關秋樹直，對闕遠山明。","肅肅保釐處，水流宮苑清。","長安日西笑，朝夕衮衣迎。"]', '["鳳輦幸秦久，周人徯帝情。","若非君敏德，誰鎮洛陽城。","前席命才彥，舉朝推令名。","綸言动北斗，職事守东京。","鄭履下天去，蘧輪满路声。","出关秋樹直，对闕远山明。","肅肅保釐处，水流宮苑清。","长安日西笑，朝夕衮衣迎。"]', '诗', 'shi', '', NULL, '送蔣尚書居守東都 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31a82e8a-53af-4220-9393-d779aa38b6a4', '送李兵曹赴河中', '送李兵曹赴河中', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["能荷鐘鼎業，不矜紈綺榮。","侯門三事後，儒服一書生。","昔志學文史，立身爲士英。","驪珠難隱耀，臯鶴會長鳴。","休命且隨牒，候時常振纓。","寒蟬思關柳，匹馬向蒲城。","秋日黯將暮，黃河如欲清。","黎人思坐嘯，知子樹佳聲。"]', '["能荷鐘鼎業，不矜紈綺榮。","侯门三事後，儒服一书生。","昔志学文史，立身爲士英。","驪珠难隐耀，臯鹤會长鳴。","休命且隨牒，候时常振纓。","寒蟬思关柳，匹马向蒲城。","秋日黯將暮，黄河如欲清。","黎人思坐嘯，知子樹佳声。"]', '诗', 'shi', '', NULL, '送李兵曹赴河中 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8267ac9-1f33-4532-a703-d641f992c721', '罷官後酬元校書見贈', '罷官後酬元校书见贈', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["心期悵已阻，交道復何如。","自我辭丹闕，惟君到故廬。","忘機貧負米，憶戴出無車。","鄰犬吠初服，家人愁斗儲。","秋堂入閑夜，雲月思離居。","窮巷聞砧冷，荒枝應鵲疎。","宦名隨落葉，生事感枯魚。","臨水仍揮手，知音未棄余。"]', '["心期悵已阻，交道复何如。","自我辞丹闕，惟君到故廬。","忘機貧負米，憶戴出無车。","鄰犬吠初服，家人愁斗儲。","秋堂入闲夜，云月思離居。","窮巷闻砧冷，荒枝應鵲疎。","宦名隨落葉，生事感枯鱼。","臨水仍揮手，知音未棄余。"]', '诗', 'shi', '', NULL, '罷官後酬元校書見贈 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea805a63-234b-4905-bf2b-eb1386df69a6', '同鄔戴關中旅寓', '同鄔戴关中旅寓', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["文士皆求遇，今人誰至公。","靈臺一寄宿，楊柳再春風。","更惜忘形友，頻年失志同。","羽毛齊燕雀，心事阻鴛鴻。","留滯慚歸養，飛鳴恨觸籠。","橘懷鄉夢裏，書去客愁中。","殘雪迷歸雁，韶光棄斷蓬。","吞悲問唐舉，何路出屯蒙。"]', '["文士皆求遇，今人誰至公。","靈台一寄宿，楊柳再春风。","更惜忘形友，頻年失志同。","羽毛齊燕雀，心事阻鴛鴻。","留滯慚归養，飞鳴恨觸籠。","橘懷乡梦裏，书去客愁中。","殘雪迷归雁，韶光棄斷蓬。","吞悲问唐舉，何路出屯蒙。"]', '诗', 'shi', '', NULL, '同鄔戴關中旅寓 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f525551a-715b-428d-8d6e-9dfe7d5a7181', '新豐主人', '新豐主人', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["明代少知己，夜光頻暗投。","迍邅終薄命，動息盡窮愁。","自欲歸飛鷁，當爲不繫舟。","雙垂素絲淚，幾弊皁貂裘。","暮鳥棲幽樹，孤雲出舊丘。","蛩悲衣褐夕，雨暗轉蓬秋。","客裏馮諼劒，歌中甯戚牛。","主人能縱酒，一醉且忘憂。"]', '["明代少知己，夜光頻暗投。","迍邅終薄命，动息尽窮愁。","自欲归飞鷁，當爲不繫舟。","雙垂素絲泪，幾弊皁貂裘。","暮鸟棲幽樹，孤云出旧丘。","蛩悲衣褐夕，雨暗轉蓬秋。","客裏馮諼劒，歌中甯戚牛。","主人能縱酒，一醉且忘憂。"]', '诗', 'shi', '', NULL, '新豐主人 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('412b1025-4c86-495c-a2d0-07393f01d36b', '夕遊覆釜山道士觀因登玄元廟', '夕游覆釜山道士观因登玄元廟', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["冥搜過物表，洞府次溪傍。","已入瀛洲遠，誰言仙路長。","孤煙出深竹，道侶正焚香。","鳴磬愛山靜，步虛宜夜涼。","仍同象帝廟，更上紫霞岡。","霽月懸琪樹，明星映碧堂。","傾思丹竈術，願采玉芝芳。","儻把浮丘袂，乘雲別舊鄉。"]', '["冥搜過物表，洞府次溪傍。","已入瀛洲远，誰言仙路长。","孤煙出深竹，道侶正焚香。","鳴磬愛山静，步虛宜夜涼。","仍同象帝廟，更上紫霞岡。","霽月懸琪樹，明星映碧堂。","傾思丹竈術，願采玉芝芳。","儻把浮丘袂，乘云別旧乡。"]', '诗', 'shi', '', NULL, '夕遊覆釜山道士觀因登玄元廟 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('502bbda5-2aff-47f8-85e8-f97686c59769', '陪郭常侍令公東亭宴集', '陪郭常侍令公东亭宴集', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["盛業山河列，重名劒履榮。","珥貂爲相子，開閤引時英。","美景池臺色，佳期宴賞情。","詞人載筆至，仙妓出花迎。","暗竹朱輪轉，迴塘玉佩鳴。","舞衫招戲蝶，歌扇隔啼鶯。","飲德心皆醉，披雲興轉清。","不愁懽樂盡，積慶在和羹。"]', '["盛業山河列，重名劒履榮。","珥貂爲相子，开閤引时英。","美景池台色，佳期宴賞情。","词人載笔至，仙妓出花迎。","暗竹朱輪轉，迴塘玉佩鳴。","舞衫招戲蝶，歌扇隔啼鶯。","饮德心皆醉，披云兴轉清。","不愁懽乐尽，積慶在和羹。"]', '诗', 'shi', '', NULL, '陪郭常侍令公東亭宴集 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f51694bd-8955-4c4d-9ed6-673c2fbb5321', '太子李舍人城東別業與二三文友逃暑', '太子李舍人城东別業與二三文友逃暑', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["下馬失炎暑，重門深綠篁。","宮臣禮嘉客，林表開蘭堂。","茲夕興難盡，澄罍照墨塲。","鮮風吹印綬，密坐皆馨香。","美景惜文會，清吟遲羽觴。","東林晚來好，目極趣何長。","鳥道挂疎雨，人家殘夕陽。","城隅擁歸騎，留醉戀瓊芳。"]', '["下马失炎暑，重门深綠篁。","宮臣禮嘉客，林表开蘭堂。","茲夕兴难尽，澄罍照墨塲。","鲜风吹印綬，密坐皆馨香。","美景惜文會，清吟遲羽觴。","东林晚来好，目極趣何长。","鸟道挂疎雨，人家殘夕陽。","城隅擁归騎，留醉戀瓊芳。"]', '诗', 'shi', '', NULL, '太子李舍人城東別業與二三文友逃暑 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbda2c85-f609-450a-8e93-a6c8f2723372', '柏崖老人號無名先生男削髮女黃冠自以雲泉獨樂命予賦詩', '柏崖老人號無名先生男削髮女黄冠自以云泉独乐命予賦诗', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["古也憂婚嫁，君能樂性腸。","長男棲月宇，少女炫霓裳。","問爾餐霞處，春山芝桂旁。","鶴前飛九轉，壺裏駐三光。","與我開龍嶠，披雲靜藥堂。","胡麻兼藻綠，石髓隔花香。","帝力言何有，椿年喜漸長。","窅然高象外，寧不傲羲皇。"]', '["古也憂婚嫁，君能乐性腸。","长男棲月宇，少女炫霓裳。","问爾餐霞处，春山芝桂旁。","鹤前飞九轉，壺裏駐三光。","與我开龙嶠，披云静藥堂。","胡麻兼藻綠，石髓隔花香。","帝力言何有，椿年喜漸长。","窅然高象外，寧不傲羲皇。"]', '诗', 'shi', '', NULL, '柏崖老人號無名先生男削髮女黃冠自以雲泉獨樂命予賦詩 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7acefb15-1b2f-4b16-b2a5-812ad64f5942', '贈李十六', '贈李十六', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["半面喜投分，數年欽盛名。","常思夢顏色，誰憶訪柴荆。","忽聽欵扉響，欣然倒屣迎。","蓬蒿駐騶馭，雞犬傍簪纓。","酌水即嘉宴，新知甚故情。","僕夫視日色，棲鳥催車聲。","自爾宴言後，至今門館清。","何當更乘興，林下已苔生。"]', '["半面喜投分，數年欽盛名。","常思梦顏色，誰憶訪柴荆。","忽听欵扉响，欣然倒屣迎。","蓬蒿駐騶馭，雞犬傍簪纓。","酌水即嘉宴，新知甚故情。","僕夫視日色，棲鸟催车声。","自爾宴言後，至今门館清。","何當更乘兴，林下已苔生。"]', '诗', 'shi', '', NULL, '贈李十六 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e63fc312-4dce-4035-b83a-2d781cbf1a80', '裴僕射東亭', '裴僕射东亭', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["鳳扆任匡濟，雲溪難退還。","致君超列辟，得道在榮班。","朱戟繚垣下，高齋芳樹間。","隔花開遠水，廢卷愛晴山。","晚沐值清興，知音同解顏。","藉蘭開賜酒，留客下重關。","仙犬逐人靜，朝車映竹閑。","則知真隱逸，未必謝區寰。"]', '["鳳扆任匡濟，云溪难退還。","致君超列辟，得道在榮班。","朱戟繚垣下，高斋芳樹间。","隔花开远水，廢卷愛晴山。","晚沐值清兴，知音同解顏。","藉蘭开賜酒，留客下重关。","仙犬逐人静，朝车映竹闲。","則知真隐逸，未必謝區寰。"]', '诗', 'shi', '', NULL, '裴僕射東亭 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dd02167-1740-4788-b07d-c411ae73db13', '中書王舍人輞川舊居', '中书王舍人輞川旧居', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["幾年家絕壑，滿徑種芳蘭。","帶石買松貴，通溪漲水寬。","誦經連谷響，吹律減雲寒。","誰謂桃源裏，天書問考槃。","一從解蕙帶，三入偶蟬冠。","今夕復何夕，歸休尋舊歡。","片雲隔蒼翠，春雨半林湍。","藤長穿松蓋，花繁壓藥欄。","景深青眼下，興絕綵毫端。","笑向同來客，登龍此地難。"]', '["幾年家絕壑，满徑種芳蘭。","带石買松貴，通溪漲水寬。","誦經連谷响，吹律減云寒。","誰謂桃源裏，天书问考槃。","一從解蕙带，三入偶蟬冠。","今夕复何夕，归休尋旧歡。","片云隔蒼翠，春雨半林湍。","藤长穿松蓋，花繁壓藥欄。","景深青眼下，兴絕綵毫端。","笑向同来客，登龙此地难。"]', '诗', 'shi', '', NULL, '中書王舍人輞川舊居 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe3ad884-f353-40a0-a854-5b8761bd3b64', '送襄陽盧判官奏開河事', '送襄陽盧判官奏开河事', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["千里趨魏闕，一言簡聖聰。","河流引關外，國用贍秦中。","有詔許其策，隨山興此功。","連雲積石阻，計日安波通。","飛櫂轉年穀，利人勝歲豐。","言歸漢陽路，拜手蓬萊宮。","紫殿賜衣出，青門酣酌同。","晚陽過微雨，秋水見新鴻。","坐惜去車遠，愁看離館空。","因思郢川守，南楚滿清風。"]', '["千里趨魏闕，一言簡聖聰。","河流引关外，国用贍秦中。","有詔許其策，隨山兴此功。","連云積石阻，計日安波通。","飞櫂轉年穀，利人勝歲豐。","言归漢陽路，拜手蓬萊宮。","紫殿賜衣出，青门酣酌同。","晚陽過微雨，秋水见新鴻。","坐惜去车远，愁看離館空。","因思郢川守，南楚满清风。"]', '诗', 'shi', '', NULL, '送襄陽盧判官奏開河事 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30292448-c593-430a-b123-b82914c79ea6', '奉送戶部李郎中充晉國副節度出塞', '奉送戶部李郎中充晉国副節度出塞', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["德佐調梅用，忠輸擊虜年。","子房推廟略，漢主託兵權。","受命榮中禁，分麾鎮左賢。","風生黑山道，星下紫微天。","始願文經國，俄看武定邊。","鬼方堯日遠，幕府代雲連。","汗馬將行矣，盧龍已肅然。","關防驅使節，花月眷離筵。","自忝知音遇，而今感義偏。","淚聞橫吹落，心逐去旌懸。","帝念夔能政，時須說濟川。","勞還應即爾，朝暮玉墀前。"]', '["德佐調梅用，忠輸擊虜年。","子房推廟略，漢主託兵權。","受命榮中禁，分麾鎮左賢。","风生黑山道，星下紫微天。","始願文經国，俄看武定邊。","鬼方堯日远，幕府代云連。","汗马將行矣，盧龙已肅然。","关防驱使節，花月眷離筵。","自忝知音遇，而今感義偏。","泪闻橫吹落，心逐去旌懸。","帝念夔能政，时須说濟川。","勞還應即爾，朝暮玉墀前。"]', '诗', 'shi', '', NULL, '奉送戶部李郎中充晉國副節度出塞 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b8a3c93-5ee4-45fe-a45d-67f843332e30', '奉和中書常舍人晚秋集賢院即事寄徐薛二侍御', '奉和中书常舍人晚秋集賢院即事寄徐薛二侍御', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["文星垂太虛，辭伯綜羣書。","彩筆下鴛掖，褒衣來石渠。","典墳探奧旨，造化覩權輿。","述聖魯宣父，通經漢仲舒。","窗明宜縹帶，地肅近丹除。","清晝刪詩暇，高秋作賦初。","露盤侵漢聳，宮柳度鵶疎。","靜對連雲閣，晴聞過闕車。","舊僚云出矣，晚歲復何如。","海嶠瞻歸路，江城夢直廬。","含毫思兩鳳，望遠寄雙魚。","定笑巴歌拙，還參麗曲餘。"]', '["文星垂太虛，辞伯綜羣书。","彩笔下鴛掖，褒衣来石渠。","典墳探奧旨，造化覩權輿。","述聖魯宣父，通經漢仲舒。","窗明宜縹带，地肅近丹除。","清晝刪诗暇，高秋作賦初。","露盤侵漢聳，宮柳度鵶疎。","静对連云閣，晴闻過闕车。","旧僚云出矣，晚歲复何如。","海嶠瞻归路，江城梦直廬。","含毫思兩鳳，望远寄雙鱼。","定笑巴歌拙，還參丽曲餘。"]', '诗', 'shi', '', NULL, '奉和中書常舍人晚秋集賢院即事寄徐薛二侍御 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf18450f-5fc1-409e-a265-e964ff5ce00b', '和范郎中宿直中書曉翫清池贈南省同僚兩垣遺補', '和范郎中宿直中书晓翫清池贈南省同僚兩垣遺補', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["青瑣留才子，春池靜禁林。","自矜仙島勝，宛在掖垣深。","引派彤庭裏，含虛玉砌陰。","漲來知聖澤，清處見天心。","蘭氣飄紅岸，文星動碧潯。","鳳棲長近日，虬臥欲爲霖。","席寵雖高位，流謙乃素襟。","焚香春漏盡，假寐曉鶯吟。","丹地宜清泚，朝陽復照臨。","司言兼逸趣，鼓興接知音。","六義驚摛藻，三臺響擲金。","爲憐風水外，落羽此漂沈。"]', '["青瑣留才子，春池静禁林。","自矜仙島勝，宛在掖垣深。","引派彤庭裏，含虛玉砌陰。","漲来知聖澤，清处见天心。","蘭氣飄紅岸，文星动碧潯。","鳳棲长近日，虬臥欲爲霖。","席寵雖高位，流謙乃素襟。","焚香春漏尽，假寐晓鶯吟。","丹地宜清泚，朝陽复照臨。","司言兼逸趣，鼓兴接知音。","六義驚摛藻，三台响擲金。","爲怜风水外，落羽此漂沈。"]', '诗', 'shi', '', NULL, '和范郎中宿直中書曉翫清池贈南省同僚兩垣遺補 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e041093-c6eb-4280-8a91-4ad04f25fd93', '同程九早入中書', '同程九早入中书', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["漢家賢相重英奇，蟠木何材也見知。","不意雲霄能自致，空驚鵷鷺忽相隨。","臘雪初明柏子殿，春光欲上萬年枝。","獨慙皇鑒明如日，未厭春光向玉墀。"]', '["漢家賢相重英奇，蟠木何材也见知。","不意云霄能自致，空驚鵷鷺忽相隨。","臘雪初明柏子殿，春光欲上万年枝。","独慙皇鑒明如日，未厭春光向玉墀。"]', '诗', 'shi', '', NULL, '同程九早入中書 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fecb85f-b511-4ca3-9dde-d6ef7c762e26', '仲春宴王補闕城東小池', '仲春宴王補闕城东小池', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["王孫興至幽尋好，芳草春深景氣和。","藥院愛隨流水入，山齋喜與白雲過。","猶嫌巢鶴窺人遠，不厭叢花對客多。","醉來倚玉無餘事，目送歸鴻笑復歌。"]', '["王孫兴至幽尋好，芳草春深景氣和。","藥院愛隨流水入，山斋喜與白云過。","猶嫌巢鹤窺人远，不厭叢花对客多。","醉来倚玉無餘事，目送归鴻笑复歌。"]', '诗', 'shi', '', NULL, '仲春宴王補闕城東小池 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4639195c-ea55-4380-a88f-c1b3dca3282e', '夜宿靈臺寺寄郎士元', '夜宿靈台寺寄郎士元', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["西日橫山含碧空，東方吐月滿禪宮。","朝瞻雙頂青冥上，夜宿諸天色界中。","石潭倒獻蓮花水，塔院空聞松柏風。","萬里故人能尚爾，知君視聽我心同。"]', '["西日橫山含碧空，东方吐月满禪宮。","朝瞻雙頂青冥上，夜宿諸天色界中。","石潭倒獻蓮花水，塔院空闻松柏风。","万里故人能尚爾，知君視听我心同。"]', '诗', 'shi', '', NULL, '夜宿靈臺寺寄郎士元 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e4849dc-c411-49fa-8664-20a58b0493fd', '題郎士元半日吳村別業兼呈李長官', '題郎士元半日吳村別業兼呈李长官', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["半日吳村帶晚霞，閑門高柳亂飛鵶。","橫雲嶺外千重樹，流水聲中一兩家。","愁人昨夜相思苦，閏月今年春意賒。","自歎梅生頭似雪，却憐潘令縣如花。"]', '["半日吳村带晚霞，闲门高柳亂飞鵶。","橫云嶺外千重樹，流水声中一兩家。","愁人昨夜相思苦，閏月今年春意賒。","自歎梅生头似雪，却怜潘令縣如花。"]', '诗', 'shi', '', NULL, '題郎士元半日吳村別業兼呈李長官 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffdf18b6-9fd6-4e38-ba7e-ca42b6ab0ae9', '猷川雪後送僧粲臨還京時避世臥疾', '猷川雪後送僧粲臨還京时避世臥疾', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["連步青溪幾萬重，有時共立在孤峯。","齋到盂空餐雪麥，經傳金字坐雲松。","呻吟獨臥猷川水，振錫先聞長樂鐘。","回望羣山攜手處，離心一一涕無從。"]', '["連步青溪幾万重，有时共立在孤峯。","斋到盂空餐雪麦，經傳金字坐云松。","呻吟独臥猷川水，振錫先闻长乐鐘。","回望羣山携手处，離心一一涕無從。"]', '诗', 'shi', '', NULL, '猷川雪後送僧粲臨還京時避世臥疾 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3363fa1-91fa-4810-b7cf-161aad333d1c', '和李員外扈駕幸溫泉宮', '和李員外扈駕幸溫泉宮', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["未央月曉度疎鐘，鳳輦時巡出九重。","雪霽山門迎瑞日，雲開水殿候飛龍。","經寒不入宮中樹，佳氣常薰仗外峯。","遙羨枚臯扈仙蹕，偏承霄漢渥恩濃。"]', '["未央月晓度疎鐘，鳳輦时巡出九重。","雪霽山门迎瑞日，云开水殿候飞龙。","經寒不入宮中樹，佳氣常薰仗外峯。","遙羨枚臯扈仙蹕，偏承霄漢渥恩濃。"]', '诗', 'shi', '', NULL, '和李員外扈駕幸溫泉宮 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee331a15-7015-4bee-bac7-d0527b76fd7f', '長信怨', '长信怨', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["長信螢來一葉秋，蛾眉淚盡九重幽。","鳷鵲觀前明月度，芙蓉闕下絳河流。","鴛衾久別難爲夢，鳳管遙聞更起愁。","誰分昭陽夜歌舞，君王玉輦正淹留。"]', '["长信螢来一葉秋，蛾眉泪尽九重幽。","鳷鵲观前明月度，芙蓉闕下絳河流。","鴛衾久別难爲梦，鳳管遙闻更起愁。","誰分昭陽夜歌舞，君王玉輦正淹留。"]', '诗', 'shi', '', NULL, '長信怨 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33dedd52-529b-4ca2-a5b4-60893317358a', '送河南陸少府', '送河南陸少府', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["雲間陸生美且奇，銀章朱綬暎金羈。","自料抱材將致遠，寧嗟趨府暫牽卑。","東城社日催巢燕，上苑秋聲散御梨。","朝夕詔書還柏署，行看飛隼集高枝。"]', '["云间陸生美且奇，銀章朱綬暎金羈。","自料抱材將致远，寧嗟趨府暫牽卑。","东城社日催巢燕，上苑秋声散御梨。","朝夕詔书還柏署，行看飞隼集高枝。"]', '诗', 'shi', '', NULL, '送河南陸少府 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfabc25e-fd75-4b27-97cd-414d624a330b', '送李評事赴潭州使幕', '送李評事赴潭州使幕', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["湖南遠去有餘情，蘋葉初齊白芷生。","謾說簡書催物役，遙知心賞緩王程。","興過山寺先雲到，嘯引江帆帶月行。","幕下由來貴無事，佇聞談笑靜黎甿。"]', '["湖南远去有餘情，蘋葉初齊白芷生。","謾说簡书催物役，遙知心賞緩王程。","兴過山寺先云到，嘯引江帆带月行。","幕下由来貴無事，佇闻談笑静黎甿。"]', '诗', 'shi', '', NULL, '送李評事赴潭州使幕 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('527965e4-6f69-4397-9af0-fd9474e092e8', '送李九貶南陽', '送李九貶南陽', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["玉柱金罍醉不歡，雲山驛道向東看。","鴻聲斷續暮天遠，柳影蕭疎秋日寒。","霜降幽林霑蕙若，弦驚翰苑失鴛鸞。","秋來回首君門阻，馬上應歌行路難。"]', '["玉柱金罍醉不歡，云山驛道向东看。","鴻声斷續暮天远，柳影蕭疎秋日寒。","霜降幽林霑蕙若，弦驚翰苑失鴛鸾。","秋来回首君门阻，马上應歌行路难。"]', '诗', 'shi', '', NULL, '送李九貶南陽 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('902d6e35-87bd-4557-bc5a-003cacb20c3f', '送裴頔侍御使蜀', '送裴頔侍御使蜀', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["柱史纔年四十強，鬚髯玄髮美清揚。","朝天繡服乘恩貴，出使星軺滿路光。","錦水繁花添麗藻，峨嵋明月引飛觴。","多才自有雲霄望，計日應追鴛鷺行。"]', '["柱史纔年四十強，鬚髯玄髮美清揚。","朝天繡服乘恩貴，出使星軺满路光。","錦水繁花添丽藻，峨嵋明月引飞觴。","多才自有云霄望，計日應追鴛鷺行。"]', '诗', 'shi', '', NULL, '送裴頔侍御使蜀 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57a1cf23-a1e4-47eb-b08d-36631dd271ca', '送韋信愛子歸覲', '送韋信愛子归覲', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["離舟解纜到斜暉，春水東流燕北飛。","才子學詩趨露冕，棠花含笑待斑衣。","稍聞江樹啼猨近，轉覺山林過客稀。","借問還珠盈合浦，何如鯉也入庭闈。"]', '["離舟解纜到斜暉，春水东流燕北飞。","才子学诗趨露冕，棠花含笑待斑衣。","稍闻江樹啼猨近，轉覺山林過客稀。","借问還珠盈合浦，何如鯉也入庭闈。"]', '诗', 'shi', '', NULL, '送韋信愛子歸覲 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b004bc6-935f-4859-9d56-a93f45b698e3', '送興平王少府遊梁', '送兴平王少府游梁', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["舊識相逢情更親，攀歡甚少愴離頻。","黃綬罷來多遠客，青山何處不愁人。","日斜官樹聞蟬滿，雨過關城見月新。","梁國遺風重詞賦，諸侯應念馬卿貧。"]', '["旧識相逢情更親，攀歡甚少愴離頻。","黄綬罷来多远客，青山何处不愁人。","日斜官樹闻蟬满，雨過关城见月新。","梁国遺风重词賦，諸侯應念马卿貧。"]', '诗', 'shi', '', NULL, '送興平王少府遊梁 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e03a8de-bba1-46b9-869b-5eb61b3850a4', '送張員外出牧岳州', '送張員外出牧岳州', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["鳳凰銜詔與何人，善政多才寵寇恂。","臺上鴛鸞爭送遠，岳陽雲樹待行春。","自憐黃閣知音在，不厭彤幨出守頻。","應笑馮唐衰且拙，世情相見白頭新。"]', '["鳳凰銜詔與何人，善政多才寵寇恂。","台上鴛鸾爭送远，岳陽云樹待行春。","自怜黄閣知音在，不厭彤幨出守頻。","應笑馮唐衰且拙，世情相见白头新。"]', '诗', 'shi', '', NULL, '送張員外出牧岳州 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc49f117-2ca9-4e87-bf92-b7a93c4f37f3', '送孫十尉溫縣', '送孫十尉溫縣', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["飛花落絮滿河橋，千里傷心送客遙。","不惜芸香染黃綬，惟憐鴻羽下青霄。","雲衢有志終驤首，吏道無媒且折腰。","急管繁弦催一醉，頹陽不駐引征鑣。"]', '["飞花落絮满河橋，千里傷心送客遙。","不惜芸香染黄綬，惟怜鴻羽下青霄。","云衢有志終驤首，吏道無媒且折腰。","急管繁弦催一醉，頹陽不駐引征鑣。"]', '诗', 'shi', '', NULL, '送孫十尉溫縣 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0adb2c4d-8ba5-4029-9f06-9254dd8d6172', '送鍾評事應宏詞下第東歸', '送鍾評事應宏词下第东归', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["芳歲歸人嗟轉蓬，含情回首灞陵東。","蛾眉不入秦臺鏡，鷁羽還驚宋國風。","世事悠揚春夢裏，年光寂寞旅愁中。","勸君稍盡離筵酒，千里佳期難再同。"]', '["芳歲归人嗟轉蓬，含情回首灞陵东。","蛾眉不入秦台镜，鷁羽還驚宋国风。","世事悠揚春梦裏，年光寂寞旅愁中。","勸君稍尽離筵酒，千里佳期难再同。"]', '诗', 'shi', '', NULL, '送鍾評事應宏詞下第東歸 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb486444-73c0-4e6f-9a77-033bb7454764', '送嚴維尉河南', '送嚴維尉河南', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["蕙葉青青花亂開，少年趨府下蓬萊。","甘泉未獻揚雄賦，吏道何勞賈誼才。","征陌獨愁飛蓋遠，離筵只惜暝鐘催。","欲知別後相思處，願植瓊枝向柏臺。"]', '["蕙葉青青花亂开，少年趨府下蓬萊。","甘泉未獻揚雄賦，吏道何勞賈誼才。","征陌独愁飞蓋远，離筵只惜暝鐘催。","欲知別後相思处，願植瓊枝向柏台。"]', '诗', 'shi', '', NULL, '送嚴維尉河南 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adfe6e15-6cce-4379-bc88-d77b442bc2ef', '送馬員外拜官覲省', '送马員外拜官覲省', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["二十爲郎事漢文，鴛雛驥子自爲羣。","筆精已許臺中妙，劒術還令世上聞。","歸覲屢經槐里月，出師常笑棘門軍。","莫言來往朝天遠，看取鳴鞘入斷雲。"]', '["二十爲郎事漢文，鴛雛驥子自爲羣。","笔精已許台中妙，劒術還令世上闻。","归覲屢經槐里月，出師常笑棘门軍。","莫言来往朝天远，看取鳴鞘入斷云。"]', '诗', 'shi', '', NULL, '送馬員外拜官覲省 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cbbbeb3-f615-43dd-88c9-7fea8fbe1aab', '送冷朝陽擢第後歸金陵覲省', '送冷朝陽擢第後归金陵覲省', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["萊子晝歸今始好，潘園景色夏偏濃。","夕陽流水吟詩去，明月青山出竹逢。","兄弟相歡初讓果，鄉人爭賀舊登龍。","佳期少別俄千里，雲樹愁看過幾重。"]', '["萊子晝归今始好，潘园景色夏偏濃。","夕陽流水吟诗去，明月青山出竹逢。","兄弟相歡初讓果，乡人爭賀旧登龙。","佳期少別俄千里，云樹愁看過幾重。"]', '诗', 'shi', '', NULL, '送冷朝陽擢第後歸金陵覲省 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e68121e3-9861-445c-ad71-53ef99bf90e1', '九日宴浙江西亭', '九日宴浙江西亭', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["詩人九日憐芳菊，筵客高齋宴浙江。","漁浦浪花搖素壁，西陵樹色入秋窗。","木奴向熟懸金實，桑落新開瀉玉缸。","四子醉時爭講習，笑論黃霸舊爲邦。"]', '["诗人九日怜芳菊，筵客高斋宴浙江。","漁浦浪花搖素壁，西陵樹色入秋窗。","木奴向熟懸金實，桑落新开瀉玉缸。","四子醉时爭講習，笑論黄霸旧爲邦。"]', '诗', 'shi', '', NULL, '九日宴浙江西亭 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12ee4679-d01b-40c7-95aa-5a419bf96aff', '和王員外雪晴早朝', '和王員外雪晴早朝', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["紫微晴雪帶恩光，繞仗偏隨鴛鷺行。","長信月留寧避曉，宜春花滿不飛香。","獨看積素凝清禁，已覺輕寒讓太陽。","題柱盛名兼絕唱，風流誰繼漢田郎。"]', '["紫微晴雪带恩光，繞仗偏隨鴛鷺行。","长信月留寧避晓，宜春花满不飞香。","独看積素凝清禁，已覺轻寒讓太陽。","題柱盛名兼絕唱，风流誰繼漢田郎。"]', '诗', 'shi', '', NULL, '和王員外雪晴早朝 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('526e8971-c795-45e2-9e36-d62771bd67b6', '避暑納涼', '避暑納涼', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["木槿花開畏日長，時搖輕扇倚繩牀。","初晴草蔓緣新筍，頻雨苔衣染舊牆。","十旬河朔應虛醉，八柱天台好納涼。","無事始然知靜勝，深垂紗帳詠滄浪。"]', '["木槿花开畏日长，时搖轻扇倚繩牀。","初晴草蔓緣新筍，頻雨苔衣染旧牆。","十旬河朔應虛醉，八柱天台好納涼。","無事始然知静勝，深垂紗帳詠滄浪。"]', '诗', 'shi', '', NULL, '避暑納涼 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a049502-7724-450f-9ca4-d1a5d9fc0677', '早夏', '早夏', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["楚狂身世恨情多，似病如憂正是魔。","花萼敗春多寂寞，葉陰迎夏已清和。","鸝黃好鳥搖深樹，細白佳人著紫羅。","軍旅閱詩裁不得，可憐風景遣如何。"]', '["楚狂身世恨情多，似病如憂正是魔。","花萼敗春多寂寞，葉陰迎夏已清和。","鸝黄好鸟搖深樹，細白佳人著紫羅。","軍旅閱诗裁不得，可怜风景遣如何。"]', '诗', 'shi', '', NULL, '早夏 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d210949-8fc9-490f-b130-12b2cbeb3243', '題嵩陽焦道士石壁', '題嵩陽焦道士石壁', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["三峯花畔碧堂懸，錦里真人此得仙。","玉體纔飛西蜀雨，霓裳欲向大羅天。","彩雲不散燒丹竈，白鹿時藏種玉田。","幸入桃源因去世，方期丹訣一延年。"]', '["三峯花畔碧堂懸，錦里真人此得仙。","玉體纔飞西蜀雨，霓裳欲向大羅天。","彩云不散燒丹竈，白鹿时藏種玉田。","幸入桃源因去世，方期丹訣一延年。"]', '诗', 'shi', '', NULL, '題嵩陽焦道士石壁 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b1ba89a-046a-4f9b-a38f-f619d1f85a52', '題延州聖僧穴', '題延州聖僧穴', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["定力無涯不可稱，未知何代坐禪僧。","默默山門宵閉月，熒熒石壁晝然燈。","四時樹長書經葉，萬歲巖懸拄杖藤。","昔日捨身緣救鴿，今時出見有飛鷹。"]', '["定力無涯不可稱，未知何代坐禪僧。","默默山门宵閉月，熒熒石壁晝然灯。","四时樹长书經葉，万歲巖懸拄杖藤。","昔日捨身緣救鴿，今时出见有飞鷹。"]', '诗', 'shi', '', NULL, '題延州聖僧穴 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c666b745-582a-422d-ad62-82a63cdee472', '樂遊原晴望上中書李侍郎', '乐游原晴望上中书李侍郎', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["爽氣朝來萬里清，憑高一望九秋輕。","不知鳳沼霖初霽，但覺堯天日轉明。","四野山河通遠色，千家砧杵共秋聲。","遙想青雲丞相府，何時開閤引書生。"]', '["爽氣朝来万里清，憑高一望九秋轻。","不知鳳沼霖初霽，但覺堯天日轉明。","四野山河通远色，千家砧杵共秋声。","遙想青云丞相府，何时开閤引书生。"]', '诗', 'shi', '', NULL, '樂遊原晴望上中書李侍郎 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04cd52a7-6cc1-4fcf-8fb3-a15fa9f7a293', '幽居春暮書懷', '幽居春暮书懷', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["自哂鄙夫多野性，貧居數畝半臨湍。","谿雲雜雨來茅屋，山雀將雛到藥欄。","仙籙滿牀閑不厭，陰符在篋老羞看。","更憐童子宜春服，花裏尋師指杏壇。"]', '["自哂鄙夫多野性，貧居數畝半臨湍。","谿云杂雨来茅屋，山雀將雛到藥欄。","仙籙满牀闲不厭，陰符在篋老羞看。","更怜童子宜春服，花裏尋師指杏壇。"]', '诗', 'shi', '', NULL, '幽居春暮書懷 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c38d9a61-5006-4c44-855e-2a396d3c542d', '謁許由廟', '謁許由廟', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["故向箕山訪許由，林泉物外自清幽。","松上挂瓢枝幾變，石間洗耳水空流。","綠苔唯見遮三徑，青史空傳謝九州。","緬想古人增歎惜，颯然雲樹滿巖秋。"]', '["故向箕山訪許由，林泉物外自清幽。","松上挂瓢枝幾变，石间洗耳水空流。","綠苔唯见遮三徑，青史空傳謝九州。","緬想古人增歎惜，颯然云樹满巖秋。"]', '诗', 'shi', '', NULL, '謁許由廟 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db2bbc2b-6c36-45cc-afdd-8fb1f0bec4eb', '過張成侍御宅', '過張成侍御宅', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["丞相幕中題鳳人，文章心事每相親。","從軍誰謂仲宣樂，入室方知顏子貧。","杯裏紫茶香代酒，琴中綠水靜留賓。","欲知別後相思意，唯願瓊枝入夢頻。"]', '["丞相幕中題鳳人，文章心事每相親。","從軍誰謂仲宣乐，入室方知顏子貧。","杯裏紫茶香代酒，琴中綠水静留賓。","欲知別後相思意，唯願瓊枝入梦頻。"]', '诗', 'shi', '', NULL, '過張成侍御宅 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('456018c4-321c-48f3-bafd-9b7240e5587c', '酬考功楊員外見贈佳句', '酬考功楊員外见贈佳句', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["上林諫獵知才薄，尺組承恩愧命牽。","潢潦難滋滄海潤，螢光空盡太陽前。","虛名濫接登龍士，野性寧忘種黍田。","相國無私人守樸，何辭老去上皇年。"]', '["上林諫獵知才薄，尺組承恩愧命牽。","潢潦难滋滄海潤，螢光空尽太陽前。","虛名濫接登龙士，野性寧忘種黍田。","相国無私人守樸，何辞老去上皇年。"]', '诗', 'shi', '', NULL, '酬考功楊員外見贈佳句 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef32c93e-f044-4031-b566-3c4bd658a396', '寄永嘉王十二', '寄永嘉王十二', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["永嘉風景入新年，才子詩成定可憐。","夢裏還鄉不相見，天涯憶戴復誰傳。","花傾曉露垂如淚，鶯拂遊絲斷若弦。","願得回風吹海雁，飛書一宿到君邊。"]', '["永嘉风景入新年，才子诗成定可怜。","梦裏還乡不相见，天涯憶戴复誰傳。","花傾晓露垂如泪，鶯拂游絲斷若弦。","願得回风吹海雁，飞书一宿到君邊。"]', '诗', 'shi', '', NULL, '寄永嘉王十二 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ab8a9b1-54d3-4bc5-896b-29d69ee4641e', '七盤嶺阻寇聞李端公先到南楚', '七盤嶺阻寇闻李端公先到南楚', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["日暮窮途淚滿襟，雲天南望羨飛禽。","阮腸暗與孤鴻斷，江水遙連別恨深。","明月既能通憶夢，青山何用隔同心。","秦楚眼看成絕國，相思一寄白頭吟。"]', '["日暮窮途泪满襟，云天南望羨飞禽。","阮腸暗與孤鴻斷，江水遙連別恨深。","明月既能通憶梦，青山何用隔同心。","秦楚眼看成絕国，相思一寄白头吟。"]', '诗', 'shi', '', NULL, '七盤嶺阻寇聞李端公先到南楚 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09d05f44-f973-4257-810d-fc07960cefae', '酬趙給事相尋不遇留贈', '酬趙給事相尋不遇留贈', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["誰憶顏生窮巷裏，能勞馬跡破春苔。","忽看童子掃花處，始愧夕郎題鳳來。","斜景適隨詩興盡，好風纔送珮聲回。","豈無雞黍期他日，惜此殘春阻綠杯。"]', '["誰憶顏生窮巷裏，能勞马跡破春苔。","忽看童子掃花处，始愧夕郎題鳳来。","斜景適隨诗兴尽，好风纔送珮声回。","豈無雞黍期他日，惜此殘春阻綠杯。"]', '诗', 'shi', '', NULL, '酬趙給事相尋不遇留贈 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82a8441a-23a3-47c0-8470-6264e4a58486', '山中酬楊補闕見過', '山中酬楊補闕见過', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["日暖風恬種藥時，紅泉翠壁薜蘿垂。","幽溪鹿過苔還靜，深樹雲來鳥不知。","青瑣同心多逸興，春山載酒遠相隨。","却慙身外牽纓冕，未勝杯前倒接䍦。"]', '["日暖风恬種藥时，紅泉翠壁薜蘿垂。","幽溪鹿過苔還静，深樹云来鸟不知。","青瑣同心多逸兴，春山載酒远相隨。","却慙身外牽纓冕，未勝杯前倒接䍦。"]', '诗', 'shi', '', NULL, '山中酬楊補闕見過 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69438f82-ac49-4093-85d4-99095b68d968', '同王錥起居程浩郎中韓翃舍人題安國寺用上人院', '同王錥起居程浩郎中韓翃舍人題安国寺用上人院', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["慧眼沙門真遠公，經行宴坐有儒風。","香緣不絕簪裾會，禪想寧妨藻思通。","曙後鑪煙生不滅，晴來堦色並歸空。","狂夫入室無餘事，唯與天花一笑同。"]', '["慧眼沙门真远公，經行宴坐有儒风。","香緣不絕簪裾會，禪想寧妨藻思通。","曙後鑪煙生不滅，晴来堦色並归空。","狂夫入室無餘事，唯與天花一笑同。"]', '诗', 'shi', '', NULL, '同王錥起居程浩郎中韓翃舍人題安國寺用上人院 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de300810-8cb8-4686-9d07-3a07bd3d68bc', '尋司勳李郎中不遇', '尋司勳李郎中不遇', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["知己知音同舍郎，如何咫尺阻清揚。","每恨蒹葭傍芳樹，多慚新燕入華堂。","重花不隔陳蕃榻，修竹能深夫子牆。","唯有早朝趨鳳閤，朝時憐羽接鴛行。"]', '["知己知音同舍郎，如何咫尺阻清揚。","每恨蒹葭傍芳樹，多慚新燕入华堂。","重花不隔陳蕃榻，修竹能深夫子牆。","唯有早朝趨鳳閤，朝时怜羽接鴛行。"]', '诗', 'shi', '', NULL, '尋司勳李郎中不遇 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c1b9d40-b0ec-4079-a196-8bc53bb27fc4', '贈張南史', '贈張南史', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["紫泥何日到滄州，笑向東陽沈隱侯。","黛色晴峯雲外出，縠文江水縣前流。","使臣自欲論公道，才子非關厭薄遊。","溪畔秋蘭雖可佩，知君不得少停舟。"]', '["紫泥何日到滄州，笑向东陽沈隐侯。","黛色晴峯云外出，縠文江水縣前流。","使臣自欲論公道，才子非关厭薄游。","溪畔秋蘭雖可佩，知君不得少停舟。"]', '诗', 'shi', '', NULL, '贈張南史 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c03561b-a191-4c44-b2e5-e10adc3d4605', '暇日覽舊詩因以題詠', '暇日覽旧诗因以題詠', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["逍遙心地得關關，偶被功名涴我閑。","有壽亦將歸象外，無詩兼不戀人間。","何窮默識輕洪範，未喪斯文勝大還。","筐篋靜開難似此，蕊珠春色海中山。"]', '["逍遙心地得关关，偶被功名涴我闲。","有壽亦將归象外，無诗兼不戀人间。","何窮默識轻洪範，未喪斯文勝大還。","筐篋静开难似此，蕊珠春色海中山。"]', '诗', 'shi', '', NULL, '暇日覽舊詩因以題詠 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a8cfcc3-22c6-42f5-b021-fea5eb7e3081', '漢武出獵', '漢武出獵', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["漢家無事樂時雍，羽獵年年出九重。","玉帛不朝金闕路，旌旗長繞綵霞峰。","且貪原獸輕黃屋，寧畏漁人犯白龍。","薄暮方歸長樂觀，垂楊幾處綠烟濃。"]', '["漢家無事乐时雍，羽獵年年出九重。","玉帛不朝金闕路，旌旗长繞綵霞峰。","且貪原獸轻黄屋，寧畏漁人犯白龙。","薄暮方归长乐观，垂楊幾处綠烟濃。"]', '诗', 'shi', '', NULL, '漢武出獵 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b32f372-cbd1-4bfd-a495-4ff49fff4bef', '宴曹王宅', '宴曹王宅', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["賢王駟馬退朝初，小苑三春帶雨餘。","林沼葱蘢多貴氣，樓臺隱暎接天居。","仙雞引敵穿紅藥，宮燕銜泥落綺疏。","自歎平生相識願，何如今日廁應徐。"]', '["賢王駟马退朝初，小苑三春带雨餘。","林沼葱蘢多貴氣，楼台隐暎接天居。","仙雞引敵穿紅藥，宮燕銜泥落綺疏。","自歎平生相識願，何如今日廁應徐。"]', '诗', 'shi', '', NULL, '宴曹王宅 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dc6041e-860b-401c-b6f3-0543da9de095', '重贈趙給事', '重贈趙給事', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["久飛鴛掖出時髦，耻負平生稽古勞。","玉樹滿庭家轉貴，雲衢獨步位初高。","能迂騶馭尋蝸舍，不惜瑤華報木桃。","應念潛郎守貧病，常悲休沐對蓬蒿。"]', '["久飞鴛掖出时髦，耻負平生稽古勞。","玉樹满庭家轉貴，云衢独步位初高。","能迂騶馭尋蝸舍，不惜瑤华報木桃。","應念潛郎守貧病，常悲休沐对蓬蒿。"]', '诗', 'shi', '', NULL, '重贈趙給事 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42f17f00-bbc1-4b5b-82c1-3e9e012725ba', '贈闕下裴舍人', '贈闕下裴舍人', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["二月黃鶯飛上林，春城紫禁曉陰陰。","長樂鐘聲花外盡，龍池柳色雨中深。","陽和不散窮途恨，霄漢長懷捧日新。","獻賦十年猶未遇，羞將白髮對華簪。"]', '["二月黄鶯飞上林，春城紫禁晓陰陰。","长乐鐘声花外尽，龙池柳色雨中深。","陽和不散窮途恨，霄漢长懷捧日新。","獻賦十年猶未遇，羞將白髮对华簪。"]', '诗', 'shi', '', NULL, '贈闕下裴舍人 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11964ccb-20f2-4a42-9ae2-d6a3e11ef7dc', '登劉賓客高齋', '登劉賓客高斋', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["能以功成疎寵位，不將心賞負雲霞。","林間客散孫弘閣，城上山宜綺季家。","蝴蝶晴連池岸草，黃鸝晚出柳園花。","日陪鯉也趨文苑，誰道門生隔絳紗。"]', '["能以功成疎寵位，不將心賞負云霞。","林间客散孫弘閣，城上山宜綺季家。","蝴蝶晴連池岸草，黄鸝晚出柳园花。","日陪鯉也趨文苑，誰道门生隔絳紗。"]', '诗', 'shi', '', NULL, '登劉賓客高齋 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5a048bc-d553-4d3e-8133-a66fb269b879', '哭辛霽', '哭辛霽', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["流水辭山花別枝，隨風一去絕還期。","昨夜故人泉下宿，今朝白髮鏡中垂。","音徽寂寂空成夢，容範朝朝無見時。","旦暮餘生幾息在，不應存沒未嘗悲。"]', '["流水辞山花別枝，隨风一去絕還期。","昨夜故人泉下宿，今朝白髮镜中垂。","音徽寂寂空成梦，容範朝朝無见时。","旦暮餘生幾息在，不應存沒未嘗悲。"]', '诗', 'shi', '', NULL, '哭辛霽 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eff1088d-b577-4eef-af9a-5a4eaeec8c25', '和慕容法曹尋漁者寄城中故人', '和慕容法曹尋漁者寄城中故人', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["孤煙一點綠溪湄，漁父幽居即舊基。","飢鷺不驚收釣處，閑麛應乳負暄時。","茅齋對雪開尊好，穉子焚枯飯客遲。","勝事宛然懷抱裏，頃來新得謝公詩。"]', '["孤煙一点綠溪湄，漁父幽居即旧基。","飢鷺不驚收釣处，闲麛應乳負暄时。","茅斋对雪开尊好，穉子焚枯飯客遲。","勝事宛然懷抱裏，頃来新得謝公诗。"]', '诗', 'shi', '', NULL, '和慕容法曹尋漁者寄城中故人 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bafddb95-1efe-4217-93e4-9b3972338bc0', '山花', '山花', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["山花照塢復燒溪，樹樹枝枝盡可迷。","野客未來枝畔立，流鶯已向樹邊啼。","從容只是愁風起，眷戀常須向日西。","別有妖妍勝桃李，攀來折去亦成蹊。"]', '["山花照塢复燒溪，樹樹枝枝尽可迷。","野客未来枝畔立，流鶯已向樹邊啼。","從容只是愁风起，眷戀常須向日西。","別有妖妍勝桃李，攀来折去亦成蹊。"]', '诗', 'shi', '', NULL, '山花 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9d26f69-3e18-49a5-b5dd-06d1f3bb9436', '送楊著作歸東海', '送楊著作归东海', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["楊柳出關色，東行千里期。","酒酣暫輕別，路遠始相思。","欲識離心盡，斜陽到海時。"]', '["楊柳出关色，东行千里期。","酒酣暫轻別，路远始相思。","欲識離心尽，斜陽到海时。"]', '诗', 'shi', '', NULL, '送楊著作歸東海 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66d4ad7b-5e1e-400c-80c8-78c2a9f8333c', '送李協律還東京', '送李協律還东京', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["芳草忽無色，王孫復入關。","長河侵驛道，匹馬傍雲山。","愁見離居久，螢飛秋月閑。"]', '["芳草忽無色，王孫复入关。","长河侵驛道，匹马傍云山。","愁见離居久，螢飞秋月闲。"]', '诗', 'shi', '', NULL, '送李協律還東京 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('498451d1-f974-48a5-89a4-23f3b3b6ae19', '秋館言懷', '秋館言懷', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["蟋蟀已秋思，蕙蘭仍碧滋。","蹉跎獻賦客，歎息此良時。","日夕雲臺下，商歌空自悲。"]', '["蟋蟀已秋思，蕙蘭仍碧滋。","蹉跎獻賦客，歎息此良时。","日夕云台下，商歌空自悲。"]', '诗', 'shi', '', NULL, '秋館言懷 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc5e25c0-ab54-49e2-b2e6-1b243c97492e', '和劉明府宴縣前山亭', '和劉明府宴縣前山亭', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["城隅勞心處，雪後歲芳開。","山暎千花出，泉經萬井來。","翔鸞欲下舞，上客且留杯。"]', '["城隅勞心处，雪後歲芳开。","山暎千花出，泉經万井来。","翔鸾欲下舞，上客且留杯。"]', '诗', 'shi', '', NULL, '和劉明府宴縣前山亭 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9ae84e5-db56-4118-899e-9ceed7305800', '新雨喜得王卿書問', '新雨喜得王卿书问', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["苦雨暗秋徑，寒花垂紫苔。","愁中綠尊盡，夢裏故人來。","果有相思字，銀鉤新月開。"]', '["苦雨暗秋徑，寒花垂紫苔。","愁中綠尊尽，梦裏故人来。","果有相思字，銀鉤新月开。"]', '诗', 'shi', '', NULL, '新雨喜得王卿書問 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d38cd1a9-1a77-427f-8335-9900de6ef133', '賦得巢燕送客', '賦得巢燕送客', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["能棲杏梁際，不與黃雀羣。","夜影寄紅燭，朝飛高碧雲。","含情別故侶，花月惜春分。"]', '["能棲杏梁際，不與黄雀羣。","夜影寄紅燭，朝飞高碧云。","含情別故侶，花月惜春分。"]', '诗', 'shi', '', NULL, '賦得巢燕送客 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('461d3eec-5f92-4719-aeeb-78e90fa2cd53', '題張藍田訟堂', '題張藍田訟堂', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["角巾高枕向晴山，訟簡庭空不用關。","秋風窗下琴書靜，夜景門前人吏閑。","稍覺淵明歸思遠，東臯月出片雲還。"]', '["角巾高枕向晴山，訟簡庭空不用关。","秋风窗下琴书静，夜景门前人吏闲。","稍覺淵明归思远，东臯月出片云還。"]', '诗', 'shi', '', NULL, '題張藍田訟堂 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9954337-1b5e-429f-8f95-2981538834df', '江行無題一百首 一', '江行無題一百首 一', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["傾酒向漣漪，乘流東去時。","寸心同尺璧，投此報馮夷。"]', '["傾酒向漣漪，乘流东去时。","寸心同尺璧，投此報馮夷。"]', '诗', 'shi', '', NULL, '江行無題一百首 一 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dca3c00b-981f-4438-a463-af4241a73685', '江行無題一百首 二', '江行無題一百首 二', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["江曲全縈楚，雪飛半自秦。","峴山回首望，如別故關人。"]', '["江曲全縈楚，雪飞半自秦。","峴山回首望，如別故关人。"]', '诗', 'shi', '', NULL, '江行無題一百首 二 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('066880b9-50d7-4cdd-b469-c2397f84d0df', '江行無題一百首 三', '江行無題一百首 三', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["浦煙函夜色，冷日轉秋旻。","自有沈碑石，清光不照人。"]', '["浦煙函夜色，冷日轉秋旻。","自有沈碑石，清光不照人。"]', '诗', 'shi', '', NULL, '江行無題一百首 三 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e480fc9f-c04f-4c9e-a6f4-6d6b117ed1c4', '江行無題一百首 四', '江行無題一百首 四', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["楚岸雲空合，楚城人不來。","只今誰善舞，莫恨發陽臺。"]', '["楚岸云空合，楚城人不来。","只今誰善舞，莫恨發陽台。"]', '诗', 'shi', '', NULL, '江行無題一百首 四 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0247264f-83a0-4ecc-ba6a-52e0d9c6d80d', '江行無題一百首 五', '江行無題一百首 五', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["行背青山郭，吟當白露秋。","風流無屈宋，空詠古荆州。"]', '["行背青山郭，吟當白露秋。","风流無屈宋，空詠古荆州。"]', '诗', 'shi', '', NULL, '江行無題一百首 五 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1798fcfb-db04-4e2e-8eb0-e191e869662e', '江行無題一百首 六', '江行無題一百首 六', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["晚來漁父喜，罾重欲收遲。","恐有長江使，金錢願贖龜。"]', '["晚来漁父喜，罾重欲收遲。","恐有长江使，金錢願贖龟。"]', '诗', 'shi', '', NULL, '江行無題一百首 六 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb2de258-03b2-4ce0-8eef-eab5466be8cd', '江行無題一百首 七', '江行無題一百首 七', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["去指龍沙路，徒懸象闕心。","夜涼無遠夢，不爲偶聞砧。"]', '["去指龙沙路，徒懸象闕心。","夜涼無远梦，不爲偶闻砧。"]', '诗', 'shi', '', NULL, '江行無題一百首 七 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9008e72-9fb6-466f-8a7d-45e360c3ceab', '江行無題一百首 八', '江行無題一百首 八', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["霽雲疎有葉，雨浪細無花。","穩放扁舟去，江天自有涯。"]', '["霽云疎有葉，雨浪細無花。","穩放扁舟去，江天自有涯。"]', '诗', 'shi', '', NULL, '江行無題一百首 八 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7d1b5b1-2eb2-43f7-b6b9-4622b89328d4', '江行無題一百首 九', '江行無題一百首 九', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["好日當秋半，層波動旅腸。","已行千里外，誰與共秋光。"]', '["好日當秋半，層波动旅腸。","已行千里外，誰與共秋光。"]', '诗', 'shi', '', NULL, '江行無題一百首 九 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('354a2455-baa5-44c0-b715-32db5623e31d', '江行無題一百首 十', '江行無題一百首 十', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["潤色非東里，官曹更建章。","宦遊難自定，來喚櫂船郎。"]', '["潤色非东里，官曹更建章。","宦游难自定，来喚櫂船郎。"]', '诗', 'shi', '', NULL, '江行無題一百首 十 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9efe7a9d-f1a2-4a46-baee-e920cc1bb585', '江行無題一百首 十一', '江行無題一百首 十一', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["夜江清未曉，徒惜月光沈。","不是因行樂，堪傷老大心。"]', '["夜江清未晓，徒惜月光沈。","不是因行乐，堪傷老大心。"]', '诗', 'shi', '', NULL, '江行無題一百首 十一 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd1f32cc-2635-4f4f-9aee-c0838a4641aa', '江行無題一百首 十二', '江行無題一百首 十二', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["翳日多喬木，維舟取束薪。","靜聽江叟語，俱是厭兵人。"]', '["翳日多喬木，維舟取束薪。","静听江叟語，俱是厭兵人。"]', '诗', 'shi', '', NULL, '江行無題一百首 十二 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c34f8f3b-b66e-422a-9681-8c2793dd2c8b', '江行無題一百首 十三', '江行無題一百首 十三', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["箭漏日初短，汀煙草未衰。","雨餘雖更綠，不是采蘋時。"]', '["箭漏日初短，汀煙草未衰。","雨餘雖更綠，不是采蘋时。"]', '诗', 'shi', '', NULL, '江行無題一百首 十三 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1fd20a8-7b31-4be6-b52c-50ca1cacc781', '江行無題一百首 十四', '江行無題一百首 十四', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["山雨夜來漲，喜魚跳滿江。","岸沙平欲盡，垂蓼入船窗。"]', '["山雨夜来漲，喜鱼跳满江。","岸沙平欲尽，垂蓼入船窗。"]', '诗', 'shi', '', NULL, '江行無題一百首 十四 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b3bb07b-f7fc-4f95-9fe4-1894cd89f90b', '江行無題一百首 十五', '江行無題一百首 十五', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["渚邊新雁下，舟上獨淒涼。","俱是南來客，憐君綴一行。"]', '["渚邊新雁下，舟上独淒涼。","俱是南来客，怜君綴一行。"]', '诗', 'shi', '', NULL, '江行無題一百首 十五 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f26fff9e-5bcc-44c9-a5d0-b2323c8c0f77', '江行無題一百首 十六', '江行無題一百首 十六', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["牽路沿江狹，沙崩岸不平。","盡知行處險，誰肯載時輕。"]', '["牽路沿江狹，沙崩岸不平。","尽知行处險，誰肯載时轻。"]', '诗', 'shi', '', NULL, '江行無題一百首 十六 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96b815a7-4598-4f97-bd81-27b1b926bfeb', '江行無題一百首 十七', '江行無題一百首 十七', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["雲密連江暗，風斜著物鳴。","一杯真戰將，笑爾作愁兵。"]', '["云密連江暗，风斜著物鳴。","一杯真戰將，笑爾作愁兵。"]', '诗', 'shi', '', NULL, '江行無題一百首 十七 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f87da9b-d715-4bc5-8ab8-319d5e0427a4', '江行無題一百首 十八', '江行無題一百首 十八', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["柳拂斜開路，籬邊數戶村。","可能還有意，不掩向江門。"]', '["柳拂斜开路，籬邊數戶村。","可能還有意，不掩向江门。"]', '诗', 'shi', '', NULL, '江行無題一百首 十八 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfac02cb-8b1a-4160-a8dd-ab5dbf02f247', '江行無題一百首 十九', '江行無題一百首 十九', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["不識桓公渴，徒吟子美詩。","江清唯獨看，心外更誰知。"]', '["不識桓公渴，徒吟子美诗。","江清唯独看，心外更誰知。"]', '诗', 'shi', '', NULL, '江行無題一百首 十九 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b5fd5f3-be0b-406d-afc1-4ceea464b034', '江行無題一百首 二十', '江行無題一百首 二十', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["憔悴異靈均，非讒作逐臣。","如逢漁父問，未是獨醒人。"]', '["憔悴異靈均，非讒作逐臣。","如逢漁父问，未是独醒人。"]', '诗', 'shi', '', NULL, '江行無題一百首 二十 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51acc5b7-2e40-4af4-8273-9ec745a3fa7b', '江行無題一百首 二十一', '江行無題一百首 二十一', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["水涵秋色靜，雲帶夕陽高。","詩癖非吾病，何妨吮短毫。"]', '["水涵秋色静，云带夕陽高。","诗癖非吾病，何妨吮短毫。"]', '诗', 'shi', '', NULL, '江行無題一百首 二十一 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27eac145-8bc9-4ad6-aa09-d39c3d63beea', '江行無題一百首 二十二', '江行無題一百首 二十二', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["登舟非古岸，還似阻西陵。","箕伯無多少，回頭詎不能。"]', '["登舟非古岸，還似阻西陵。","箕伯無多少，回头詎不能。"]', '诗', 'shi', '', NULL, '江行無題一百首 二十二 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12b892e7-6526-4ee4-89f4-eb79942c3148', '江行無題一百首 二十三', '江行無題一百首 二十三', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["帆翅初張處，雲鵬怒翼同。","莫愁千里路，自有到來風。"]', '["帆翅初張处，云鵬怒翼同。","莫愁千里路，自有到来风。"]', '诗', 'shi', '', NULL, '江行無題一百首 二十三 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a93db04-65b7-4609-ac1b-0c79b0384158', '江行無題一百首 二十四', '江行無題一百首 二十四', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["秋雲久無雨，江燕社猶飛。","却笑舟中客，今年未得歸。"]', '["秋云久無雨，江燕社猶飞。","却笑舟中客，今年未得归。"]', '诗', 'shi', '', NULL, '江行無題一百首 二十四 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8316417c-7ccf-4c24-a1ad-9900a18891c4', '江行無題一百首 二十五', '江行無題一百首 二十五', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["佳節雖逢菊，浮生正似萍。","故山何處望，荒岸小長亭。"]', '["佳節雖逢菊，浮生正似萍。","故山何处望，荒岸小长亭。"]', '诗', 'shi', '', NULL, '江行無題一百首 二十五 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8acb52b-3a97-4242-b9fb-72bb8ab45389', '江行無題一百首 二十六', '江行無題一百首 二十六', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["行到楚江岸，蒼茫人正迷。","秖知秦塞遠，格磔鷓鴣啼。"]', '["行到楚江岸，蒼茫人正迷。","秖知秦塞远，格磔鷓鴣啼。"]', '诗', 'shi', '', NULL, '江行無題一百首 二十六 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49d7fc45-498b-478f-b010-148e72262877', '江行無題一百首 二十七', '江行無題一百首 二十七', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["月下江流靜，村荒人語稀。","鷺鷥雖有伴，仍共影雙飛。"]', '["月下江流静，村荒人語稀。","鷺鷥雖有伴，仍共影雙飞。"]', '诗', 'shi', '', NULL, '江行無題一百首 二十七 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a556bfdf-a6ad-458d-9dee-2e4e1b6a5582', '江行無題一百首 二十八', '江行無題一百首 二十八', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["斗轉月未落，舟行夜已深。","有村知不遠，風便數聲砧。"]', '["斗轉月未落，舟行夜已深。","有村知不远，风便數声砧。"]', '诗', 'shi', '', NULL, '江行無題一百首 二十八 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ff5ac3c-c010-49c7-9d29-f5f60ff6e5df', '江行無題一百首 二十九', '江行無題一百首 二十九', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["櫂驚沙鳥迅，飛濺夕陽波。","不顧魚多處，應防一目羅。"]', '["櫂驚沙鸟迅，飞濺夕陽波。","不顧鱼多处，應防一目羅。"]', '诗', 'shi', '', NULL, '江行無題一百首 二十九 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a6b608c-491c-431f-836c-ec6069fd71c9', '江行無題一百首 三十', '江行無題一百首 三十', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["漸覺江天遠，難逢故國書。","可能無往事，空食鼎中魚。"]', '["漸覺江天远，难逢故国书。","可能無往事，空食鼎中鱼。"]', '诗', 'shi', '', NULL, '江行無題一百首 三十 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb79253f-28b5-4190-94e8-50d10c97bd5b', '江行無題一百首 三十一', '江行無題一百首 三十一', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["岸草連荒色，村聲樂稔年。","晚晴初穫稻，閑却采蓮船。"]', '["岸草連荒色，村声乐稔年。","晚晴初穫稻，闲却采蓮船。"]', '诗', 'shi', '', NULL, '江行無題一百首 三十一 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c248c958-dd2f-4921-844e-2b0d07a970b8', '江行無題一百首 三十二', '江行無題一百首 三十二', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["灘淺爭遊鷺，江清易見魚。","怪來吟未足，秋物欠紅蕖。"]', '["灘淺爭游鷺，江清易见鱼。","怪来吟未足，秋物欠紅蕖。"]', '诗', 'shi', '', NULL, '江行無題一百首 三十二 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a07de9ca-7fc1-42d0-816a-11bf68772fc8', '江行無題一百首 三十三', '江行無題一百首 三十三', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["蛩響依莎草，螢飛透水煙。","夜涼誰詠史，空泊運租船。"]', '["蛩响依莎草，螢飞透水煙。","夜涼誰詠史，空泊運租船。"]', '诗', 'shi', '', NULL, '江行無題一百首 三十三 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29d10afb-167b-4911-992f-953bc524b2cd', '江行無題一百首 三十四', '江行無題一百首 三十四', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["睡穩葉舟輕，風微浪不驚。","任君蘆葦岸，終夜動秋聲。"]', '["睡穩葉舟轻，风微浪不驚。","任君蘆葦岸，終夜动秋声。"]', '诗', 'shi', '', NULL, '江行無題一百首 三十四 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cfcf661-af73-4357-adb8-90fc89f732f7', '江行無題一百首 三十五', '江行無題一百首 三十五', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["自念平生意，曾期一郡符。","豈知因謫宦，斑鬢入江湖。"]', '["自念平生意，曾期一郡符。","豈知因謫宦，斑鬢入江湖。"]', '诗', 'shi', '', NULL, '江行無題一百首 三十五 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('955b7180-969b-4698-a5ef-d2a5c96451d2', '江行無題一百首 三十六', '江行無題一百首 三十六', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["煙渚復煙渚，畫屏休畫屏。","引愁天末去，數點暮山青。"]', '["煙渚复煙渚，畫屏休畫屏。","引愁天末去，數点暮山青。"]', '诗', 'shi', '', NULL, '江行無題一百首 三十六 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a24b7060-4a1b-4829-8ccf-d040f7e41fcf', '江行無題一百首 三十七', '江行無題一百首 三十七', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["水天涼夜月，不是惜清光。","好物隨人祕，秦淮憶建康。"]', '["水天涼夜月，不是惜清光。","好物隨人祕，秦淮憶建康。"]', '诗', 'shi', '', NULL, '江行無題一百首 三十七 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab54142f-68a2-456a-92ea-d4f6826537c6', '江行無題一百首 三十八', '江行無題一百首 三十八', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["古來多思客，搖落恨江潭。","今日秋風至，蕭疎獨沔南。"]', '["古来多思客，搖落恨江潭。","今日秋风至，蕭疎独沔南。"]', '诗', 'shi', '', NULL, '江行無題一百首 三十八 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a38f17bc-0465-48c4-8b37-782a8e59de5a', '江行無題一百首 三十九', '江行無題一百首 三十九', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["暎竹疑村好，穿蘆覺渚幽。","漸安無曠土，薑芋當農收。"]', '["暎竹疑村好，穿蘆覺渚幽。","漸安無曠土，薑芋當農收。"]', '诗', 'shi', '', NULL, '江行無題一百首 三十九 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b1b5adc-d4b9-44c6-b097-8bbbd11a62df', '江行無題一百首 四十', '江行無題一百首 四十', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["秋風動客心，寂寂不成吟。","飛上危檣立，啼烏報好音。"]', '["秋风动客心，寂寂不成吟。","飞上危檣立，啼烏報好音。"]', '诗', 'shi', '', NULL, '江行無題一百首 四十 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ee9124b-f8e7-4aac-b846-0117b2171621', '江行無題一百首 四十一', '江行無題一百首 四十一', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["見底高秋水，開懷萬里天。","旅吟還有伴，沙柳數枝蟬。"]', '["见底高秋水，开懷万里天。","旅吟還有伴，沙柳數枝蟬。"]', '诗', 'shi', '', NULL, '江行無題一百首 四十一 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d23ebcf-8141-4288-a6f3-e4e01ca8ef9a', '江行無題一百首 四十二', '江行無題一百首 四十二', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["九日自佳節，扁舟無一杯。","曹園舊尊酒，戲馬憶高臺。"]', '["九日自佳節，扁舟無一杯。","曹园旧尊酒，戲马憶高台。"]', '诗', 'shi', '', NULL, '江行無題一百首 四十二 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04bcbc77-4097-472c-a3d5-a4d8c21ac6a9', '江行無題一百首 四十三', '江行無題一百首 四十三', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["兵火有餘燼，貧村纔數家。","無人爭曉渡，殘月下寒沙。"]', '["兵火有餘燼，貧村纔數家。","無人爭晓渡，殘月下寒沙。"]', '诗', 'shi', '', NULL, '江行無題一百首 四十三 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b9fb9d0-0521-4f02-8f34-74943fabc134', '江行無題一百首 四十四', '江行無題一百首 四十四', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["渚禽菱芡足，不向稻粱爭。","靜宿涼灣月，應無失侶聲。"]', '["渚禽菱芡足，不向稻粱爭。","静宿涼灣月，應無失侶声。"]', '诗', 'shi', '', NULL, '江行無題一百首 四十四 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4cc0a52-7920-4761-a653-c3df127cd4aa', '江行無題一百首 四十五', '江行無題一百首 四十五', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["輕雲未護霜，樹杪橘初黃。","信是知名物，微風過水香。"]', '["轻云未護霜，樹杪橘初黄。","信是知名物，微风過水香。"]', '诗', 'shi', '', NULL, '江行無題一百首 四十五 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7536ba5-753e-4e99-b8ee-3a50c2eb0a79', '江行無題一百首 四十六', '江行無題一百首 四十六', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["渺渺望天涯，清漣浸赤霞。","難逢星漢使，烏鵲日乘槎。"]', '["渺渺望天涯，清漣浸赤霞。","难逢星漢使，烏鵲日乘槎。"]', '诗', 'shi', '', NULL, '江行無題一百首 四十六 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb8871e5-463f-4938-b81e-02055b78f8b3', '江行無題一百首 四十七', '江行無題一百首 四十七', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["土曠深耕少，江平遠釣多。","生平皆棄本，金革竟如何。"]', '["土曠深耕少，江平远釣多。","生平皆棄本，金革竟如何。"]', '诗', 'shi', '', NULL, '江行無題一百首 四十七 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81ccc894-ee3e-4860-bf31-d158c6468751', '江行無題一百首 四十八', '江行無題一百首 四十八', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["海月非常物，等閑不可尋。","披沙應有地，淺處定無金。"]', '["海月非常物，等闲不可尋。","披沙應有地，淺处定無金。"]', '诗', 'shi', '', NULL, '江行無題一百首 四十八 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('886af2c8-32c9-4c69-a6f1-875b96ae75f6', '江行無題一百首 四十九', '江行無題一百首 四十九', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["風晚冷颼颼，蘆花已白頭。","舊來紅葉寺，堪憶玉京秋。"]', '["风晚冷颼颼，蘆花已白头。","旧来紅葉寺，堪憶玉京秋。"]', '诗', 'shi', '', NULL, '江行無題一百首 四十九 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fd941af-cdd1-4a75-a0e3-e80fa2d164b6', '江行無題一百首 五十', '江行無題一百首 五十', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["風好來無陣，雲閑去有蹤。","釣歌無遠近，應喜罷艨艟。"]', '["风好来無陣，云闲去有蹤。","釣歌無远近，應喜罷艨艟。"]', '诗', 'shi', '', NULL, '江行無題一百首 五十 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec1f2d9c-2c0e-4cf6-918f-6acc281e325c', '江行無題一百首 五十一', '江行無題一百首 五十一', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["吳疆連楚甸，楚俗異吳鄉。","漫把尊中物，無人啄蟹筐。"]', '["吳疆連楚甸，楚俗異吳乡。","漫把尊中物，無人啄蟹筐。"]', '诗', 'shi', '', NULL, '江行無題一百首 五十一 錢起 shi');
